/**
 * Validates mandatory production secrets and rejects insecure placeholders.
 * Exported for isolated automated testing.
 */
export function validateProductionSecrets(env: NodeJS.ProcessEnv = process.env): { isValid: boolean; errors: string[] } {
  const isProd = env.NODE_ENV === "production";
  const errors: string[] = [];

  if (isProd) {
    const accessSec = (env.JWT_SECRET || env.JWT_ACCESS_SECRET || "").trim();
    if (!accessSec) {
      errors.push("Missing mandatory production secret: JWT_SECRET (or JWT_ACCESS_SECRET).");
    } else {
      if (accessSec.length < 32) {
        errors.push("JWT_SECRET must be at least 32 characters in production.");
      }
      if (accessSec.includes("super_secure_key") || accessSec.includes("default") || accessSec.includes("change_me")) {
        errors.push("Insecure placeholder secret detected in JWT_SECRET.");
      }
    }

    const refreshSec = (env.JWT_REFRESH_SECRET || "").trim();
    if (!refreshSec) {
      errors.push("Missing mandatory production secret: JWT_REFRESH_SECRET.");
    } else {
      if (refreshSec.length < 32) {
        errors.push("JWT_REFRESH_SECRET must be at least 32 characters in production.");
      }
      if (refreshSec.includes("super_secure_key") || refreshSec.includes("default") || refreshSec.includes("change_me")) {
        errors.push("Insecure placeholder secret detected in JWT_REFRESH_SECRET.");
      }
    }

    // In production, validate integration secrets if configured or if external services are enabled
    const paySec = (env.PAYMENT_PROVIDER_SECRET || "").trim();
    if (paySec) {
      if (paySec.length < 16 || paySec.includes("rzp_sec_live_99a823bf8912") || paySec.includes("dev_test_")) {
        errors.push("Insecure placeholder or weak secret detected in PAYMENT_PROVIDER_SECRET.");
      }
    }

    const payWhSec = (env.PAYMENT_WEBHOOK_SECRET || "").trim();
    if (payWhSec) {
      if (payWhSec.length < 16 || payWhSec.includes("rzp_whsec_live_default_hmac_secret_2026") || payWhSec.includes("dev_test_")) {
        errors.push("Insecure placeholder or weak secret detected in PAYMENT_WEBHOOK_SECRET.");
      }
    }

    const notifSec = (env.NOTIFICATION_SERVICE_SECRET || "").trim();
    if (notifSec) {
      if (notifSec.includes("a2z_notif_sec_2026_production_auth_key") || notifSec.includes("dev_test_")) {
        errors.push("Insecure placeholder secret detected in NOTIFICATION_SERVICE_SECRET.");
      }
    }

    const storageSec = (env.STORAGE_SERVICE_SECRET || "").trim();
    if (storageSec) {
      if (storageSec.includes("a2z_storage_sec_2026_presigned_url_token") || storageSec.includes("dev_test_")) {
        errors.push("Insecure placeholder secret detected in STORAGE_SERVICE_SECRET.");
      }
    }
  }

  return { isValid: errors.length === 0, errors };
}

// Validate production secrets immediately on process load
const secretValidation = validateProductionSecrets();
if (!secretValidation.isValid) {
  console.error("================================================================");
  console.error("[FATAL SECURITY ERROR] Missing or insecure production configuration:");
  for (const err of secretValidation.errors) {
    console.error(`  - ${err}`);
  }
  console.error("Application startup aborted to prevent insecure operation.");
  console.error("================================================================");
  process.exit(1);
}

