/**
 * Evaluates whether an incoming HTTP Origin is approved under CORS policy.
 * Exported for deterministic automated verification.
 */
export function isAllowedCorsOrigin(
  requestOrigin: string | undefined,
  allowedOrigins: string[],
  isProductionMode: boolean
): boolean {
  // Allow requests without Origin (e.g. mobile apps, curl, native tools, same-origin server calls)
  if (!requestOrigin) return true;

  const normalized = requestOrigin.trim().toLowerCase();
  if (allowedOrigins.includes(normalized)) return true;

  // In non-production, permit standard localhost/127.0.0.1 origins if no explicit allowlist provided
  if (!isProductionMode && allowedOrigins.length === 0) {
    const defaultDevOrigins = [
      "http://localhost:3000",
      "http://localhost:5173",
      "http://127.0.0.1:3000",
      "http://127.0.0.1:5173"
    ];
    return defaultDevOrigins.includes(normalized);
  }

  return false;
}

/**
 * Checks whether simulated OTP disclosure is permitted.
 * Strictly forbidden in production; requires explicit ALLOW_SIMULATED_OTP=true in non-production.
 */
export function isSimulatedOtpAllowed(env: NodeJS.ProcessEnv = process.env): boolean {
  return env.NODE_ENV !== "production" && env.ALLOW_SIMULATED_OTP === "true";
}

/**
 * Parses and validates time duration strings (e.g., '15m', '1h', '7d')
 * within strict security bounds.
 */
function parseAndValidateDuration(
  value: string | undefined,
  fallback: string,
  minMs: number,
  maxMs: number,
  label: string
): { expiryString: string; durationMs: number } {
  function toMs(str: string): number {
    const match = /^(\d+)\s*(s|m|h|d|w)?$/i.exec(str.trim());
    if (!match) return 0;
    const amount = parseInt(match[1], 10);
    const unit = (match[2] || 's').toLowerCase();
    switch (unit) {
      case 's': return amount * 1000;
      case 'm': return amount * 60 * 1000;
      case 'h': return amount * 60 * 60 * 1000;
      case 'd': return amount * 24 * 60 * 60 * 1000;
      case 'w': return amount * 7 * 24 * 60 * 60 * 1000;
      default: return amount * 1000;
    }
  }

  const fallbackMs = toMs(fallback);
  if (!value || typeof value !== 'string') {
    return { expiryString: fallback, durationMs: fallbackMs };
  }

  const trimmed = value.trim();
  const parsedMs = toMs(trimmed);

  // Validate format and boundaries
  if (parsedMs <= 0 || parsedMs < minMs || parsedMs > maxMs) {
    return { expiryString: fallback, durationMs: fallbackMs };
  }

  return { expiryString: trimmed, durationMs: parsedMs };
}

// Access token: min 1 min (60s), max 24 hours (86400s), default 15m
const accessExpiryConfig = parseAndValidateDuration(
  process.env.JWT_ACCESS_EXPIRES_IN,
  "15m",
  60 * 1000,
  24 * 60 * 60 * 1000,
  "JWT_ACCESS_EXPIRES_IN"
);
const JWT_ACCESS_EXPIRY = accessExpiryConfig.expiryString;
const JWT_ACCESS_EXPIRY_MS = accessExpiryConfig.durationMs;

// Refresh token: min 1 hour (3600s), max 30 days, default 7d
const refreshExpiryConfig = parseAndValidateDuration(
  process.env.JWT_REFRESH_EXPIRES_IN,
  "7d",
  60 * 60 * 1000,
  30 * 24 * 60 * 60 * 1000,
  "JWT_REFRESH_EXPIRES_IN"
);
const JWT_REFRESH_EXPIRY = refreshExpiryConfig.expiryString;
const JWT_REFRESH_EXPIRY_MS = refreshExpiryConfig.durationMs;

// Server-side Integration Secrets (strict zero-hardcode policy in production)
const PAYMENT_PROVIDER_SECRET = process.env.PAYMENT_PROVIDER_SECRET || (isProduction ? "" : "dev_test_payment_provider_secret");
const PAYMENT_WEBHOOK_SECRET = process.env.PAYMENT_WEBHOOK_SECRET || (isProduction ? "" : "dev_test_payment_webhook_secret");
const NOTIFICATION_SERVICE_SECRET = process.env.NOTIFICATION_SERVICE_SECRET || (isProduction ? "" : "dev_test_notification_secret");
const STORAGE_SERVICE_SECRET = process.env.STORAGE_SERVICE_SECRET || (isProduction ? "" : "dev_test_storage_secret");

/**
 * Database connection resolver
 * Uses DATABASE_URL directly if available, or constructs it securely from individual parameters.
 */
function resolveDatabaseConfig(): { isConfigured: boolean; connectionType: 'URL' | 'SEPARATE' | 'IN_MEMORY' } {
  if (process.env.DATABASE_URL && process.env.DATABASE_URL.trim().length > 0) {
    return { isConfigured: true, connectionType: 'URL' };
  }
  if (process.env.DB_HOST && process.env.DB_USER && process.env.DB_NAME) {
    return { isConfigured: true, connectionType: 'SEPARATE' };
  }
  return { isConfigured: false, connectionType: 'IN_MEMORY' };
}
const dbConfigStatus = resolveDatabaseConfig();

