// Helper: Calculate late payment wallet penalty points
export function calculateLatePaymentPenalty(
  creditPeriodDays: number,
  actualPaidDay: number,
  approvedGraceDays: number,
  policy: LatePaymentPolicyConfigEntity = latePaymentPolicyConfigDb
): {
  totalLateDays: number;
  standardLateDays: number;
  graceDaysApplied: number;
  standardPenalty: number;
  gracePenalty: number;
  totalDeduction: number;
} {
  if (actualPaidDay <= creditPeriodDays) {
    return {
      totalLateDays: 0,
      standardLateDays: 0,
      graceDaysApplied: 0,
      standardPenalty: 0,
      gracePenalty: 0,
      totalDeduction: 0
    };
  }

  const totalLateDays = actualPaidDay - creditPeriodDays;
  const graceDaysApplied = Math.min(totalLateDays, Math.max(0, approvedGraceDays));
  const standardLateDays = totalLateDays - graceDaysApplied;

  const standardPenalty = standardLateDays * policy.standardLatePenaltyPointsPerDay;
  const gracePenalty = graceDaysApplied * policy.approvedGracePenaltyPointsPerDay;
  const totalDeduction = Math.round((standardPenalty + gracePenalty) * 100) / 100;

  return {
    totalLateDays,
    standardLateDays,
    graceDaysApplied,
    standardPenalty,
    gracePenalty,
    totalDeduction
  };
}

// Helper: Calculate 2% Pay Now discount breakdown
export function calculatePayNowBreakdown(subtotal: number, gstRate: number = 0.12, coldChainFee: number = 0) {
  const discountPercent = 2.0;
  const discountAmount = Math.round(subtotal * 0.02 * 100) / 100;
  const subtotalAfterDiscount = Math.round((subtotal - discountAmount) * 100) / 100;
  const gstAmount = Math.round(subtotalAfterDiscount * gstRate * 100) / 100;
  const finalPayableAmount = Math.round((subtotalAfterDiscount + gstAmount + coldChainFee) * 100) / 100;

  return {
    originalAmount: subtotal,
    discountPercent,
    discountAmount,
    subtotalAfterDiscount,
    gstAmount,
    coldChainFee,
    finalPayableAmount
  };
}

