// ----------------------------------------------------------------------------
// SERVER-SIDE CORE ENGINES: COVERAGE, HEALTH SCORE & SCHEDULE GENERATORS
// ----------------------------------------------------------------------------

/**
 * 1. Calculate Equipment Coverage State & Active Contract Record
 * Evaluates contract records chronologically, checks current timestamp against
 * expiration windows, and determines coverage state.
 */
export function calculateEquipmentCoverage(equipmentId: string): {
  coverageState: string;
  activeCoverage?: CoverageRecordEntity;
  allCoverages: CoverageRecordEntity[];
} {
  const records = coveragesDb.filter(c => c.equipmentId === equipmentId);
  if (records.length === 0) {
    return {
      coverageState: "NO_ACTIVE_COVERAGE",
      allCoverages: []
    };
  }

  const now = new Date().getTime();
  const EXPIRING_SOON_THRESHOLD_DAYS = 60; // Configurable threshold (60 days)
  const EXPIRING_SOON_THRESHOLD_MS = EXPIRING_SOON_THRESHOLD_DAYS * 24 * 60 * 60 * 1000;

  // Sort by endDate descending
  const sorted = [...records].sort((a, b) => new Date(b.endDate).getTime() - new Date(a.endDate).getTime());
  
  // Find active or currently valid coverage
  const active = sorted.find(c => {
    const start = new Date(c.startDate).getTime();
    const end = new Date(c.endDate).getTime();
    return now >= start && now <= end;
  });

  if (!active) {
    // Check if the most recent ended recently (Expired)
    const latest = sorted[0];
    if (latest.coverageType === "WARRANTY") {
      return { coverageState: "WARRANTY_EXPIRED", activeCoverage: undefined, allCoverages: sorted };
    } else if (latest.coverageType === "AMC") {
      return { coverageState: "AMC_EXPIRED", activeCoverage: undefined, allCoverages: sorted };
    } else if (latest.coverageType === "CMC") {
      return { coverageState: "CMC_EXPIRED", activeCoverage: undefined, allCoverages: sorted };
    }
    return { coverageState: "NO_ACTIVE_COVERAGE", activeCoverage: undefined, allCoverages: sorted };
  }

  const endMs = new Date(active.endDate).getTime();
  const isExpiringSoon = (endMs - now) <= EXPIRING_SOON_THRESHOLD_MS;

  let state = "NO_ACTIVE_COVERAGE";
  if (active.coverageType === "WARRANTY") {
    state = isExpiringSoon ? "WARRANTY_EXPIRING_SOON" : "UNDER_WARRANTY";
  } else if (active.coverageType === "AMC") {
    state = isExpiringSoon ? "AMC_EXPIRING_SOON" : "UNDER_AMC";
  } else if (active.coverageType === "CMC") {
    state = isExpiringSoon ? "CMC_EXPIRING_SOON" : "UNDER_CMC";
  }

  return {
    coverageState: state,
    activeCoverage: active,
    allCoverages: sorted
  };
}

/**
 * 2. Calculate Server-Authoritative Equipment Health Score (0-100)
 * Evaluates on-time PM compliance, open service tickets, repeat faults,
 * failed checklist items, equipment age, and active coverage.
 */
export function calculateEquipmentHealthScore(equipmentId: string): {
  score: number;
  level: "HEALTHY" | "ATTENTION" | "AT_RISK" | "CRITICAL";
  colorClass: string;
  factors: Array<{ name: string; scoreImpact: number; detail: string; category: string }>;
  openTicketCount: number;
  lastCalculatedAt: string;
} {
  const eq = customerEquipmentDb.find(e => e.id === equipmentId);
  const tickets = serviceTicketsDb.filter(t => t.equipmentId === equipmentId);
  const pmWorkOrders = pmWorkOrdersDb.filter(p => p.equipmentId === equipmentId);
  const coverage = calculateEquipmentCoverage(equipmentId);

  let score = 100;
  const factors: Array<{ name: string; scoreImpact: number; detail: string; category: string }> = [];

  // A. PM Compliance Check
  const overduePms = pmWorkOrders.filter(p => p.status === "OVERDUE" || (p.status !== "COMPLETED" && p.status !== "CLOSED" && new Date(p.scheduledDueDate).getTime() < Date.now()));
  const completedOnTime = pmWorkOrders.filter(p => p.status === "COMPLETED" || p.status === "CLOSED");

  if (overduePms.length > 0) {
    const penalty = overduePms.length * 20;
    score -= penalty;
    factors.push({
      name: "Overdue Preventive Maintenance",
      scoreImpact: -penalty,
      detail: `${overduePms.length} scheduled PM cycle(s) overdue. Immediate calibration & service needed.`,
      category: "PM_COMPLIANCE"
    });
  } else if (completedOnTime.length > 0) {
    factors.push({
      name: "On-Time PM Compliance",
      scoreImpact: +10,
      detail: `All ${completedOnTime.length} previous maintenance milestones completed on time.`,
      category: "PM_COMPLIANCE"
    });
  }

  // B. Open Service Breakdown Tickets Check
  const openTickets = tickets.filter(t => !["CLOSED", "RESOLVED", "CANCELLED"].includes(t.status));
  const criticalTickets = openTickets.filter(t => t.priority === "CRITICAL" || t.priority === "HIGH");
  
  if (criticalTickets.length > 0) {
    const penalty = criticalTickets.length * 25;
    score -= penalty;
    factors.push({
      name: "Active Breakdown Service Tickets",
      scoreImpact: -penalty,
      detail: `${criticalTickets.length} High/Critical priority unresolved fault(s) currently open.`,
      category: "TICKET_HISTORY"
    });
  } else if (openTickets.length > 0) {
    const penalty = openTickets.length * 10;
    score -= penalty;
    factors.push({
      name: "Open Service Inquiries",
      scoreImpact: -penalty,
      detail: `${openTickets.length} standard priority ticket(s) currently in progress.`,
      category: "TICKET_HISTORY"
    });
  }

  // C. Repeat Faults within 90 days
  const ninetyDaysAgo = Date.now() - 90 * 24 * 60 * 60 * 1000;
  const recentTickets = tickets.filter(t => new Date(t.createdAt).getTime() >= ninetyDaysAgo);
  if (recentTickets.length >= 2) {
    score -= 15;
    factors.push({
      name: "Repeat Fault Recurrence (90 Days)",
      scoreImpact: -15,
      detail: `${recentTickets.length} fault tickets registered in the past 90 days indicating intermittent failure risk.`,
      category: "REPEAT_FAULTS"
    });
  }

  // D. Coverage State Impact
  if (coverage.coverageState === "NO_ACTIVE_COVERAGE" || coverage.coverageState === "WARRANTY_EXPIRED") {
    score -= 10;
    factors.push({
      name: "Uncovered / Expired Contract",
      scoreImpact: -10,
      detail: "No active AMC/CMC contract active. Spare parts replacement lead time prolonged.",
      category: "COVERAGE"
    });
  } else if (coverage.coverageState.includes("UNDER_")) {
    factors.push({
      name: "Active Comprehensive Coverage",
      scoreImpact: +5,
      detail: `Protected under active ${coverage.activeCoverage?.coverageType} contract with expedited SLA.`,
      category: "COVERAGE"
    });
  }

  // Bound score between 0 and 100
  score = Math.max(0, Math.min(100, score));

  let level: "HEALTHY" | "ATTENTION" | "AT_RISK" | "CRITICAL" = "HEALTHY";
  let colorClass = "text-emerald-700 bg-emerald-50 border-emerald-200";

  if (score >= 80) {
    level = "HEALTHY";
    colorClass = "text-emerald-700 bg-emerald-50 border-emerald-200";
  } else if (score >= 60) {
    level = "ATTENTION";
    colorClass = "text-blue-700 bg-blue-50 border-blue-200";
  } else if (score >= 40) {
    level = "AT_RISK";
    colorClass = "text-amber-700 bg-amber-50 border-amber-200";
  } else {
    level = "CRITICAL";
    colorClass = "text-rose-700 bg-rose-50 border-rose-200";
  }

  return {
    score,
    level,
    colorClass,
    factors,
    openTicketCount: openTickets.length,
    lastCalculatedAt: new Date().toISOString()
  };
}

/**
 * 3. Calculate Next Scheduled PM Due Date & Period Key
 */
export function calculateNextPmDueDate(
  lastDateStr: string,
  frequency: "MONTHLY" | "QUARTERLY" | "HALF_YEARLY" | "ANNUAL" | "CUSTOM_INTERVAL" | "USAGE_BASED"
): { nextDueDate: string; reminderWindowStartDate: string; periodKey: string } {
  const base = new Date(lastDateStr);
  let monthsToAdd = 3; // Default Quarterly

  if (frequency === "MONTHLY") monthsToAdd = 1;
  else if (frequency === "QUARTERLY") monthsToAdd = 3;
  else if (frequency === "HALF_YEARLY") monthsToAdd = 6;
  else if (frequency === "ANNUAL") monthsToAdd = 12;

  const nextDate = new Date(base);
  nextDate.setMonth(nextDate.getMonth() + monthsToAdd);

  const reminderDate = new Date(nextDate);
  reminderDate.setDate(reminderDate.getDate() - 30); // 30-day reminder window

  const year = nextDate.getFullYear();
  const q = Math.floor(nextDate.getMonth() / 3) + 1;
  const periodKey = `${year}-Q${q}`;

  return {
    nextDueDate: nextDate.toISOString().split("T")[0],
    reminderWindowStartDate: reminderDate.toISOString().split("T")[0],
    periodKey
  };
}

/**
 * 4. Automatic Engineer Assignment Engine
 * Selection Order:
 * 1. Model Qualification Match
 * 2. Territory / Region Match
 * 3. Active Availability Check
 * 4. Lowest Active Workload Balancing
 */
export function autoAssignBestEngineerForPm(equipment: any, customerAddress?: string): any | null {
  const qualified = engineerQualificationsDb.filter(eng => {
    if (!eng.isAvailable) return false;
    const matchesModel = eng.qualifiedModels.some((m: string) => 
      equipment.modelNumber?.toLowerCase().includes(m.toLowerCase()) || 
      equipment.equipmentName?.toLowerCase().includes(m.toLowerCase()) ||
      m.toLowerCase().includes(equipment.modelNumber?.toLowerCase())
    );
    return matchesModel;
  });

  if (qualified.length === 0) {
    // Fallback: pick any available engineer with lowest workload
    const available = engineerQualificationsDb.filter(e => e.isAvailable);
    if (available.length === 0) return null;
    available.sort((a, b) => a.activeWorkloadCount - b.activeWorkloadCount);
    return available[0];
  }

  // Sort by lowest active workload
  qualified.sort((a, b) => a.activeWorkloadCount - b.activeWorkloadCount);
  return qualified[0];
}


