    const batchStatus = validationResult.errorRows > 0 ? "VALIDATION_FAILED" : "READY_FOR_REVIEW";

    const requestingUser = usersDb.find(u => u.id === req.user?.id);
    const uName = requestingUser ? `${requestingUser.firstName} ${requestingUser.lastName}`.trim() : (req.user?.email || "Office Staff");

