  app.post("/api/v1/special-pricing/import/execute", authenticateJwt as any, requireRole(UserRoleType.SUPER_ADMIN, UserRoleType.OFFICE_ADMIN, UserRoleType.OFFICE_STAFF) as any, (req: AuthenticatedRequest, res) => {
    if (checkPostgresMutationGuard(res, "POST /api/v1/special-pricing/import/execute")) return;
    const { batchId, rows, mode = "CREATE_ONLY" } = req.body;
    let targetBatch = batchId ? priceContractImportBatchesDb.find(b => b.id === batchId) : undefined;
    let parsedRowsToImport = targetBatch?.parsedRows || [];

    if (parsedRowsToImport.length === 0 && Array.isArray(rows) && rows.length > 0) {
      const vResult = validatePriceContractImportRows(rows, mode as any, usersDb, productsDb, customerPriceRulesDb);
      parsedRowsToImport = vResult.validatedRows;
    }

    const rowsToProcess = parsedRowsToImport.filter((r: any) => r.isValid && (r.action === "CREATE" || r.action === "UPDATE"));
    let createdCount = 0;
    let updatedCount = 0;

    for (const r of rowsToProcess) {
      const existingRule = customerPriceRulesDb.find(
        (rule: any) =>
          rule.customerId === r.customerId && rule.productId === r.productId
      ) as any;

      if (existingRule) {
        existingRule.customFixedPrice = r.contractNetPrice;
        existingRule.discountPercent = r.discountPercent;
        existingRule.minOrderQuantity = r.minOrderQuantity;
        existingRule.validUntil = r.effectiveEndDate;
        existingRule.isActive = r.contractStatus === "ACTIVE";
        existingRule.updatedAt = new Date().toISOString();
        updatedCount++;
      } else {
        customerPriceRulesDb.unshift({
          id: `rule-${Date.now()}-${Math.floor(Math.random() * 1000)}`,
          customerId: r.customerId || "u-cust-01",
          customerLabName: r.customerLabName,
          productId: r.productId || "prod-001",
          productSku: r.productSku,
          productName: r.productName,
          customFixedPrice: r.contractNetPrice,
          discountPercent: r.discountPercent,
          minOrderQuantity: r.minOrderQuantity,
          validUntil: r.effectiveEndDate,
          isActive: r.contractStatus === "ACTIVE",
          createdAt: new Date().toISOString(),
          updatedAt: new Date().toISOString()
        } as any);
        createdCount++;
      }
    }

    if (targetBatch) {
      targetBatch.status = "COMPLETED";
      targetBatch.completedAt = new Date().toISOString();
      targetBatch.newContractsCount = createdCount;
      targetBatch.updatedContractsCount = updatedCount;
    }

    logAudit(req, "SPECIAL_PRICE_IMPORT_COMPLETED", "PRICING", "SUCCESS", {
      userId: req.user?.id,
      details: {
        batchId: targetBatch?.id,
        createdCount,
        updatedCount
      }
    });

    res.json({
      statusCode: 200,
      message: `Price contracts imported successfully: ${createdCount} created, ${updatedCount} updated.`,
      data: { createdCount, updatedCount, batch: targetBatch }
    });
  });

