  app.post("/api/v1/sales-targets/import/validate", authenticateJwt as any, requireRole(UserRoleType.SUPER_ADMIN, UserRoleType.OFFICE_ADMIN, UserRoleType.OFFICE_STAFF) as any, (req: AuthenticatedRequest, res) => {
    const { rows, mode = "CREATE_ONLY", fileName = "Uploaded_Sales_Targets.xlsx", fileSizeBytes = 0 } = req.body;

    if (!Array.isArray(rows) || rows.length === 0) {
      return res.status(400).json({ statusCode: 400, message: "Uploaded file contains no readable sales target rows.", error: "Bad Request" });
    }

    const validationResult = validateSalesTargetImportRows(rows, mode as any, usersDb, salesTargetsDb);

    const batchId = `batch-targ-${Date.now()}`;
    const batchNumber = `TARG-IMP-${new Date().getFullYear()}-${String(new Date().getMonth() + 1).padStart(2, '0')}-${String(salesTargetImportBatchesDb.length + 1).padStart(3, '0')}`;
    const batchStatus = validationResult.errorRows > 0 ? "VALIDATION_FAILED" : "READY_FOR_REVIEW";

    const requestingUser = usersDb.find(u => u.id === req.user?.id);
    const uName = requestingUser ? `${requestingUser.firstName} ${requestingUser.lastName}`.trim() : (req.user?.email || "Office Staff");

    const newBatch = {
      id: batchId,
      batchNumber,
      fileName,
      fileSizeBytes: Number(fileSizeBytes) || 0,
      uploadedByUserId: req.user?.id || "u-staff-01",
      uploadedByUserName: uName,
      uploadedByUserEmail: req.user?.email || "staff@a2zdiagnostic.com",
      uploadedByUserRole: req.user?.roleType || "OFFICE_STAFF",
      importMode: mode,
      status: batchStatus,
      totalRows: validationResult.totalRows,
      validRows: validationResult.validRows,
      errorRows: validationResult.errorRows,
      warningRows: validationResult.warningRows,
      totalRevenueQuota: validationResult.totalRevenueQuota,
      totalCollectionQuota: validationResult.totalCollectionQuota,
      newTargetsCount: validationResult.newTargetsCount,
      updatedTargetsCount: validationResult.updatedTargetsCount,
      skippedRowsCount: validationResult.skippedRowsCount,
      requiresApproval: false,
      issues: validationResult.issues,
      parsedRows: validationResult.validatedRows,
      createdAt: new Date().toISOString(),
      updatedAt: new Date().toISOString()
    };

    salesTargetImportBatchesDb.unshift(newBatch);

    res.json({
      statusCode: 200,
      message: `Sales target validation finished. Total revenue target: ₹${validationResult.totalRevenueQuota.toLocaleString()}, ${validationResult.validRows} valid rows, ${validationResult.errorRows} errors.`,
      data: {
        batch: newBatch,
        summary: {
          totalRows: validationResult.totalRows,
          validRows: validationResult.validRows,
          errorRows: validationResult.errorRows,
          warningRows: validationResult.warningRows,
          totalRevenueQuota: validationResult.totalRevenueQuota,
          totalCollectionQuota: validationResult.totalCollectionQuota,
          newTargetsCount: validationResult.newTargetsCount,
          updatedTargetsCount: validationResult.updatedTargetsCount,
          skippedRowsCount: validationResult.skippedRowsCount
        },
        rows: validationResult.validatedRows,
        issues: validationResult.issues
      }
    });
  });

  app.post("/api/v1/sales-targets/import/execute", authenticateJwt as any, requireRole(UserRoleType.SUPER_ADMIN, UserRoleType.OFFICE_ADMIN, UserRoleType.OFFICE_STAFF) as any, (req: AuthenticatedRequest, res) => {
    if (checkPostgresMutationGuard(res, "POST /api/v1/sales-targets/import/execute")) return;
    const { batchId, rows, mode = "CREATE_ONLY" } = req.body;
    let targetBatch = batchId ? salesTargetImportBatchesDb.find(b => b.id === batchId) : undefined;
    let parsedRowsToImport = targetBatch?.parsedRows || [];

    if (parsedRowsToImport.length === 0 && Array.isArray(rows) && rows.length > 0) {
      const vResult = validateSalesTargetImportRows(rows, mode as any, usersDb, salesTargetsDb);
      parsedRowsToImport = vResult.validatedRows;
    }

    const rowsToProcess = parsedRowsToImport.filter((r: any) => r.isValid && (r.action === "CREATE" || r.action === "UPDATE"));
    let createdCount = 0;
    let updatedCount = 0;

    for (const r of rowsToProcess) {
      const existingTarget = salesTargetsDb.find(
        (t: any) =>
          (t.salesRepEmail === r.salesRepEmailOrId || t.salesRepId === r.salesRepId) &&
          t.periodName === r.periodName &&
          t.productDivision === r.productDivision
      );

      if (existingTarget) {
        existingTarget.revenueTargetAmount = r.revenueTargetAmount;
        existingTarget.collectionTargetAmount = r.collectionTargetAmount;
        existingTarget.newCustomerTargetCount = r.newCustomerTargetCount;
        existingTarget.equipmentUnitTargetCount = r.equipmentUnitTargetCount;
        existingTarget.incentiveSlab = r.incentiveSlab;
        existingTarget.remarks = r.remarks;
        existingTarget.updatedAt = new Date().toISOString();
        updatedCount++;
      } else {
        salesTargetsDb.unshift({
          id: `targ-${Date.now()}-${Math.floor(Math.random() * 1000)}`,
          salesRepId: r.salesRepId || "u-sales-01",
          salesRepEmail: r.salesRepEmailOrId,
          salesRepName: r.salesRepName,
          periodType: r.periodType,
          fiscalYear: r.fiscalYear,
          periodName: r.periodName,
          territoryCode: r.territoryCode,
          territoryName: r.territoryName,
          productDivision: r.productDivision,
          brandFocus: r.brandFocus,
          revenueTargetAmount: r.revenueTargetAmount,
          collectionTargetAmount: r.collectionTargetAmount,
          newCustomerTargetCount: r.newCustomerTargetCount,
          equipmentUnitTargetCount: r.equipmentUnitTargetCount,
          incentiveSlab: r.incentiveSlab,
          remarks: r.remarks,
          createdAt: new Date().toISOString(),
          updatedAt: new Date().toISOString()
        });
        createdCount++;
      }
    }

    if (targetBatch) {
      targetBatch.status = "COMPLETED";
      targetBatch.completedAt = new Date().toISOString();
      targetBatch.newTargetsCount = createdCount;
      targetBatch.updatedTargetsCount = updatedCount;
    }

    logAudit(req, "SALES_TARGET_IMPORT_COMPLETED", "SALES_OPERATIONS", "SUCCESS", {
      userId: req.user?.id,
      details: {
        batchId: targetBatch?.id,
        createdCount,
        updatedCount
      }
    });

    res.json({
      statusCode: 200,
      message: `Sales targets imported successfully: ${createdCount} created, ${updatedCount} updated.`,
      data: { createdCount, updatedCount, batch: targetBatch }
    });
  });

  app.get("/api/v1/sales-targets/import/batches", authenticateJwt as any, requireRole(UserRoleType.SUPER_ADMIN, UserRoleType.OFFICE_ADMIN, UserRoleType.OFFICE_STAFF) as any, (req: AuthenticatedRequest, res) => {
    res.json({ statusCode: 200, data: salesTargetsDb, batches: salesTargetImportBatchesDb, total: salesTargetsDb.length });
  });



  // ----------------------------------------------------------------------------
