  // 29.1 Personalized "Shop by Company" Access & Directory Engine
  app.get("/api/v1/customer/companies/personalized", authenticateJwt as any, (req: AuthenticatedRequest, res) => {
    const authUser = req.user!;
    if (authUser.roleType === UserRoleType.CUSTOMER) {
      if (req.query.customerId && req.query.customerId !== authUser.id && req.query.customerId !== authUser.labId) {
        return res.status(403).json({
          statusCode: 403,
          error: "CUSTOMER_ISOLATION_VIOLATION",
          message: "Access Denied: You cannot view personalized company directory for another customer account."
        });
      }
    }
    const customerId = authUser.roleType === UserRoleType.CUSTOMER ? authUser.id : ((req.query.customerId as string) || authUser.id);
    
    // 1. Find active equipment for customer
    const customerEquipment = customerEquipmentDb.filter(eq => eq.customerId === customerId && eq.status !== 'DECOMMISSIONED');
    const equipmentCompanyIds = new Set<string>();
    customerEquipment.forEach(eq => {
      if (eq.companyId) equipmentCompanyIds.add(eq.companyId);
      const prod = productsDb.find(p => p.id === eq.productId);
      if (prod && prod.companyId) equipmentCompanyIds.add(prod.companyId);
    });

    // 2. Find contract price rules for customer
    const customerPriceRules = customerPriceRulesDb.filter(r => r.customerId === customerId && r.isActive);
    const contractCompanyIds = new Set<string>();
    customerPriceRules.forEach(r => {
      if (r.companyId) contractCompanyIds.add(r.companyId);
      if (r.productId) {
        const prod = productsDb.find(p => p.id === r.productId);
        if (prod && prod.companyId) contractCompanyIds.add(prod.companyId);
      }
    });

    // 3. Find past orders for customer
    const customerOrders = customerOrdersDb.filter(o => o.customerId === customerId);
    const orderHistoryCompanyIds = new Set<string>();
    customerOrders.forEach(o => {
      o.items.forEach(item => {
        const prod = productsDb.find(p => p.id === item.productId);
        if (prod && prod.companyId) orderHistoryCompanyIds.add(prod.companyId);
      });
    });

    // 4. Find explicit product access rules for customer
    const accessRules = productAccessRulesDb.filter(r => r.customerId === customerId && r.isActive);
    const accessCompanyIds = new Set<string>();
    accessRules.forEach(r => {
      if (r.companyId && r.ruleType !== 'FORCE_HIDE') accessCompanyIds.add(r.companyId);
    });

    // Combine for "Your Companies"
    const yourCompanyIds = new Set<string>([
      ...Array.from(equipmentCompanyIds),
      ...Array.from(contractCompanyIds),
      ...Array.from(orderHistoryCompanyIds),
      ...Array.from(accessCompanyIds)
    ]);

    // Compute category tags and authorized product counts for each company
    const activeCompanies = companiesDb.filter(c => c.isActive).sort((a, b) => a.sortOrder - b.sortOrder);

    const enrichedCompanies = activeCompanies.map(c => {
      const isYour = yourCompanyIds.has(c.id);
      const eqCount = customerEquipment.filter(eq => eq.companyId === c.id || productsDb.find(p => p.id === eq.productId)?.companyId === c.id).length;
      const contractCount = customerPriceRules.filter(r => r.companyId === c.id || productsDb.find(p => p.id === r.productId)?.companyId === c.id).length;
      const hasOrderHist = orderHistoryCompanyIds.has(c.id);
      
      // Evaluate product visibility
      const visibleProducts = productsDb.filter(p => {
        if (p.companyId !== c.id || !p.isActive) return false;
        const vis = evaluateProductVisibility(p, customerId, customerEquipmentDb);
        return vis.isVisible;
      });

      // Category tags
      const catIds = new Set(visibleProducts.map(p => p.categoryId));
      const categoryTags = categoriesDb.filter(cat => catIds.has(cat.id)).map(cat => cat.name);

      // Offers
      const offersCount = featuredOffersDb.filter(o => o.isActive && o.categoryOrCompanyFilter?.id === c.id).length;

      return {
        ...c,
        isYourCompany: isYour,
        installedEquipmentCount: eqCount,
        activeContractsCount: contractCount,
        hasOrderHistory: hasOrderHist,
        authorizedProductsCount: visibleProducts.length,
        categoryTags: categoryTags.length > 0 ? categoryTags : ['Diagnostics', 'Reagents'],
        offersCount,
        isAuthorizedToBrowse: visibleProducts.length > 0 || isYour || true
      };
    });

    const yourCompanies = enrichedCompanies.filter(c => c.isYourCompany);
    const exploreCompanies = enrichedCompanies.filter(c => !c.isYourCompany);

    res.json({
      statusCode: 200,
      data: {
        yourCompanies,
        exploreCompanies,
        allCompanies: enrichedCompanies,
        summary: {
          totalYourCompanies: yourCompanies.length,
          totalExploreCompanies: exploreCompanies.length,
          totalEquipmentCount: customerEquipment.length
        }
      }
    });
  });

  // 29.2 Customer Active Equipment & Health Monitoring Endpoint
  app.get("/api/v1/customer/equipment", authenticateJwt as any, (req: AuthenticatedRequest, res) => {
    const authUser = req.user!;
    if (authUser.roleType === UserRoleType.CUSTOMER) {
      if (req.query.customerId && req.query.customerId !== authUser.id && req.query.customerId !== authUser.labId) {
        return res.status(403).json({
          statusCode: 403,
          error: "CUSTOMER_ISOLATION_VIOLATION",
          message: "Access Denied: You cannot view equipment for another customer account."
        });
      }
    }
    const customerId = authUser.roleType === UserRoleType.CUSTOMER ? authUser.id : ((req.query.customerId as string) || authUser.id);
    const equipment = customerEquipmentDb.filter(eq => eq.customerId === customerId);

    const enrichedEquipment = equipment.map(eq => {
      const prod = productsDb.find(p => p.id === eq.productId);
      const company = companiesDb.find(c => c.id === eq.companyId || (prod && c.id === prod.companyId));
      
      // Open tickets for this equipment
      const openTickets = serviceTicketsDb.filter(t => t.equipmentId === eq.id && !['CLOSED', 'CANCELLED', 'RESOLVED'].includes(t.status));
      
      // Compatible reagents
      const compatibleReagents = productsDb.filter(p => {
        if (!p.isActive || p.productType === 'EQUIPMENT') return false;
        const isCompat = (p.compatibleEquipmentProductIds && (
          p.compatibleEquipmentProductIds.includes(eq.id) ||
          p.compatibleEquipmentProductIds.includes(eq.productId) ||
          p.compatibleEquipmentProductIds.includes(eq.serialNumber) ||
          (prod && p.compatibleEquipmentProductIds.includes(prod.sku))
        )) || (p.companyId === (eq.companyId || prod?.companyId) && p.productType === 'REAGENT');

        if (!isCompat) return false;
        const vis = evaluateProductVisibility(p, customerId, customerEquipmentDb);
        return vis.isVisible;
      }).map(p => {
        const pricing = calculateCustomerPricing(p, customerId);
        return { ...p, pricing };
      });

      // Determine health score and status text
      const healthScore = eq.healthScore ?? (eq.status === 'OPERATIONAL' ? 98 : eq.status === 'DEGRADED' ? 68 : 25);
      const healthStatus = healthScore >= 90 ? 'OPTIMAL' : healthScore >= 70 ? 'GOOD' : healthScore >= 40 ? 'ATTENTION' : 'CRITICAL';
      
      // Maintenance text
      let maintenanceStatusText = "No PM scheduled";
      if (eq.nextPmDueDate) {
        const dueDate = new Date(eq.nextPmDueDate);
        const now = new Date();
        const diffDays = Math.ceil((dueDate.getTime() - now.getTime()) / (1000 * 3600 * 24));
        if (diffDays < 0) {
          maintenanceStatusText = `PM Overdue by ${Math.abs(diffDays)} days`;
        } else if (diffDays <= 30) {
          maintenanceStatusText = `PM Due soon (${diffDays} days left)`;
        } else {
          maintenanceStatusText = `Next PM Due: ${eq.nextPmDueDate}`;
        }
      }

      // Coverage badge
      let coverageBadgeText = "Out of Warranty";
      let coverageBadgeColor = "bg-rose-100 text-rose-800 border-rose-200";
      if (eq.warrantyStatus === 'UNDER_WARRANTY') {
        coverageBadgeText = "Under Warranty";
        coverageBadgeColor = "bg-emerald-100 text-emerald-800 border-emerald-200";
      } else if (eq.warrantyStatus === 'ACTIVE_AMC') {
        coverageBadgeText = "Active AMC";
        coverageBadgeColor = "bg-blue-100 text-blue-800 border-blue-200";
      } else if (eq.warrantyStatus === 'ACTIVE_CMC') {
        coverageBadgeText = "Active CMC";
        coverageBadgeColor = "bg-purple-100 text-purple-800 border-purple-200";
      }

      return {
        ...eq,
        companyId: company?.id,
        companyName: company?.name || eq.companyName || "Diagnostic OEM",
        companyLogoUrl: company?.logoUrl,
        healthScore,
        healthStatus,
        maintenanceStatusText,
        coverageBadgeText,
        coverageBadgeColor,
        coverageStatus: coverageBadgeText,
        openServiceStatusText: openTickets.length > 0 ? `${openTickets.length} Open Ticket (${openTickets[0].status})` : 'All Systems Nominal',
        hasOpenTicket: openTickets.length > 0,
        compatibleReagentsCount: compatibleReagents.length,
        compatibleReagents
      };
    });

    res.json({
      statusCode: 200,
      data: enrichedEquipment
    });
  });

  // 29.3 Customer Compatible Reagents for Installed Analyzers
