  // 30. Customer Product Catalog with Strictly Isolated Customer-Specific Pricing
  app.get("/api/v1/customer/products", (req, res) => {
    const {
      search,
      companyId,
      categoryId,
      productType,
      isColdChain,
      availability,
      customerId,
      page = 1,
      limit = 20
    } = req.query;

    // Resolve authenticated customer with strict isolation, or public visitor (empty customerId -> standard MRP/base pricing)
    const effectiveCustomerId = resolveCatalogCustomerId(req);

    // Enforce Core Rule 1: Server-Side Product Visibility Filter
    let list = productsDb.filter(p => {
      if (!p.isActive) return false;
      const visibility = evaluateProductVisibility(p, effectiveCustomerId, customerEquipmentDb);
      return visibility.isVisible;
    });

    if (companyId) {
      list = list.filter(p => p.companyId === companyId);
    }

    if (categoryId) {
      list = list.filter(p => p.categoryId === categoryId);
    }

    if (productType && productType !== "ALL") {
      list = list.filter(p => p.productType === productType);
    }

    if (isColdChain !== undefined && isColdChain !== "") {
      const coldBool = String(isColdChain) === "true";
      list = list.filter(p => p.isColdChain === coldBool);
    }

    if (availability === "COLD_CHAIN") {
      list = list.filter(p => p.isColdChain);
    } else if (availability === "IN_STOCK") {
      list = list.filter(p => p.stockStatus === "IN_STOCK");
    }

    if (search) {
      const q = String(search).toLowerCase().trim();
      list = list.filter(p =>
        p.name.toLowerCase().includes(q) ||
        p.sku.toLowerCase().includes(q) ||
        (p.catalogNumber && p.catalogNumber.toLowerCase().includes(q)) ||
        (p.shortDescription && p.shortDescription.toLowerCase().includes(q))
      );
    }

    const total = list.length;
    const pageNum = Math.max(1, Number(page) || 1);
    const limitNum = Math.max(1, Math.min(100, Number(limit) || 20));
    const totalPages = Math.ceil(total / limitNum) || 1;
    const offset = (pageNum - 1) * limitNum;
    const paginated = list.slice(offset, offset + limitNum);

    // Compute isolated customer pricing for each product
    const customerProducts = paginated.map(p => {
      const company = companiesDb.find(c => c.id === p.companyId);
      const category = categoriesDb.find(c => c.id === p.categoryId);
      const images = productImagesDb.filter(i => i.productId === p.id).sort((a, b) => a.sortOrder - b.sortOrder);
      const documents = productDocumentsDb.filter(d => d.productId === p.id && d.isPublic);
      const packOptions = productPackOptionsDb.filter(pk => pk.productId === p.id);
      const pricing = calculateCustomerPricing(p, effectiveCustomerId);

      return {
        ...p,
        company,
        category,
        images,
        documents,
        packOptions,
        pricing
      };
    });

    res.json({
      data: customerProducts,
      pagination: {
        page: pageNum,
        limit: limitNum,
        total,
        totalPages,
        hasNextPage: pageNum < totalPages,
        hasPrevPage: pageNum > 1
      },
      customerIdUsed: effectiveCustomerId
    });
  });

  // 31. Single Customer Product Detail with Isolated Contract Pricing
  app.get("/api/v1/customer/products/:id", (req, res) => {
    const { id } = req.params;
    const effectiveCustomerId = resolveCatalogCustomerId(req);

    const prod = productsDb.find(p => p.id === id);
    if (!prod) {
      return res.status(404).json({ statusCode: 404, message: "Product not found", error: "Not Found" });
    }

    const visibility = evaluateProductVisibility(prod, effectiveCustomerId, customerEquipmentDb);
    if (!visibility.isVisible) {
      return res.status(404).json({ statusCode: 404, message: "Product not found or not authorized for your laboratory account", error: "Not Found" });
    }

    const company = companiesDb.find(c => c.id === prod.companyId);
    const category = categoriesDb.find(c => c.id === prod.categoryId);
    const images = productImagesDb.filter(i => i.productId === prod.id).sort((a, b) => a.sortOrder - b.sortOrder);
    const documents = productDocumentsDb.filter(d => d.productId === prod.id && d.isPublic);
    const packOptions = productPackOptionsDb.filter(pk => pk.productId === prod.id);
    const pricing = calculateCustomerPricing(prod, effectiveCustomerId);

    res.json({
      statusCode: 200,
      data: {
        ...prod,
        company,
        category,
        images,
        documents,
        packOptions,
        pricing
      }
    });
  });

