    if (standardLatePenaltyPointsPerDay !== undefined) latePaymentPolicyConfigDb.standardLatePenaltyPointsPerDay = Number(standardLatePenaltyPointsPerDay);
    if (approvedGracePenaltyPointsPerDay !== undefined) latePaymentPolicyConfigDb.approvedGracePenaltyPointsPerDay = Number(approvedGracePenaltyPointsPerDay);
    if (maxExtensionDays !== undefined) latePaymentPolicyConfigDb.maxExtensionDays = Number(maxExtensionDays);
