  // 37.12 Customer Rating & Feedback Submission (Survives server restarts)
  app.post("/api/v1/customer/rating", authenticateJwt as any, (req: AuthenticatedRequest, res) => {
    const authUser = req.user!;
    const { customerId, rating, feedback } = req.body;
    if (authUser.roleType === UserRoleType.CUSTOMER) {
      if (customerId && customerId !== authUser.id && customerId !== authUser.labId) {
        return res.status(403).json({
          statusCode: 403,
          error: "CUSTOMER_ISOLATION_VIOLATION",
          message: "Access Denied: You cannot submit ratings or modify profiles for another customer."
        });
      }
    }
    const effectiveCustomerId = authUser.roleType === UserRoleType.CUSTOMER ? authUser.id : (customerId || authUser.id);
    const numRating = Number(rating);
    if (isNaN(numRating) || numRating < 1 || numRating > 5) {
      return res.status(400).json({ statusCode: 400, error: "VALIDATION_ERROR", message: "Rating must be a number between 1 and 5" });
    }
    const profile = customerCreditProfilesDb[effectiveCustomerId];
    if (profile) {
      profile.businessRating = numRating;
      profile.paymentReliabilityPercent = Math.min(100, Math.max(50, numRating * 20));
    }
    persistAllBusinessData();
    res.json({
      statusCode: 200,
      message: "Customer rating submitted and persisted successfully",
      data: {
        customerId: effectiveCustomerId,
        rating: profile?.businessRating || numRating,
        feedback
      }
    });
  });

  // 37.13 Customer Wallet Points Adjustment / Deduction (Survives server restarts)
  app.post("/api/v1/customer/wallet/deduct", authenticateJwt as any, async (req: AuthenticatedRequest, res) => {
    const mode = getPersistenceMode();
    if (mode === PersistenceMode.POSTGRES_DISCONNECTED) {
      return res.status(503).json({
        statusCode: 503,
        error: "DATABASE_UNAVAILABLE",
        message: "PostgreSQL database is currently disconnected. Wallet point deduction cannot be processed."
      });
    }

    const authUser = req.user!;
    const { customerId, points = 45, reason = "Penalty deduction" } = req.body;

    if (authUser.roleType === UserRoleType.CUSTOMER) {
      if (customerId && customerId !== authUser.id && customerId !== authUser.labId) {
        return res.status(403).json({
          statusCode: 403,
          error: "CUSTOMER_ISOLATION_VIOLATION",
          message: "Access Denied: You cannot adjust wallet points for another account."
        });
      }
    }

    const effectiveCustomerId = authUser.roleType === UserRoleType.CUSTOMER ? (authUser.labId || authUser.id) : (customerId || authUser.id);

    const profile = customerCreditProfilesDb[effectiveCustomerId];
    const wallet = customerWalletsDb[effectiveCustomerId];
    const deductPoints = Number(points);

    const profileSnapshot = profile ? JSON.stringify(profile) : null;
    const walletSnapshot = wallet ? JSON.stringify(wallet) : null;

    if (profile) {
      profile.walletPoints = Math.max(0, (profile.walletPoints || 0) - deductPoints);
    }
    const ledgerEntry = {
      id: `led-${Date.now()}`,
      date: new Date().toISOString().split("T")[0],
      type: "REBATE" as const,
      description: `Wallet points deducted: -${deductPoints} pts (${reason})`,
      referenceNumber: `DED-${Date.now().toString().slice(-6)}`,
      amount: deductPoints,
      runningBalance: wallet ? wallet.currentOutstanding : 0
    };
    if (wallet) {
      wallet.ledgerEntries.unshift(ledgerEntry);
    }

    const auditLogData: AuditLogEntity = {
      id: `aud-${Date.now()}-${Math.random().toString(36).substring(2, 7)}`,
      userId: authUser?.id || "u-admin-01",
      userEmail: authUser?.email || "admin@a2zdiagnostics.com",
      userRole: authUser?.roleType || "ADMIN",
      action: "WALLET_POINTS_DEDUCTED",
      module: "WALLET",
      resourceType: "WALLET",
      resourceId: effectiveCustomerId,
      ipAddress: (req.headers["x-forwarded-for"] as string) || req.socket.remoteAddress || "127.0.0.1",
      userAgent: req.headers["user-agent"] || "Unknown",
      status: "SUCCESS",
      details: { customerId: effectiveCustomerId, deductPoints, reason },
      timestamp: new Date().toISOString()
    };

    if (mode === PersistenceMode.POSTGRES_AUTHORITATIVE) {
      try {
        await financialRepository.adjustWalletPointsTx({
          customerId: effectiveCustomerId,
          deductPoints,
          ledgerEntry,
          auditLog: auditLogData
        });
      } catch (err: any) {
        if (profile && profileSnapshot) customerCreditProfilesDb[effectiveCustomerId] = JSON.parse(profileSnapshot);
        if (wallet && walletSnapshot) customerWalletsDb[effectiveCustomerId] = JSON.parse(walletSnapshot);

        return res.status(500).json({
          statusCode: 500,
          error: "DATABASE_WRITE_ERROR",
          message: `Failed to adjust wallet points in PostgreSQL: ${err.message}`
        });
      }
    } else {
      persistAllBusinessData();
    }

    auditLogsDb.unshift(auditLogData);
    if (auditLogsDb.length > 500) auditLogsDb.pop();

    res.json({
      statusCode: 200,
      message: `Successfully deducted ${deductPoints} wallet points`,
      data: {
        customerId: effectiveCustomerId,
        remainingPoints: profile?.walletPoints ?? 0,
        deductedPoints: deductPoints
      }
    });
  });

