  // 38. Customer Wallet Summary & Ledger (Enforces Customer Isolation)
  app.get("/api/v1/customer/wallet", authenticateJwt as any, async (req: AuthenticatedRequest, res) => {
    const authUser = req.user!;
    const { customerId } = req.query;

    if (authUser.roleType === UserRoleType.CUSTOMER) {
      if (customerId && customerId !== authUser.id && customerId !== authUser.labId) {
        return res.status(403).json({
          statusCode: 403,
          error: "CUSTOMER_ISOLATION_VIOLATION",
          message: "Access Denied: You cannot view the wallet of another customer account."
        });
      }
    }

    const effectiveCustomerId = authUser.roleType === UserRoleType.CUSTOMER ? (authUser.labId || authUser.id) : ((customerId as string) || authUser.id);
    const mode = getPersistenceMode();

    if (mode === PersistenceMode.POSTGRES_DISCONNECTED) {
      return res.status(503).json({
        statusCode: 503,
        error: "DATABASE_UNAVAILABLE",
        message: "PostgreSQL database is currently disconnected. Cannot serve authoritative wallet."
      });
    }

    if (mode === PersistenceMode.POSTGRES_AUTHORITATIVE) {
      try {
        let wallet = await walletRepository.findByCustomerId(effectiveCustomerId);
        const creditProfile = await walletRepository.findCreditProfileByCustomerId(effectiveCustomerId);

        if (!wallet) {
          const creditLimit = creditProfile?.creditLimit || 250000;
          const currentOutstanding = creditProfile?.currentOutstanding || 0;
          wallet = {
            customerId: effectiveCustomerId,
            creditLimit,
            currentOutstanding,
            availableCredit: creditLimit - currentOutstanding,
            creditPeriodDays: creditProfile?.creditPeriodDays || 45,
            unbilledOrdersCount: 0,
            walletPoints: creditProfile?.walletPoints ?? 1250,
            ledgerEntries: []
          };
        } else {
          if (creditProfile) {
            wallet.currentOutstanding = creditProfile.currentOutstanding;
            wallet.availableCredit = creditProfile.availableCredit;
          }
          (wallet as any).walletPoints = creditProfile?.walletPoints ?? (wallet as any).walletPoints ?? 1250;
        }

        return res.json({
          statusCode: 200,
          data: wallet
        });
      } catch (err: any) {
        console.error("[Wallet Read Error]", err?.message || err);
        return res.status(503).json({
          statusCode: 503,
          error: "DATABASE_READ_ERROR",
          message: "Failed to read authoritative customer wallet from database."
        });
      }
    }

    let wallet = customerWalletsDb[effectiveCustomerId];
    const creditProfile = customerCreditProfilesDb[effectiveCustomerId];

    if (!wallet) {
      const user = usersDb.find(u => u.id === effectiveCustomerId);
      const creditLimit = creditProfile?.creditLimit || user?.customerProfile?.creditLimit || 250000;
      const currentOutstanding = creditProfile?.currentOutstanding || user?.customerProfile?.currentOutstanding || 0;
      wallet = {
        customerId: effectiveCustomerId,
        creditLimit,
        currentOutstanding,
        availableCredit: creditLimit - currentOutstanding,
        creditPeriodDays: creditProfile?.creditPeriodDays || user?.customerProfile?.creditPeriodDays || 45,
        unbilledOrdersCount: 0,
        walletPoints: creditProfile?.walletPoints ?? 1250,
        ledgerEntries: []
      };
      customerWalletsDb[effectiveCustomerId] = wallet;
    } else {
      if (creditProfile) {
        wallet.currentOutstanding = creditProfile.currentOutstanding;
        wallet.availableCredit = creditProfile.availableCredit;
      }
      (wallet as any).walletPoints = creditProfile?.walletPoints ?? (wallet as any).walletPoints ?? 1250;
    }

    res.json({
      statusCode: 200,
      data: wallet
    });
  });

