  // ============================================================================
  // CUSTOMER AUTHENTICATION, REGISTRATION, OTP VERIFICATION & RBAC SUITE
  // ============================================================================

  interface CustomerRegistrationOtpRecord {
    id: string;
    identifier: string;
    otp: string;
    token: string;
    expiresAt: number;
    isUsed: boolean;
    failedAttempts: number;
    userId: string;
  }

  interface CustomerUserInviteRecord {
    id: string;
    labId: string;
    userId: string;
    email: string;
    phoneNumber: string;
    fullName: string;
    role: "ADMIN" | "STAFF" | "VIEWER";
    permissions: string[];
    token: string;
    otp: string;
    expiresAt: number;
    isUsed: boolean;
  }

  const customerRegistrationOtpsDb: CustomerRegistrationOtpRecord[] = [];
  const customerUserInvitesDb: CustomerUserInviteRecord[] = [];
  const otpSendRateLimitTracker = new Map<string, number[]>();

  function checkOtpSendRateLimit(identifier: string): { allowed: boolean; retryAfterSeconds?: number } {
    const now = Date.now();
    const windowMs = 10 * 60 * 1000;
    const maxSends = 5;
    const history = otpSendRateLimitTracker.get(identifier) || [];
    const validHistory = history.filter(ts => now - ts < windowMs);
    if (validHistory.length >= maxSends) {
      const oldest = validHistory[0];
      const retryAfter = Math.ceil((windowMs - (now - oldest)) / 1000);
      return { allowed: false, retryAfterSeconds: retryAfter };
    }
    validHistory.push(now);
    otpSendRateLimitTracker.set(identifier, validHistory);
    return { allowed: true };
  }

  function validateStrongPassword(pass: string): { valid: boolean; message?: string } {
    if (!pass || pass.length < 8) return { valid: false, message: "Password must be at least 8 characters long." };
    if (!/[A-Z]/.test(pass)) return { valid: false, message: "Password must contain at least one uppercase letter." };
    if (!/[a-z]/.test(pass)) return { valid: false, message: "Password must contain at least one lowercase letter." };
    if (!/[0-9]/.test(pass)) return { valid: false, message: "Password must contain at least one numerical digit." };
    if (!/[!@#$%^&*()_+\-=\[\]{};':"\\|,.<>\/?]/.test(pass)) return { valid: false, message: "Password must contain at least one special character (!@#$%^&*)." };
    return { valid: true };
  }

  function isValidEmail(email: string): boolean {
    return /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email);
  }

  function isValidPhone(phone: string): boolean {
    const digits = (phone || "").replace(/\D/g, "");
    return digits.length === 10 || (digits.length === 12 && digits.startsWith("91"));
  }

  // 1. Customer Registration (Clean Single Form -> Generates Owner)
  app.post("/api/v1/auth/customer/register", (req, res) => {
    const {
      labName,
      contactPersonName,
      labAddress,
      email,
      contactNumber,
      password,
      confirmPassword
    } = req.body;

    const validationErrors: string[] = [];
    if (!labName || !labName.trim()) validationErrors.push("Lab / Hospital Name is required.");
    if (!contactPersonName || !contactPersonName.trim()) validationErrors.push("Contact Person Name is required.");
    if (!labAddress || !labAddress.trim()) validationErrors.push("Lab / Hospital Address is required.");
    if (!email || !email.trim()) validationErrors.push("Email ID is required.");
    if (!contactNumber || !contactNumber.trim()) validationErrors.push("Contact Number is required.");
    if (!password) validationErrors.push("Create Password is required.");
    if (!confirmPassword) validationErrors.push("Confirm Password is required.");
    if (confirmPassword && confirmPassword !== password) validationErrors.push("Password confirmation does not match the chosen password.");

    if (validationErrors.length > 0) {
      return res.status(400).json({
        statusCode: 400,
        error: "VALIDATION_FAILED",
        message: validationErrors.join(" "),
        errors: validationErrors
      });
    }

    const cleanEmail = email.trim().toLowerCase();
    const cleanPhone = contactNumber.trim();

    if (!isValidEmail(cleanEmail)) {
      return res.status(400).json({
        statusCode: 400,
        error: "INVALID_EMAIL",
        message: "Please enter a valid institutional or personal email address."
      });
    }

    if (!isValidPhone(cleanPhone)) {
      return res.status(400).json({
        statusCode: 400,
        error: "INVALID_PHONE",
        message: "Please enter a valid 10-digit mobile contact number."
      });
    }

    const pwdCheck = validateStrongPassword(password);
    if (!pwdCheck.valid) {
      return res.status(400).json({
        statusCode: 400,
        error: "WEAK_PASSWORD",
        message: pwdCheck.message
      });
    }

    // Check duplicate email or phone in usersDb
    const existing = usersDb.find(
      u => u.email.toLowerCase() === cleanEmail || u.phoneNumber === cleanPhone
    );
    if (existing) {
      return res.status(409).json({
        statusCode: 409,
        error: "ACCOUNT_EXISTS",
        message: "An account with this email address or contact number is already registered. Please sign in or use Forgot Password."
      });
    }

    // Rate-limiting check for OTP requests
    const rateCheck = checkOtpSendRateLimit(cleanEmail);
    if (!rateCheck.allowed) {
      return res.status(429).json({
        statusCode: 429,
        error: "RATE_LIMITED",
        message: `Too many registration attempts. Please try again in ${rateCheck.retryAfterSeconds} seconds.`
      });
    }

    // First registered user for this laboratory becomes OWNER!
    const newLabId = `lab-${Date.now()}`;
    const newUserId = `u-cust-${Date.now()}`;
    const nameParts = contactPersonName.trim().split(" ");
    const firstName = nameParts[0] || contactPersonName.trim();
    const lastName = nameParts.slice(1).join(" ") || "Owner";

    const newUser: UserEntity = {
      id: newUserId,
      username: cleanEmail.split("@")[0],
      email: cleanEmail,
      phoneNumber: cleanPhone,
      passwordHash: bcrypt.hashSync(password, 10), // Passwords NEVER stored in plaintext
      firstName,
      lastName,
      roleType: UserRoleType.CUSTOMER,
      customerRole: "OWNER",
      labId: newLabId,
      labAddress: labAddress.trim(),
      status: "PENDING_ACTIVATION",
      dataScope: "OWN",
      isEmailVerified: false,
      isPhoneVerified: false,
      twoFactorEnabled: false,
      failedLoginAttempts: 0,
      customerPermissions: [
        "orders:create",
        "orders:view",
        "payments:make",
        "financials:view",
        "tickets:create",
        "applications:create",
        "users:manage",
        "lab:view",
        "products:view"
      ],
      customerProfile: {
        labName: labName.trim(),
        customerCode: `CUST-${Math.floor(1000 + Math.random() * 9000)}`,
        customerType: "CLINICAL_LABORATORY",
        creditLimit: 250000.00,
        creditPeriodDays: 30,
        currentOutstanding: 0.00,
        isApproved: true
      },
      createdAt: new Date().toISOString(),
      updatedAt: new Date().toISOString()
    };

    usersDb.push(newUser);

    // Generate 6-digit OTP & session token
    const generatedOtp = String(Math.floor(100000 + Math.random() * 900000));
    const otpToken = `otp-reg-${Date.now()}-${Math.random().toString(36).substring(2, 8)}`;

    customerRegistrationOtpsDb.push({
      id: `otp-${Date.now()}`,
      identifier: cleanEmail,
      otp: generatedOtp,
      token: otpToken,
      expiresAt: Date.now() + 600000, // 10 minutes
      isUsed: false,
      failedAttempts: 0,
      userId: newUserId
    });

    logAudit(req, "CUSTOMER_REGISTRATION_INITIATED", "AUTH", "SUCCESS", {
      userId: newUserId,
      userEmail: cleanEmail,
      details: { labName, role: "OWNER", labId: newLabId }
    });

    const simulated = isSimulatedOtpAllowed();
    res.status(201).json({
      statusCode: 201,
      message: simulated
        ? `Registration initiated. Verification OTP dispatched (simulation mode).`
        : `Registration initiated. Verification code generated (external delivery provider pending).`,
      otpToken,
      ...(simulated ? { debugOtp: generatedOtp } : {}),
      role: "OWNER",
      status: "PENDING_ACTIVATION",
      isPendingActivation: true,
      expiresInSeconds: 600
    });
  });

  // 2. Customer Registration OTP Verification -> Account Activation
  app.post("/api/v1/auth/customer/verify-registration-otp", (req, res) => {
    const { otpToken, otp, identifier, email, phone } = req.body;
    const cleanId = (identifier || email || phone || "").trim().toLowerCase();

    const entry = customerRegistrationOtpsDb.find(
      o => ((otpToken && o.token === otpToken) || (cleanId && o.identifier === cleanId)) && !o.isUsed
    );

    if (!entry) {
      return res.status(400).json({
        statusCode: 400,
        error: "INVALID_OTP",
        message: "Invalid or expired OTP session. Please request a new verification code."
      });
    }

    if (entry.failedAttempts >= 5) {
      return res.status(429).json({
        statusCode: 429,
        error: "OTP_LOCKED",
        message: "Too many failed attempts. This OTP session has been locked for security. Please request a new code."
      });
    }

    if (Date.now() > entry.expiresAt) {
      return res.status(400).json({
        statusCode: 400,
        error: "OTP_EXPIRED",
        message: "Verification code has expired. Please tap 'Resend OTP' to receive a fresh code."
      });
    }

    if (entry.otp !== String(otp).trim()) {
      entry.failedAttempts = (entry.failedAttempts || 0) + 1;
      return res.status(400).json({
        statusCode: 400,
        error: "INVALID_OTP",
        message: `Incorrect 6-digit OTP code. (${5 - entry.failedAttempts} attempt(s) remaining)`
      });
    }

    entry.isUsed = true;
    const user = usersDb.find(u => u.id === entry.userId);
    if (!user) {
      return res.status(404).json({ statusCode: 404, message: "User account not found." });
    }

    user.status = "ACTIVE";
    user.isEmailVerified = true;
    user.isPhoneVerified = true;
    user.updatedAt = new Date().toISOString();

    // Initialize wallet & credit profile for new lab
    customerWalletsDb[user.id] = {
      customerId: user.id,
      creditLimit: user.customerProfile?.creditLimit || 250000,
      currentOutstanding: 0,
      availableCredit: user.customerProfile?.creditLimit || 250000,
      creditPeriodDays: 30,
      unbilledOrdersCount: 0,
      ledgerEntries: []
    };

    customerCreditProfilesDb[user.id] = {
      customerId: user.id,
      customerLabName: user.customerProfile?.labName || "Diagnostic Partner Lab",
      creditLimit: user.customerProfile?.creditLimit || 250000,
      availableCredit: user.customerProfile?.creditLimit || 250000,
      currentOutstanding: 0,
      creditPeriodDays: 30,
      dueDate: "15 Oct 2026",
      daysOverdue: 0,
      paymentStatus: "GOOD_STANDING",
      hasApprovedExtension: false,
      approvedExtensionUntil: null,
      walletPoints: 500,
      businessRating: 5.0,
      paymentReliabilityPercent: 100.0,
      paymentHistory: [],
      paymentPromises: []
    };

    // Issue JWT Access & Refresh Tokens
    const accessToken = jwt.sign(
      {
        sub: user.id,
        email: user.email,
        role: user.roleType,
        customerRole: user.customerRole || "OWNER",
        labId: user.labId,
        permissions: user.customerPermissions || [],
        dataScope: "OWN"
      },
      JWT_ACCESS_SECRET,
      { expiresIn: Math.floor(JWT_ACCESS_EXPIRY_MS / 1000) }
    );

    const refreshToken = jwt.sign(
      { sub: user.id, family: `cust-fam-${Date.now()}` },
      JWT_REFRESH_SECRET,
      { expiresIn: Math.floor(JWT_REFRESH_EXPIRY_MS / 1000) }
    );

    logAudit(req, "CUSTOMER_ACCOUNT_ACTIVATED", "AUTH", "SUCCESS", {
      userId: user.id,
      userEmail: user.email,
      details: { role: user.customerRole, labId: user.labId }
    });

    persistAllBusinessData();

    res.json({
      statusCode: 200,
      message: "Account verified and activated successfully! Welcome to Diagnostic Services.",
      accessToken,
      refreshToken,
      user: {
        id: user.id,
        email: user.email,
        phoneNumber: user.phoneNumber,
        firstName: user.firstName,
        lastName: user.lastName,
        customerRole: user.customerRole || "OWNER",
        labId: user.labId,
        labName: user.customerProfile?.labName || "Diagnostic Partner Lab",
        labAddress: user.labAddress || "Main Laboratory Facility",
        customerPermissions: user.customerPermissions || [],
        customerProfile: user.customerProfile
      }
    });
  });

  // 3. Resend OTP with Rate Limiting
  app.post("/api/v1/auth/customer/resend-otp", (req, res) => {
    const { otpToken, identifier, email, phone } = req.body;
    const cleanId = (identifier || email || phone || "").trim().toLowerCase();

    const rateCheck = checkOtpSendRateLimit(cleanId || otpToken);
    if (!rateCheck.allowed) {
      return res.status(429).json({
        statusCode: 429,
        error: "RATE_LIMITED",
        message: `Too many OTP requests. Please wait ${rateCheck.retryAfterSeconds} seconds before requesting again.`
      });
    }

    const newOtp = String(Math.floor(100000 + Math.random() * 900000));
    const newToken = otpToken || `otp-${Date.now()}-${Math.random().toString(36).substring(2, 8)}`;

    const existingEntry = customerRegistrationOtpsDb.find(
      o => ((otpToken && o.token === otpToken) || (cleanId && o.identifier === cleanId)) && !o.isUsed
    );

    if (existingEntry) {
      existingEntry.otp = newOtp;
      existingEntry.expiresAt = Date.now() + 600000;
      existingEntry.failedAttempts = 0;
      existingEntry.isUsed = false;
    } else {
      customerRegistrationOtpsDb.push({
        id: `otp-${Date.now()}`,
        identifier: cleanId,
        otp: newOtp,
        token: newToken,
        expiresAt: Date.now() + 600000,
        isUsed: false,
        failedAttempts: 0,
        userId: ""
      });
    }

    const simulated = isSimulatedOtpAllowed();
    res.json({
      statusCode: 200,
      message: simulated
        ? "New 6-digit OTP code dispatched successfully (simulation mode)."
        : "New verification code generated (external delivery provider pending).",
      otpToken: newToken,
      ...(simulated ? { debugOtp: newOtp } : {}),
      expiresInSeconds: 600
    });
  });

  // 4. Customer Login with Lockout Protection & Clean Response
  app.post("/api/v1/auth/customer/login", (req, res) => {
    const { identifier, password } = req.body;
    const cleanId = (identifier || "").trim().toLowerCase();

    if (!cleanId || !password) {
      return res.status(400).json({
        statusCode: 400,
        error: "VALIDATION_FAILED",
        message: "Mobile number / Email ID and Password are required."
      });
    }

    const user = usersDb.find(
      u => (u.email && u.email.toLowerCase() === cleanId) ||
           (u.phoneNumber && u.phoneNumber.replace(/\D/g, "") === cleanId.replace(/\D/g, "")) ||
           (cleanId === "customer@apexlabs.com" && u.id === "u-cust-01") ||
           (cleanId === "admin@apexlabs.com" && u.id === "u-cust-01-admin") ||
           (cleanId === "viewer@apexlabs.com" && u.id === "u-cust-01-viewer") ||
           (cleanId === "customer2@metropolislabs.com" && u.id === "u-cust-02")
    );

    if (!user) {
      return res.status(401).json({
        statusCode: 401,
        error: "INVALID_CREDENTIALS",
        message: "Invalid credentials. Please verify your mobile number/email and password."
      });
    }

    // Check account lockout status
    if (user.lockoutUntil) {
      const lockTime = new Date(user.lockoutUntil).getTime();
      if (Date.now() < lockTime) {
        const remainingMinutes = Math.ceil((lockTime - Date.now()) / 60000);
        return res.status(423).json({
          statusCode: 423,
          error: "ACCOUNT_LOCKED",
          message: `Account is temporarily locked due to 5 consecutive failed login attempts. Please try again in ${remainingMinutes} minute(s).`
        });
      } else {
        user.lockoutUntil = undefined;
        user.failedLoginAttempts = 0;
      }
    }

    // Verify Password using bcrypt against stored hash
    const isValid = Boolean(user.passwordHash && bcrypt.compareSync(password, user.passwordHash));
    if (!isValid) {
      user.failedLoginAttempts = (user.failedLoginAttempts || 0) + 1;
      if (user.failedLoginAttempts >= 5) {
        user.lockoutUntil = new Date(Date.now() + 15 * 60 * 1000).toISOString();
        logAudit(req, "AUTH_ACCOUNT_LOCKED", "AUTH", "WARNING", {
          userId: user.id,
          userEmail: user.email,
          details: { failedAttempts: user.failedLoginAttempts, lockoutUntil: user.lockoutUntil }
        });
        return res.status(423).json({
          statusCode: 423,
          error: "ACCOUNT_LOCKED",
          message: "Account locked due to 5 consecutive failed login attempts. Account will remain locked for 15 minutes."
        });
      }

      return res.status(401).json({
        statusCode: 401,
        error: "INVALID_CREDENTIALS",
        message: `Invalid password. (${5 - user.failedLoginAttempts} attempts remaining before account lockout)`
      });
    }

    // Check account lifecycle status
    if (user.status === "PENDING_ACTIVATION" || user.status === "PENDING_VERIFICATION") {
      const pendingOtp = customerRegistrationOtpsDb.find(o => o.userId === user.id && !o.isUsed);
      const simulated = isSimulatedOtpAllowed();
      return res.status(403).json({
        statusCode: 403,
        error: "PENDING_ACTIVATION",
        isPendingActivation: true,
        otpToken: pendingOtp?.token,
        ...(simulated && pendingOtp?.otp ? { debugOtp: pendingOtp.otp } : {}),
        message: "Account registration is pending OTP verification. Please verify your OTP to complete activation."
      });
    }

    if (user.status === "DEACTIVATED") {
      return res.status(403).json({
        statusCode: 403,
        error: "ACCOUNT_DEACTIVATED",
        message: "Your laboratory account has been deactivated. Please contact your Laboratory Owner."
      });
    }

    if (user.status === "SUSPENDED") {
      return res.status(403).json({
        statusCode: 403,
        error: "ACCOUNT_SUSPENDED",
        message: "Account is temporarily suspended pending compliance review."
      });
    }

    // Reset failed login attempts on successful authentication
    user.failedLoginAttempts = 0;
    user.lockoutUntil = undefined;
    user.lastLoginAt = new Date().toISOString();

    const accessToken = jwt.sign(
      {
        sub: user.id,
        email: user.email,
        role: user.roleType,
        customerRole: user.customerRole || "OWNER",
        labId: user.labId || user.id,
        permissions: user.customerPermissions || [],
        dataScope: "OWN"
      },
      JWT_ACCESS_SECRET,
      { expiresIn: Math.floor(JWT_ACCESS_EXPIRY_MS / 1000) }
    );

    const refreshToken = jwt.sign(
      { sub: user.id, family: `cust-fam-${Date.now()}` },
      JWT_REFRESH_SECRET,
      { expiresIn: Math.floor(JWT_REFRESH_EXPIRY_MS / 1000) }
    );

    logAudit(req, "CUSTOMER_LOGIN_SUCCESS", "AUTH", "SUCCESS", {
      userId: user.id,
      userEmail: user.email,
      details: { customerRole: user.customerRole, labId: user.labId }
    });

    res.json({
      statusCode: 200,
      message: "Authentication successful.",
      accessToken,
      refreshToken,
      user: {
        id: user.id,
        email: user.email,
        phoneNumber: user.phoneNumber,
        firstName: user.firstName,
        lastName: user.lastName,
        customerRole: user.customerRole || user.roleType || "OWNER",
        roleType: user.roleType,
        employeeProfile: user.employeeProfile,
        labId: user.labId || user.id,
        labName: user.customerProfile?.labName || (user.employeeProfile ? `${user.firstName} ${user.lastName} (${user.employeeProfile.designation})` : "Diagnostic Partner Lab"),
        labAddress: user.labAddress || (user.branch ? `${user.branch}, ${user.region}` : "Sunrise Healthcare Complex, Powai, Mumbai"),
        customerPermissions: user.customerPermissions || [],
        customerProfile: user.customerProfile
      }
    });
  });

  // 5. Customer Secure Logout
  app.post("/api/v1/auth/customer/logout", (req, res) => {
    const authUser = getRequestAuthUser(req);
    if (authUser) {
      logAudit(req, "CUSTOMER_LOGOUT", "AUTH", "SUCCESS", {
        userId: authUser.id || authUser.sub,
        userEmail: authUser.email
      });
    }
    res.json({
      statusCode: 200,
      message: "Successfully signed out. Active session information cleared."
    });
  });

  // 6. Customer Forgot Password: Step 1 - Request OTP
  app.post("/api/v1/auth/customer/forgot-password", (req, res) => {
    const { identifier } = req.body;
    const cleanId = (identifier || "").trim().toLowerCase();

    if (!cleanId) {
      return res.status(400).json({ statusCode: 400, message: "Email or phone number is required", error: "Bad Request" });
    }

    const user = usersDb.find(
      u => u.email.toLowerCase() === cleanId ||
           u.phoneNumber === cleanId ||
           u.phoneNumber.replace(/\D/g, "") === cleanId.replace(/\D/g, "") ||
           (cleanId === "customer@apexlabs.com" && u.id === "u-cust-01") ||
           (cleanId === "admin@apexlabs.com" && u.id === "u-cust-01-admin") ||
           (cleanId === "viewer@apexlabs.com" && u.id === "u-cust-01-viewer") ||
           (cleanId === "customer2@metropolislabs.com" && u.id === "u-cust-02")
    );

    if (!user) {
      return res.status(404).json({
        statusCode: 404,
        message: "No registered laboratory account found with this email/phone.",
        error: "Not Found"
      });
    }

    const rateCheck = checkOtpSendRateLimit(cleanId);
    if (!rateCheck.allowed) {
      return res.status(429).json({
        statusCode: 429,
        error: "RATE_LIMITED",
        message: `Too many reset requests. Please wait ${rateCheck.retryAfterSeconds} seconds.`
      });
    }

    const generatedOtp = String(Math.floor(100000 + Math.random() * 900000));
    const token = `rst-tok-${Date.now()}-${Math.random().toString(36).substring(2, 8)}`;

    passwordResetOtpsDb.push({
      id: `otp-${Date.now()}`,
      identifier: cleanId,
      otp: generatedOtp,
      token,
      expiresAt: Date.now() + 600000,
      isUsed: false
    });

    logAudit(req, "CUSTOMER_FORGOT_PASSWORD_REQUESTED", "AUTH", "SUCCESS", {
      userId: user.id,
      userEmail: user.email,
      details: { identifier: cleanId, otpDispatched: true }
    });

    const simulated = isSimulatedOtpAllowed();
    res.json({
      statusCode: 200,
      message: simulated
        ? `Verification code dispatched for ${user.firstName} (simulation mode).`
        : `Verification code generated for ${user.firstName} (external delivery provider pending).`,
      token,
      ...(simulated ? { debugOtp: generatedOtp } : {}),
      expiresInSeconds: 600
    });
  });

  // 7. Customer Forgot Password: Step 2 - Verify OTP
  app.post("/api/v1/auth/customer/verify-otp", (req, res) => {
    const { identifier, otp, token } = req.body;
    const cleanId = (identifier || "").trim().toLowerCase();

    const entry = passwordResetOtpsDb.find(
      o => (o.identifier === cleanId || o.token === token) && o.otp === String(otp).trim() && !o.isUsed
    );

    if (!entry) {
      return res.status(400).json({
        statusCode: 400,
        message: "Invalid or expired OTP verification code.",
        error: "Bad Request"
      });
    }

    if (Date.now() > entry.expiresAt) {
      return res.status(400).json({
        statusCode: 400,
        message: "OTP has expired. Please request a new code.",
        error: "Bad Request"
      });
    }

    res.json({
      statusCode: 200,
      message: "OTP successfully verified. You may now set your new password.",
      resetToken: entry.token
    });
  });

  // 8. Customer Forgot Password: Step 3 - Reset Password
  app.post("/api/v1/auth/customer/reset-password", (req, res) => {
    const { identifier, resetToken, token, newPassword } = req.body;
    const cleanId = (identifier || "").trim().toLowerCase();
    const effectiveToken = resetToken || token;

    const pwdCheck = validateStrongPassword(newPassword);
    if (!pwdCheck.valid) {
      return res.status(400).json({
        statusCode: 400,
        error: "WEAK_PASSWORD",
        message: pwdCheck.message
      });
    }

    const otpEntry = passwordResetOtpsDb.find(
      o => o.token === effectiveToken && !o.isUsed
    );

    if (!otpEntry) {
      return res.status(400).json({
        statusCode: 400,
        message: "Invalid or expired reset session token.",
        error: "Bad Request"
      });
    }

    const user = usersDb.find(
      u => u.email.toLowerCase() === cleanId || u.email.toLowerCase() === otpEntry.identifier || u.phoneNumber === cleanId
    );

    if (!user) {
      return res.status(404).json({ statusCode: 404, message: "User account not found", error: "Not Found" });
    }

    user.passwordHash = bcrypt.hashSync(newPassword, 10);
    user.failedLoginAttempts = 0;
    user.lockoutUntil = undefined;
    user.updatedAt = new Date().toISOString();
    otpEntry.isUsed = true;

    logAudit(req, "CUSTOMER_PASSWORD_RESET_SUCCESS", "AUTH", "SUCCESS", {
      userId: user.id,
      userEmail: user.email,
      details: { resetViaOtp: true }
    });

    res.json({
      statusCode: 200,
      message: "Password reset successfully. You can now login with your new credentials."
    });
  });

  // 9. Owner User Management: Get Laboratory Team Users (Enforces Tenant Isolation)
  app.get("/api/v1/customer/users", (req, res) => {
    const authUser = getRequestAuthUser(req);
    if (!authUser) {
      return res.status(401).json({ statusCode: 401, error: "UNAUTHORIZED", message: "Authentication required." });
    }

    const effectiveLabId = authUser.labId || authUser.id;
    const labUsers = usersDb
      .filter(u => u.labId === effectiveLabId || u.id === effectiveLabId)
      .map(u => ({
        id: u.id,
        fullName: `${u.firstName} ${u.lastName}`.trim(),
        email: u.email,
        phoneNumber: u.phoneNumber,
        role: (u.customerRole || "STAFF") as "OWNER" | "ADMIN" | "STAFF" | "VIEWER",
        status: u.status,
        permissions: u.customerPermissions || [],
        invitedAt: u.createdAt,
        lastLoginAt: u.lastLoginAt
      }));

    res.json(labUsers);
  });

  // 10. Owner User Management: Invite User (Admin / Staff / Viewer)
  app.post("/api/v1/customer/users/invite", (req, res) => {
    const authUser = getRequestAuthUser(req);
    if (!authUser) {
      return res.status(401).json({ statusCode: 401, error: "UNAUTHORIZED", message: "Authentication required." });
    }

    // Only OWNER or users with users:manage can invite
    const isOwner = authUser.customerRole === "OWNER" || (authUser.customerPermissions && authUser.customerPermissions.includes("users:manage"));
    if (!isOwner) {
      return res.status(403).json({
        statusCode: 403,
        error: "ACCESS_DENIED",
        message: "Access Denied: Only the Laboratory Owner can invite and manage laboratory users."
      });
    }

    const { fullName, firstName: bodyFirstName, lastName: bodyLastName, email, phoneNumber, role = "STAFF", permissions } = req.body;
    const effectiveFullName = (fullName || `${bodyFirstName || ""} ${bodyLastName || ""}`).trim();
    if (!effectiveFullName || !email || !phoneNumber) {
      return res.status(400).json({
        statusCode: 400,
        error: "VALIDATION_FAILED",
        message: "Full Name, Email ID, and Contact Number are required to invite a user."
      });
    }

    const cleanEmail = email.trim().toLowerCase();
    const cleanPhone = phoneNumber.trim();

    if (!isValidEmail(cleanEmail)) {
      return res.status(400).json({ statusCode: 400, error: "INVALID_EMAIL", message: "Please provide a valid email address." });
    }

    if (!isValidPhone(cleanPhone)) {
      return res.status(400).json({ statusCode: 400, error: "INVALID_PHONE", message: "Please provide a valid 10-digit mobile number." });
    }

    if (usersDb.some(u => u.email.toLowerCase() === cleanEmail)) {
      return res.status(409).json({
        statusCode: 409,
        error: "DUPLICATE_EMAIL",
        message: "A user with this email address is already registered."
      });
    }

    // Map permissions by role
    let assignedPermissions: string[] = Array.isArray(permissions) ? permissions : [];
    if (assignedPermissions.length === 0) {
      if (role === "ADMIN") {
        assignedPermissions = [
          "orders:create",
          "orders:view",
          "financials:view",
          "tickets:create",
          "applications:create",
          "lab:view",
          "products:view"
        ]; // NOTE: Admin does NOT have payments:make by default
      } else if (role === "STAFF") {
        assignedPermissions = [
          "orders:create",
          "orders:view",
          "tickets:create",
          "products:view",
          "lab:view"
        ];
      } else if (role === "VIEWER") {
        assignedPermissions = [
          "orders:view",
          "products:view",
          "lab:view"
        ]; // Read-only
      }
    }

    const effectiveLabId = authUser.labId || authUser.id;
    const callerUser = usersDb.find(u => u.id === authUser.id);
    const newUserId = `u-cust-team-${Date.now()}`;
    const nameParts = effectiveFullName.split(" ");
    const firstName = bodyFirstName || nameParts[0] || effectiveFullName;
    const lastName = bodyLastName || nameParts.slice(1).join(" ") || "Member";

    // Invited user receives random temp hash; creates OWN password upon activation
    const tempHash = bcrypt.hashSync(`InvTempPass#${Date.now()}`, 10);

    const newTeamUser: UserEntity = {
      id: newUserId,
      username: cleanEmail.split("@")[0],
      email: cleanEmail,
      phoneNumber: cleanPhone,
      passwordHash: tempHash,
      firstName,
      lastName,
      roleType: UserRoleType.CUSTOMER,
      customerRole: role as "ADMIN" | "STAFF" | "VIEWER",
      labId: effectiveLabId,
      labAddress: callerUser?.labAddress || "Sunrise Healthcare Complex, Powai, Mumbai",
      status: "PENDING_ACTIVATION",
      dataScope: "OWN",
      isEmailVerified: false,
      isPhoneVerified: false,
      twoFactorEnabled: false,
      failedLoginAttempts: 0,
      customerPermissions: assignedPermissions,
      customerProfile: callerUser?.customerProfile,
      createdAt: new Date().toISOString(),
      updatedAt: new Date().toISOString()
    };

    usersDb.push(newTeamUser);

    const inviteOtp = String(Math.floor(100000 + Math.random() * 900000));
    const inviteToken = `inv-${Date.now()}-${Math.random().toString(36).substring(2, 8)}`;

    customerUserInvitesDb.push({
      id: `inv-${Date.now()}`,
      labId: effectiveLabId,
      userId: newUserId,
      email: cleanEmail,
      phoneNumber: cleanPhone,
      fullName: effectiveFullName,
      role: role as "ADMIN" | "STAFF" | "VIEWER",
      permissions: assignedPermissions,
      token: inviteToken,
      otp: inviteOtp,
      expiresAt: Date.now() + 86400000, // 24 hours
      isUsed: false
    });

    logAudit(req, "CUSTOMER_USER_INVITED", "USERS", "SUCCESS", {
      userId: newUserId,
      userEmail: cleanEmail,
      details: { invitedBy: authUser.id, role, labId: effectiveLabId }
    });

    const simulated = isSimulatedOtpAllowed();
    res.status(201).json({
      statusCode: 201,
      message: simulated
        ? `Invitation successfully created for ${cleanEmail} (simulation mode).`
        : `Invitation successfully created for ${cleanEmail}. Activation dispatch queued with delivery service.`,
      inviteToken,
      ...(simulated ? { debugOtp: inviteOtp } : {}),
      user: {
        id: newUserId,
        fullName: effectiveFullName,
        email: cleanEmail,
        phoneNumber: cleanPhone,
        role,
        status: "PENDING_ACTIVATION",
        permissions: assignedPermissions
      }
    });
  });

  // 11. Invited User Activation: Verify OTP and Create Own Password
  app.post("/api/v1/auth/customer/activate-invite", (req, res) => {
    const { inviteToken, otp, password } = req.body;

    const entry = customerUserInvitesDb.find(
      i => (i.token === inviteToken || i.otp === String(otp).trim()) && !i.isUsed
    );

    if (!entry) {
      return res.status(400).json({
        statusCode: 400,
        error: "INVALID_INVITE",
        message: "Invalid or expired invitation token."
      });
    }

    if (Date.now() > entry.expiresAt) {
      return res.status(400).json({
        statusCode: 400,
        error: "INVITE_EXPIRED",
        message: "This invitation has expired. Please ask your Laboratory Owner to re-invite you."
      });
    }

    const pwdCheck = validateStrongPassword(password);
    if (!pwdCheck.valid) {
      return res.status(400).json({
        statusCode: 400,
        error: "WEAK_PASSWORD",
        message: pwdCheck.message
      });
    }

    const user = usersDb.find(u => u.id === entry.userId);
    if (!user) {
      return res.status(404).json({ statusCode: 404, message: "User account not found." });
    }

    // Set user's own password securely
    user.passwordHash = bcrypt.hashSync(password, 10);
    user.status = "ACTIVE";
    user.isEmailVerified = true;
    user.isPhoneVerified = true;
    user.updatedAt = new Date().toISOString();
    entry.isUsed = true;

    const accessToken = jwt.sign(
      {
        sub: user.id,
        email: user.email,
        role: user.roleType,
        customerRole: user.customerRole || "STAFF",
        labId: user.labId,
        permissions: user.customerPermissions || [],
        dataScope: "OWN"
      },
      JWT_ACCESS_SECRET,
      { expiresIn: Math.floor(JWT_ACCESS_EXPIRY_MS / 1000) }
    );

    const refreshToken = jwt.sign(
      { sub: user.id, family: `cust-fam-${Date.now()}` },
      JWT_REFRESH_SECRET,
      { expiresIn: Math.floor(JWT_REFRESH_EXPIRY_MS / 1000) }
    );

    logAudit(req, "CUSTOMER_INVITE_ACTIVATED", "AUTH", "SUCCESS", {
      userId: user.id,
      userEmail: user.email,
      details: { role: user.customerRole, labId: user.labId }
    });

    res.json({
      statusCode: 200,
      message: `Account activated successfully! You are now logged in as ${user.customerRole}.`,
      accessToken,
      refreshToken,
      user: {
        id: user.id,
        email: user.email,
        phoneNumber: user.phoneNumber,
        firstName: user.firstName,
        lastName: user.lastName,
        customerRole: user.customerRole,
        labId: user.labId,
        labName: user.customerProfile?.labName || "Diagnostic Partner Lab",
        labAddress: user.labAddress || "Sunrise Healthcare Complex, Powai, Mumbai",
        customerPermissions: user.customerPermissions || [],
        customerProfile: user.customerProfile
      }
    });
  });

  // 12. Owner User Management: Deactivate / Reactivate User
  app.patch("/api/v1/customer/users/:id/status", (req, res) => {
    const authUser = getRequestAuthUser(req);
    if (!authUser) {
      return res.status(401).json({ statusCode: 401, error: "UNAUTHORIZED", message: "Authentication required." });
    }

    if (authUser.customerRole !== "OWNER") {
      return res.status(403).json({
        statusCode: 403,
        error: "ACCESS_DENIED",
        message: "Access Denied: Only the Laboratory Owner can change user statuses."
      });
    }

    const { id } = req.params;
    const { status } = req.body;

    if (id === authUser.id) {
      return res.status(400).json({
        statusCode: 400,
        error: "CANNOT_DEACTIVATE_SELF",
        message: "The Laboratory Owner cannot deactivate their own account."
      });
    }

    const effectiveLabId = authUser.labId || authUser.id;
    const targetUser = usersDb.find(u => u.id === id && (u.labId === effectiveLabId || u.id === effectiveLabId));

    if (!targetUser) {
      return res.status(404).json({ statusCode: 404, message: "User not found in your laboratory." });
    }

    targetUser.status = status === "DEACTIVATED" ? "DEACTIVATED" : "ACTIVE";
    targetUser.updatedAt = new Date().toISOString();

    logAudit(req, "CUSTOMER_USER_STATUS_CHANGED", "USERS", "SUCCESS", {
      resourceType: "USER",
      resourceId: targetUser.id,
      details: {
        targetUserId: targetUser.id,
        newStatus: targetUser.status,
        changedBy: authUser.id
      }
    });

    res.json({
      statusCode: 200,
      message: `User ${targetUser.firstName} ${targetUser.lastName} is now ${targetUser.status}.`,
      status: targetUser.status
    });
  });

  // 13. Owner User Management: Update Permissions / Role
  app.patch("/api/v1/customer/users/:id/permissions", (req, res) => {
    const authUser = getRequestAuthUser(req);
    if (!authUser) {
      return res.status(401).json({ statusCode: 401, error: "UNAUTHORIZED", message: "Authentication required." });
    }

    if (authUser.customerRole !== "OWNER") {
      return res.status(403).json({
        statusCode: 403,
        error: "ACCESS_DENIED",
        message: "Access Denied: Only the Laboratory Owner can assign roles and permissions."
      });
    }

    const { id } = req.params;
    const { role, permissions } = req.body;

    if (id === authUser.id) {
      return res.status(400).json({
        statusCode: 400,
        message: "Owner cannot alter their own primary root ownership role."
      });
    }

    const effectiveLabId = authUser.labId || authUser.id;
    const targetUser = usersDb.find(u => u.id === id && (u.labId === effectiveLabId || u.id === effectiveLabId));

    if (!targetUser) {
      return res.status(404).json({ statusCode: 404, message: "User not found in your laboratory." });
    }

    if (role && ["ADMIN", "STAFF", "VIEWER"].includes(role)) {
      targetUser.customerRole = role;
    }

    if (Array.isArray(permissions)) {
      targetUser.customerPermissions = permissions;
    }

    targetUser.updatedAt = new Date().toISOString();

    res.json({
      statusCode: 200,
      message: "Role and permissions updated successfully.",
      user: {
        id: targetUser.id,
        customerRole: targetUser.customerRole,
        customerPermissions: targetUser.customerPermissions
      }
    });
  });

  // 14. Customer Financial Status Summary (Visible to Owner & Admin; payment authority check)
  app.get("/api/v1/customer/financial-status", authenticateJwt as any, (req: AuthenticatedRequest, res) => {
    const authUser = req.user!;
    const { customerId } = req.query;

    if (authUser.roleType === UserRoleType.CUSTOMER) {
      if (customerId && customerId !== authUser.id && customerId !== authUser.labId) {
        return res.status(403).json({
          statusCode: 403,
          error: "CUSTOMER_ISOLATION_VIOLATION",
          message: "Access Denied: You cannot view financial records of another customer account."
        });
      }
    }

    const effectiveCustomerId = authUser.roleType === UserRoleType.CUSTOMER ? (authUser.labId || authUser.id) : ((customerId as string) || authUser.labId || authUser.id);
    let profile = customerCreditProfilesDb[effectiveCustomerId];
    let wallet = customerWalletsDb[effectiveCustomerId];

    const canMakePayments = Boolean(
      authUser && ((authUser as any).customerRole === "OWNER" || (authUser.permissions && (authUser.permissions.includes("payments:make") || authUser.permissions.includes("payments:confirm"))))
    );

    // Reconcile with authoritative double-entry accounting ledger balance
    let reconciledOutstanding = wallet?.currentOutstanding ?? profile?.currentOutstanding ?? 0;
    try {
      const acctSnapshot = accountingSyncEngine.getCustomerOutstanding(effectiveCustomerId);
      if (acctSnapshot && typeof acctSnapshot.netOutstandingBalance === "number") {
        reconciledOutstanding = acctSnapshot.netOutstandingBalance;
      }
    } catch (_e) {
      // Fallback safely to wallet/profile if snapshot unavailable
    }

    const creditLimitVal = profile?.creditLimit ?? 250000;
    const finData = {
      totalOutstanding: reconciledOutstanding,
      overdueAmount: profile?.overdueAmount ?? 0,
      dueSoonAmount: profile?.dueSoonAmount ?? 0,
      creditLimit: creditLimitVal,
      availableCredit: Math.max(0, creditLimitVal - reconciledOutstanding),
      dueDate: profile?.dueDate || new Date(Date.now() + 30 * 86400000).toISOString().split("T")[0],
      daysOverdue: profile?.daysOverdue || 0,
      paymentStatus: profile?.paymentStatus || "GOOD_STANDING",
      paymentReliability: profile?.paymentReliability || "EXCELLENT",
      canMakePayments: Boolean(canMakePayments),
      paymentAuthority: canMakePayments ? "FULL_PAYMENT_AUTHORITY" : "VIEW_ONLY_AUTHORITY",
      walletPoints: (wallet as any)?.pointsBalance ?? profile?.walletPoints ?? 1250,
      paymentHistory: profile?.paymentHistory || []
    };

    res.json({
      statusCode: 200,
      ...finData,
      data: finData
    });
  });

  // 15. Settle Overdue Payment (Strict Payment Authority Required)
  app.post("/api/v1/customer/payments/settle-overdue", authenticateJwt as any, (req: AuthenticatedRequest, res) => {
    const authUser = req.user!;
    const { customerId, amount, paymentMode = "IMPS / UPI Transfer" } = req.body;

    if (authUser.roleType === UserRoleType.CUSTOMER) {
      if (customerId && customerId !== authUser.id && customerId !== authUser.labId) {
        return res.status(403).json({
          statusCode: 403,
          error: "CUSTOMER_ISOLATION_VIOLATION",
          message: "Access Denied: You cannot settle payments for another customer account."
        });
      }
    }

    // Strict Payment Authority Enforcement
    const canMakePayments = Boolean(authUser && ((authUser as any).customerRole === "OWNER" || (authUser.permissions && (authUser.permissions.includes("payments:make") || authUser.permissions.includes("payments:confirm")))));
    if (!canMakePayments) {
      return res.status(403).json({
        statusCode: 403,
        error: "UNAUTHORIZED_PAYMENT_ATTEMPT",
        message: "Payment authority denied: Only Laboratory Owner can authorize or make payments. Admin has view-only financial authority."
      });
    }

    const effectiveCustomerId = authUser.roleType === UserRoleType.CUSTOMER ? (authUser.labId || authUser.id) : (customerId || authUser.labId || authUser.id);
    const profile = customerCreditProfilesDb[effectiveCustomerId];
    const wallet = customerWalletsDb[effectiveCustomerId];

    const paymentAmount = Number(amount) || profile.overdueAmount || 35000;

    if (wallet) {
      wallet.currentOutstanding = Math.max(0, wallet.currentOutstanding - paymentAmount);
      wallet.availableCredit = Math.min(wallet.creditLimit, wallet.availableCredit + paymentAmount);
      wallet.ledgerEntries.unshift({
        id: `led-${Date.now()}`,
        date: new Date().toISOString().split("T")[0],
        type: "PAYMENT_CREDIT",
        description: `Overdue Payment Received (${paymentMode})`,
        referenceNumber: `PAY-MH-${Math.floor(10000 + Math.random() * 90000)}`,
        amount: -paymentAmount,
        runningBalance: wallet.currentOutstanding
      });
    }

    if (profile) {
      profile.currentOutstanding = wallet?.currentOutstanding ?? 0;
      profile.availableCredit = wallet?.availableCredit ?? profile.creditLimit;
      profile.overdueAmount = 0;
      profile.daysOverdue = 0;
      profile.paymentStatus = "GOOD_STANDING";
      profile.paymentHistory = profile.paymentHistory || [];
      profile.paymentHistory.unshift({
        id: `ph-${Date.now()}`,
        invoiceNumber: `INV-2026-${Math.floor(1000 + Math.random() * 9000)}`,
        orderNumber: `ORD-2026-${Math.floor(1000 + Math.random() * 9000)}`,
        amount: paymentAmount,
        paymentDate: new Date().toISOString().split("T")[0],
        paymentMethod: paymentMode,
        onTime: true,
        daysLate: 0
      });
    }

    logAudit(req, "CUSTOMER_PAYMENT_SUCCESS", "FINANCE", "SUCCESS", {
      resourceType: "PAYMENT",
      resourceId: effectiveCustomerId,
      details: {
        customerId: effectiveCustomerId,
        amount: paymentAmount,
        authorizedBy: authUser?.email || "owner"
      }
    });

    persistAllBusinessData();

    res.json({
      statusCode: 200,
      message: `Overdue settlement of ₹${paymentAmount.toLocaleString("en-IN")} captured successfully! Account restored to Good Standing.`,
      data: {
        settledAmount: paymentAmount,
        remainingOutstanding: wallet ? wallet.currentOutstanding : 0,
        availableCredit: wallet ? wallet.availableCredit : 500000,
        paymentStatus: "GOOD_STANDING"
      }
    });
  });

