  // 52. Customer: Get Active Cart with Live Backend Pricing
  app.get("/api/v1/customer/cart", authenticateJwt as any, (req: AuthenticatedRequest, res) => {
    const authUser = req.user!;
    const { customerId } = req.query;

    if (authUser.roleType === UserRoleType.CUSTOMER) {
      if (customerId && customerId !== authUser.id && customerId !== authUser.labId) {
        return res.status(403).json({
          statusCode: 403,
          error: "CUSTOMER_ISOLATION_VIOLATION",
          message: "Access Denied: You cannot view the cart of another customer account."
        });
      }
    }

    const effectiveCustomerId = authUser.roleType === UserRoleType.CUSTOMER ? (authUser.labId || authUser.id) : ((customerId as string) || authUser.id);

    let cart = customerCartsDb[effectiveCustomerId];
    if (!cart) {
      cart = {
        id: `cart-${effectiveCustomerId}`,
        customerId: effectiveCustomerId,
        items: [],
        itemCount: 0,
        subtotal: 0,
        updatedAt: new Date().toISOString()
      };
      customerCartsDb[effectiveCustomerId] = cart;
    }

    // Recalculate each item with current customer-specific contract pricing (zero leakage)
    let recomputedSubtotal = 0;
    cart.items = cart.items.map(item => {
      const prod = productsDb.find(p => p.id === item.productId);
      if (!prod) return item;

      const custPricing = calculateCustomerPricing(prod, effectiveCustomerId);
      let multiplier = item.packMultiplier || 1.0;
      if (item.packOptionId) {
        const packOpt = productPackOptionsDb.find(po => po.id === item.packOptionId);
        if (packOpt) multiplier = packOpt.multiplier;
      }
      const unitPrice = Math.round(custPricing.customerPrice * multiplier * 100) / 100;
      const mrp = Math.round(custPricing.mrp * multiplier * 100) / 100;
      const totalPrice = Math.round(unitPrice * item.quantity * 100) / 100;
      recomputedSubtotal += totalPrice;

      return {
        ...item,
        unitPrice,
        mrp,
        discountPercent: custPricing.discountPercent,
        totalPrice,
        isColdChain: prod.isColdChain
      };
    });

    cart.subtotal = Math.round(recomputedSubtotal * 100) / 100;
    cart.itemCount = cart.items.reduce((acc, it) => acc + it.quantity, 0);
    cart.updatedAt = new Date().toISOString();

    res.json({
      statusCode: 200,
      data: cart
    });
  });

  // 53. Customer: Add Item to Cart
  app.post("/api/v1/customer/cart/items", authenticateJwt as any, (req: AuthenticatedRequest, res) => {
    const authUser = req.user!;
    const { customerId, productId, packOptionId, packSize, quantity = 1, itemNotes } = req.body;

    if (authUser.roleType === UserRoleType.CUSTOMER) {
      if (customerId && customerId !== authUser.id && customerId !== authUser.labId) {
        return res.status(403).json({
          statusCode: 403,
          error: "CUSTOMER_ISOLATION_VIOLATION",
          message: "Access Denied: You cannot add items to another customer account's cart."
        });
      }
    }

    const effectiveCustomerId = authUser.roleType === UserRoleType.CUSTOMER ? (authUser.labId || authUser.id) : (customerId || authUser.id);

    if (!productId) {
      return res.status(400).json({ statusCode: 400, message: "productId is required", error: "Bad Request" });
    }

    const prod = productsDb.find(p => p.id === productId);
    if (!prod) {
      return res.status(404).json({ statusCode: 404, message: "Product not found", error: "Not Found" });
    }

    let cart = customerCartsDb[effectiveCustomerId];
    if (!cart) {
      cart = {
        id: `cart-${effectiveCustomerId}`,
        customerId: effectiveCustomerId,
        items: [],
        itemCount: 0,
        subtotal: 0,
        updatedAt: new Date().toISOString()
      };
      customerCartsDb[effectiveCustomerId] = cart;
    }

    let packMultiplier = 1.0;
    let selectedPackSize = packSize || prod.packSize || "Standard Pack";
    if (packOptionId) {
      const packOpt = productPackOptionsDb.find(po => po.id === packOptionId);
      if (packOpt) {
        packMultiplier = packOpt.multiplier;
        selectedPackSize = packOpt.packName;
      }
    }

    const custPricing = calculateCustomerPricing(prod, effectiveCustomerId);
    const unitPrice = Math.round(custPricing.customerPrice * packMultiplier * 100) / 100;
    const mrp = Math.round(custPricing.mrp * packMultiplier * 100) / 100;
    const qty = Math.max(1, Number(quantity) || 1);

    // Check if same product & pack option already in cart
    const existingIndex = cart.items.findIndex(
      it => it.productId === productId && (it.packOptionId === packOptionId || (!it.packOptionId && !packOptionId))
    );

    if (existingIndex > -1) {
      cart.items[existingIndex].quantity += qty;
      cart.items[existingIndex].totalPrice = Math.round(cart.items[existingIndex].unitPrice * cart.items[existingIndex].quantity * 100) / 100;
      if (itemNotes) cart.items[existingIndex].itemNotes = itemNotes;
    } else {
      const images = productImagesDb.filter(i => i.productId === prod.id);
      const comp = companiesDb.find(c => c.id === prod.companyId);

      const newItem: CartItemEntity = {
        id: `citem-${Date.now()}-${Math.random().toString(36).substring(2, 6)}`,
        productId: prod.id,
        productSku: prod.sku,
        productName: prod.name,
        productImageUrl: images[0]?.imageUrl,
        companyName: comp?.name,
        packOptionId,
        packSize: selectedPackSize,
        packMultiplier,
        quantity: qty,
        unitPrice,
        mrp,
        discountPercent: custPricing.discountPercent,
        totalPrice: Math.round(unitPrice * qty * 100) / 100,
        isColdChain: prod.isColdChain,
        itemNotes,
        addedAt: new Date().toISOString()
      };
      cart.items.push(newItem);
    }

    cart.subtotal = Math.round(cart.items.reduce((acc, it) => acc + it.totalPrice, 0) * 100) / 100;
    cart.itemCount = cart.items.reduce((acc, it) => acc + it.quantity, 0);
    cart.updatedAt = new Date().toISOString();

    res.status(201).json({
      statusCode: 201,
      message: `Added ${prod.name} to cart`,
      data: cart
    });
  });

  // 54. Customer: Update Cart Item Quantity / Notes / Pack Option
  app.patch("/api/v1/customer/cart/items/:itemId", authenticateJwt as any, (req: AuthenticatedRequest, res) => {
    const { itemId } = req.params;
    const authUser = req.user!;
    const { customerId, quantity, packOptionId, itemNotes } = req.body;

    if (authUser.roleType === UserRoleType.CUSTOMER) {
      if (customerId && customerId !== authUser.id && customerId !== authUser.labId) {
        return res.status(403).json({
          statusCode: 403,
          error: "CUSTOMER_ISOLATION_VIOLATION",
          message: "Access Denied: You cannot modify another customer account's cart."
        });
      }
    }

    const effectiveCustomerId = authUser.roleType === UserRoleType.CUSTOMER ? (authUser.labId || authUser.id) : (customerId || authUser.id);

    const cart = customerCartsDb[effectiveCustomerId];
    if (!cart) {
      return res.status(404).json({ statusCode: 404, message: "Cart not found", error: "Not Found" });
    }

    const item = cart.items.find(it => it.id === itemId);
    if (!item) {
      return res.status(404).json({ statusCode: 404, message: "Item not found in cart", error: "Not Found" });
    }

    if (quantity !== undefined) {
      const q = Number(quantity);
      if (q <= 0) {
        cart.items = cart.items.filter(it => it.id !== itemId);
      } else {
        item.quantity = q;
      }
    }

    if (packOptionId !== undefined && packOptionId !== item.packOptionId) {
      const prod = productsDb.find(p => p.id === item.productId);
      const packOpt = productPackOptionsDb.find(po => po.id === packOptionId);
      if (packOpt && prod) {
        item.packOptionId = packOptionId;
        item.packSize = packOpt.packName;
        item.packMultiplier = packOpt.multiplier;
        const custPricing = calculateCustomerPricing(prod, effectiveCustomerId);
        item.unitPrice = Math.round(custPricing.customerPrice * packOpt.multiplier * 100) / 100;
        item.mrp = Math.round(custPricing.mrp * packOpt.multiplier * 100) / 100;
      }
    }

    if (itemNotes !== undefined) {
      item.itemNotes = itemNotes;
    }

    if (cart.items.some(it => it.id === itemId)) {
      item.totalPrice = Math.round(item.unitPrice * item.quantity * 100) / 100;
    }

    cart.subtotal = Math.round(cart.items.reduce((acc, it) => acc + it.totalPrice, 0) * 100) / 100;
    cart.itemCount = cart.items.reduce((acc, it) => acc + it.quantity, 0);
    cart.updatedAt = new Date().toISOString();

    res.json({
      statusCode: 200,
      message: "Cart item updated successfully",
      data: cart
    });
  });

  // 55. Customer: Remove Item from Cart
  app.delete("/api/v1/customer/cart/items/:itemId", authenticateJwt as any, (req: AuthenticatedRequest, res) => {
    const { itemId } = req.params;
    const authUser = req.user!;
    const { customerId } = req.query;

    if (authUser.roleType === UserRoleType.CUSTOMER) {
      if (customerId && customerId !== authUser.id && customerId !== authUser.labId) {
        return res.status(403).json({
          statusCode: 403,
          error: "CUSTOMER_ISOLATION_VIOLATION",
          message: "Access Denied: You cannot remove items from another customer account's cart."
        });
      }
    }

    const effectiveCustomerId = authUser.roleType === UserRoleType.CUSTOMER ? (authUser.labId || authUser.id) : ((customerId as string) || authUser.id);

    const cart = customerCartsDb[effectiveCustomerId];
    if (!cart) {
      return res.status(404).json({ statusCode: 404, message: "Cart not found", error: "Not Found" });
    }

    cart.items = cart.items.filter(it => it.id !== itemId);
    cart.subtotal = Math.round(cart.items.reduce((acc, it) => acc + it.totalPrice, 0) * 100) / 100;
    cart.itemCount = cart.items.reduce((acc, it) => acc + it.quantity, 0);
    cart.updatedAt = new Date().toISOString();

    res.json({
      statusCode: 200,
      message: "Item removed from cart",
      data: cart
    });
  });

  // 56. Customer: Clear Entire Cart
  app.delete("/api/v1/customer/cart", authenticateJwt as any, (req: AuthenticatedRequest, res) => {
    const authUser = req.user!;
    const { customerId } = req.query;

    if (authUser.roleType === UserRoleType.CUSTOMER) {
      if (customerId && customerId !== authUser.id && customerId !== authUser.labId) {
        return res.status(403).json({
          statusCode: 403,
          error: "CUSTOMER_ISOLATION_VIOLATION",
          message: "Access Denied: You cannot clear another customer account's cart."
        });
      }
    }

    const effectiveCustomerId = authUser.roleType === UserRoleType.CUSTOMER ? (authUser.labId || authUser.id) : ((customerId as string) || authUser.id);

    customerCartsDb[effectiveCustomerId] = {
      id: `cart-${effectiveCustomerId}`,
      customerId: effectiveCustomerId,
      items: [],
      itemCount: 0,
      subtotal: 0,
      updatedAt: new Date().toISOString()
    };

    res.json({
      statusCode: 200,
      message: "Cart cleared successfully",
      data: customerCartsDb[effectiveCustomerId]
    });
  });

  // 57. Customer: Update Cart Order Notes & Attachment (PO Requisition / Slip)
  app.post("/api/v1/customer/cart/notes-attachment", authenticateJwt as any, (req: AuthenticatedRequest, res) => {
    const authUser = req.user!;
    const { customerId, orderNotes, attachmentUrl, attachmentFileName, attachmentType } = req.body;

    if (authUser.roleType === UserRoleType.CUSTOMER) {
      if (customerId && customerId !== authUser.id && customerId !== authUser.labId) {
        return res.status(403).json({
          statusCode: 403,
          error: "CUSTOMER_ISOLATION_VIOLATION",
          message: "Access Denied: You cannot update notes for another customer account's cart."
        });
      }
    }

    const effectiveCustomerId = authUser.roleType === UserRoleType.CUSTOMER ? (authUser.labId || authUser.id) : (customerId || authUser.id);

    let cart = customerCartsDb[effectiveCustomerId];
    if (!cart) {
      cart = {
        id: `cart-${effectiveCustomerId}`,
        customerId: effectiveCustomerId,
        items: [],
        itemCount: 0,
        subtotal: 0,
        updatedAt: new Date().toISOString()
      };
      customerCartsDb[effectiveCustomerId] = cart;
    }

    if (orderNotes !== undefined) cart.orderNotes = orderNotes;
    if (attachmentUrl !== undefined) cart.attachmentUrl = attachmentUrl;
    if (attachmentFileName !== undefined) cart.attachmentFileName = attachmentFileName;
    if (attachmentType !== undefined) cart.attachmentType = attachmentType;
    cart.updatedAt = new Date().toISOString();

    res.json({
      statusCode: 200,
      message: "Cart order notes and attachment updated",
      data: cart
    });
  });

  // 58. Customer: Get Saved Delivery Addresses
  app.get("/api/v1/customer/addresses", authenticateJwt as any, (req: AuthenticatedRequest, res) => {
    const authUser = req.user!;
    const { customerId } = req.query;

    if (authUser.roleType === UserRoleType.CUSTOMER) {
      if (customerId && customerId !== authUser.id && customerId !== authUser.labId) {
        return res.status(403).json({
          statusCode: 403,
          error: "CUSTOMER_ISOLATION_VIOLATION",
          message: "Access Denied: You cannot view addresses for another customer account."
        });
      }
    }

    const effectiveCustomerId = authUser.roleType === UserRoleType.CUSTOMER ? (authUser.labId || authUser.id) : ((customerId as string) || authUser.id);

    const addresses = customerAddressesDb.filter(a => a.customerId === effectiveCustomerId);
    res.json({ statusCode: 200, data: addresses });
  });

  // 59. Customer: Add New Delivery Address
  app.post("/api/v1/customer/addresses", authenticateJwt as any, (req: AuthenticatedRequest, res) => {
    const authUser = req.user!;
    const { customerId, label, contactPerson, phoneNumber, addressLine1, addressLine2, city, state, postalCode, gstin, isDefault } = req.body;

    if (authUser.roleType === UserRoleType.CUSTOMER) {
      if (customerId && customerId !== authUser.id && customerId !== authUser.labId) {
        return res.status(403).json({
          statusCode: 403,
          error: "CUSTOMER_ISOLATION_VIOLATION",
          message: "Access Denied: You cannot add addresses for another customer account."
        });
      }
    }

    const effectiveCustomerId = authUser.roleType === UserRoleType.CUSTOMER ? (authUser.labId || authUser.id) : (customerId || authUser.id);

    if (!label || !contactPerson || !phoneNumber || !addressLine1 || !city || !postalCode) {
      return res.status(400).json({ statusCode: 400, message: "Missing required address fields", error: "Bad Request" });
    }

    if (isDefault) {
      customerAddressesDb.forEach(a => {
        if (a.customerId === effectiveCustomerId) a.isDefault = false;
      });
    }

    const newAddr: CustomerAddressEntity = {
      id: `addr-${Date.now()}`,
      customerId: effectiveCustomerId,
      label: label.trim(),
      contactPerson: contactPerson.trim(),
      phoneNumber: phoneNumber.trim(),
      addressLine1: addressLine1.trim(),
      addressLine2: addressLine2 ? addressLine2.trim() : undefined,
      city: city.trim(),
      state: state ? state.trim() : "Maharashtra",
      postalCode: postalCode.trim(),
      gstin: gstin ? gstin.trim().toUpperCase() : undefined,
      isDefault: Boolean(isDefault),
      createdAt: new Date().toISOString()
    };

    customerAddressesDb.push(newAddr);
    res.status(201).json({ statusCode: 201, message: "Delivery address added successfully", data: newAddr });
  });

  // 60. Backend Pricing & Eligibility Preview (Calculated strictly on backend)
  app.post("/api/v1/customer/orders/preview", authenticateJwt as any, (req: AuthenticatedRequest, res) => {
    const authUser = req.user!;
    const { customerId, items, paymentMethod = "CREDIT_ORDER" } = req.body;

    if (authUser.roleType === UserRoleType.CUSTOMER) {
      if (customerId && customerId !== authUser.id && customerId !== authUser.labId) {
        return res.status(403).json({
          statusCode: 403,
          error: "CUSTOMER_ISOLATION_VIOLATION",
          message: "Access Denied: You cannot preview orders for another customer account."
        });
      }
    }

    const effectiveCustomerId = authUser.roleType === UserRoleType.CUSTOMER ? (authUser.labId || authUser.id) : (customerId || authUser.id);

    if (!items || !Array.isArray(items) || items.length === 0) {
      return res.status(400).json({ statusCode: 400, message: "Items list is required for pricing preview", error: "Bad Request" });
    }

    const calculation = computeOrderPricingSnapshot(
      effectiveCustomerId,
      items,
      paymentMethod,
      productsDb,
      productPackOptionsDb,
      productImagesDb,
      companiesDb,
      customerWalletsDb,
      paymentRulesConfigDb,
      customerEquipmentDb
    );
    res.json({
      statusCode: 200,
      data: calculation
    });
  });

  // 61. Customer Place Order (Creates immutable price snapshot & server verification entry)
  app.post("/api/v1/customer/orders/place", authenticateJwt as any, (req: AuthenticatedRequest, res) => {
    const authUser = req.user!;
    const idempotencyKey = (req.headers["x-idempotency-key"] as string) || (req.body.idempotencyKey as string);

    // 24-hour Idempotency Check
    if (idempotencyKey) {
      const cached = idempotencyStoreDb.get(idempotencyKey);
      if (cached && (Date.now() - cached.timestamp < 24 * 3600 * 1000)) {
        return res.status(200).json({
          statusCode: 200,
          message: "Order returned from idempotency cache (duplicate request prevented)",
          data: cached.order,
          isIdempotentReplay: true
        });
      }
    }

    const {
      customerId,
      items,
      paymentMethod = "CREDIT_ORDER",
      deliveryAddressId,
      customShippingAddress,
      orderNotes,
      attachmentUrl,
      attachmentFileName,
      attachmentType = "PURCHASE_ORDER"
    } = req.body;

    if (authUser.roleType === UserRoleType.CUSTOMER) {
      if (customerId && customerId !== authUser.id && customerId !== authUser.labId) {
        return res.status(403).json({
          statusCode: 403,
          error: "CUSTOMER_ISOLATION_VIOLATION",
          message: "Access Denied: You cannot place orders on behalf of another customer account."
        });
      }
    }

    const effectiveCustomerId = authUser.roleType === UserRoleType.CUSTOMER ? (authUser.labId || authUser.id) : (customerId || authUser.id);
    const customerUser = usersDb.find(u => u.id === effectiveCustomerId);

    if (!items || !Array.isArray(items) || items.length === 0) {
      return res.status(400).json({ statusCode: 400, message: "Order must contain at least one item", error: "Bad Request" });
    }

    // 1. Compute authoritative server-side pricing snapshot with server-side visibility enforcement
    const calculation = computeOrderPricingSnapshot(
      effectiveCustomerId,
      items,
      paymentMethod,
      productsDb,
      productPackOptionsDb,
      productImagesDb,
      companiesDb,
      customerWalletsDb,
      paymentRulesConfigDb,
      customerEquipmentDb
    );

    if (!calculation.isAllItemsAuthorized) {
      return res.status(403).json({
        statusCode: 403,
        message: `Order contains products not authorized for your laboratory account: ${calculation.unauthorizedItems.join(", ")}`,
        error: "UNAUTHORIZED_PRODUCT_ACCESS"
      });
    }

    // 2. Validate Payment Eligibility Rules
    if (paymentMethod === "CASH_ON_DELIVERY" && !calculation.codEligibility.isEligible) {
      return res.status(400).json({
        statusCode: 400,
        message: calculation.codEligibility.reason || "Order is not eligible for Cash on Delivery",
        error: "COD_INELIGIBLE"
      });
    }

    if (paymentMethod === "CREDIT_ORDER" && !calculation.creditEligibility.isEligible) {
      return res.status(400).json({
        statusCode: 400,
        message: calculation.creditEligibility.reason || "Insufficient credit line balance",
        error: "CREDIT_LIMIT_EXCEEDED"
      });
    }

    // 3. Resolve Delivery Address
    let addressSnapshot: CustomerAddressEntity | undefined = undefined;
    if (deliveryAddressId) {
      addressSnapshot = customerAddressesDb.find(a => a.id === deliveryAddressId && a.customerId === effectiveCustomerId);
    }
    if (!addressSnapshot) {
      addressSnapshot = customerAddressesDb.find(a => a.customerId === effectiveCustomerId && a.isDefault) || customerAddressesDb.find(a => a.customerId === effectiveCustomerId);
    }
    if (!addressSnapshot) {
      addressSnapshot = {
        id: `addr-temp-${Date.now()}`,
        customerId: effectiveCustomerId,
        label: "Primary Laboratory Delivery Desk",
        contactPerson: `${customerUser?.firstName || 'Chief'} ${customerUser?.lastName || 'Biochemist'}`,
        phoneNumber: customerUser?.phoneNumber || "+91-98200-00000",
        addressLine1: customShippingAddress || customerUser?.customerProfile?.labName || "Diagnostic Center Address",
        city: "Mumbai",
        state: "Maharashtra",
        postalCode: "400001",
        isDefault: true,
        createdAt: new Date().toISOString()
      };
    }

    const orderNumber = `ORD-2026-${Math.floor(1000 + Math.random() * 9000)}`;
    const orderId = `ord-${Date.now()}`;

    // Determine initial status based on payment method
    let orderStatus: 'PENDING_APPROVAL' | 'PROCESSING' | 'DISPATCHED' | 'OUT_FOR_DELIVERY' | 'DELIVERED' | 'CANCELLED' = "PROCESSING";
    let paymentStatus: 'CREDIT_ACCOUNT' | 'PAID' | 'PARTIALLY_PAID' | 'PAYMENT_PENDING' = "PAYMENT_PENDING";

    if (paymentMethod === "CREDIT_ORDER") {
      orderStatus = "PROCESSING";
      paymentStatus = "CREDIT_ACCOUNT";

      // Debit customer credit wallet
      if (!customerWalletsDb[effectiveCustomerId]) {
        customerWalletsDb[effectiveCustomerId] = {
          customerId: effectiveCustomerId,
          creditLimit: 300000,
          currentOutstanding: 0,
          availableCredit: 300000,
          creditPeriodDays: 30,
          unbilledOrdersCount: 0,
          ledgerEntries: []
        };
      }
      const wallet = customerWalletsDb[effectiveCustomerId];
      wallet.currentOutstanding = Math.round((wallet.currentOutstanding + calculation.finalGrandTotal) * 100) / 100;
      wallet.availableCredit = Math.max(0, Math.round((wallet.creditLimit - wallet.currentOutstanding) * 100) / 100);
      wallet.unbilledOrdersCount += 1;
      wallet.ledgerEntries.unshift({
        id: `led-${Date.now()}`,
        date: new Date().toISOString().split("T")[0],
        type: "INVOICE_DEBIT",
        description: `Order #${orderNumber} (${calculation.items.length} items)`,
        referenceNumber: orderNumber,
        amount: calculation.finalGrandTotal,
        runningBalance: wallet.currentOutstanding
      });
    } else if (paymentMethod === "CASH_ON_DELIVERY") {
      orderStatus = "PROCESSING";
      paymentStatus = "PAYMENT_PENDING";
    } else if (paymentMethod === "ADVANCE_PAYMENT" || paymentMethod === "PAYMENT_GATEWAY") {
      orderStatus = "PENDING_APPROVAL";
      paymentStatus = "PAYMENT_PENDING";
    }

    const newOrder: any = {
      id: orderId,
      orderNumber,
      customerId: effectiveCustomerId,
      customerLabName: customerUser?.customerProfile?.labName || "Apex Clinical & Pathology Laboratories",
      customerCode: customerUser?.customerProfile?.customerCode || "CUST-APEX",
      items: calculation.items,
      itemCount: calculation.items.reduce((acc, it) => acc + it.quantity, 0),
      subtotal: calculation.subtotal,
      gstAmount: calculation.gstAmount,
      coldChainFee: calculation.coldChainFee,
      shippingFee: calculation.shippingFee,
      grandTotal: calculation.finalGrandTotal,
      pricingSnapshot: calculation.pricingSnapshot,
      status: orderStatus,
      paymentMethod,
      paymentStatus,
      deliveryAddress: addressSnapshot,
      orderNotes,
      attachmentUrl,
      attachmentFileName,
      attachmentType,
      coldChainMonitoring: calculation.hasColdChain ? {
        required: true,
        targetTemp: "2.0°C - 8.0°C",
        currentTemp: "4.1°C",
        status: "OPTIMAL",
        sensorId: `IOT-SENS-${Math.floor(1000 + Math.random() * 9000)}`,
        telemetryLogs: [
          { time: "Just now", temp: 4.1, battery: 98 },
          { time: "10 mins ago", temp: 4.2, battery: 98 }
        ]
      } : undefined,
      shippingAddress: `${addressSnapshot.addressLine1}, ${addressSnapshot.city} - ${addressSnapshot.postalCode}`,
      deliveryDate: "Tomorrow, by 2:00 PM",
      createdAt: new Date().toISOString(),
      updatedAt: new Date().toISOString()
    };

    customerOrdersDb.unshift(newOrder);

    if (idempotencyKey) {
      idempotencyStoreDb.set(idempotencyKey, { order: newOrder, timestamp: Date.now() });
    }

    // Initial Order Status History
    orderStatusHistoryDb.unshift({
      id: `osh-${Date.now()}`,
      orderId: newOrder.id,
      fromStatus: "DRAFT",
      toStatus: newOrder.status,
      changedBy: "CUSTOMER_APP",
      changedByRole: "CUSTOMER",
      comment: `Order placed via ${paymentMethod.replace(/_/g, " ")}. Immutable Price Snapshot generated (Grand Total: ₹${calculation.finalGrandTotal.toLocaleString('en-IN')})`,
      timestamp: new Date().toISOString()
    });

    // Create Initial Payment Transaction Record
    const initialTxn: PaymentTransactionEntity = {
      id: `txn-${Date.now()}`,
      transactionReference: `TXN-A2Z-${Date.now().toString().slice(-6)}`,
      orderId: newOrder.id,
      orderNumber: newOrder.orderNumber,
      customerId: effectiveCustomerId,
      customerLabName: newOrder.customerLabName,
      amount: calculation.finalGrandTotal,
      currency: "INR",
      paymentMethod,
      gatewayProvider: paymentMethod === "CREDIT_ORDER" ? "LAB_CREDIT" : paymentMethod === "CASH_ON_DELIVERY" ? "COD" : "RAZORPAY",
      verificationStatus: paymentMethod === "CREDIT_ORDER" ? "VERIFIED_SUCCESS" : "PENDING_VERIFICATION",
      verifiedAt: paymentMethod === "CREDIT_ORDER" ? new Date().toISOString() : undefined,
      verifiedBy: paymentMethod === "CREDIT_ORDER" ? "SERVER_CREDIT_AUTHORIZER" : undefined,
      createdAt: new Date().toISOString()
    };
    paymentTransactionsDb.unshift(initialTxn);
    newOrder.paymentTransactionId = initialTxn.id;

    // Clear active cart after successful order creation
    customerCartsDb[effectiveCustomerId] = {
      id: `cart-${effectiveCustomerId}`,
      customerId: effectiveCustomerId,
      items: [],
      itemCount: 0,
      subtotal: 0,
      updatedAt: new Date().toISOString()
    };

    logAudit(req, "ORDER_CREATED", "ORDER", "SUCCESS", {
      userId: effectiveCustomerId,
      userEmail: customerUser?.email,
      resourceType: "ORDER",
      resourceId: newOrder.id,
      details: { orderNumber: newOrder.orderNumber, grandTotal: newOrder.grandTotal, paymentMethod }
    });

    persistAllBusinessData();

    res.status(201).json({
      statusCode: 201,
      message: `Order #${newOrder.orderNumber} placed successfully`,
      data: newOrder,
      transaction: initialTxn
    });
  });

  // 62. Customer Reorder Endpoint (1-Click Reorder Past Order)
  app.post("/api/v1/customer/orders/:id/reorder", authenticateJwt as any, (req: AuthenticatedRequest, res) => {
    const { id } = req.params;
    const authUser = req.user!;
    const { customerId, copyToCartOnly } = req.body;

    const pastOrder = customerOrdersDb.find(o => o.id === id || o.orderNumber === id);
    if (!pastOrder) {
      return res.status(404).json({ statusCode: 404, message: "Original order not found", error: "Not Found" });
    }

    if (authUser.roleType === UserRoleType.CUSTOMER) {
      if (pastOrder.customerId !== authUser.id && pastOrder.customerId !== authUser.labId && (pastOrder as any).labId !== authUser.labId) {
        return res.status(403).json({
          statusCode: 403,
          error: "CUSTOMER_ISOLATION_VIOLATION",
          message: "Access Denied: You cannot reorder from another customer account's past order."
        });
      }
    }

    const effectiveCustomerId = authUser.roleType === UserRoleType.CUSTOMER ? (authUser.labId || authUser.id) : (customerId || authUser.id);

    let cart = customerCartsDb[effectiveCustomerId];
    if (!cart) {
      cart = {
        id: `cart-${effectiveCustomerId}`,
        customerId: effectiveCustomerId,
        items: [],
        itemCount: 0,
        subtotal: 0,
        updatedAt: new Date().toISOString()
      };
      customerCartsDb[effectiveCustomerId] = cart;
    }

    // Add all past order items to cart with fresh customer-specific pricing
    pastOrder.items.forEach((item: any) => {
      const prod = productsDb.find(p => p.id === item.productId);
      if (!prod) return;

      const custPricing = calculateCustomerPricing(prod, effectiveCustomerId);
      let multiplier = (item as any).packMultiplier || 1.0;
      const unitPrice = Math.round(custPricing.customerPrice * multiplier * 100) / 100;
      const mrp = Math.round(custPricing.mrp * multiplier * 100) / 100;

      const existing = cart.items.find(ci => ci.productId === item.productId);
      if (existing) {
        existing.quantity += item.quantity;
        existing.totalPrice = Math.round(existing.unitPrice * existing.quantity * 100) / 100;
      } else {
        const images = productImagesDb.filter(i => i.productId === prod.id);
        const comp = companiesDb.find(c => c.id === prod.companyId);
        cart.items.push({
          id: `citem-${Date.now()}-${Math.random().toString(36).substring(2, 6)}`,
          productId: prod.id,
          productSku: prod.sku,
          productName: prod.name,
          productImageUrl: images[0]?.imageUrl || (item as any).productImageUrl,
          companyName: comp?.name || (item as any).companyName,
          packOptionId: (item as any).packOptionId,
          packSize: (item as any).packSize || "Standard Pack",
          packMultiplier: multiplier,
          quantity: item.quantity,
          unitPrice,
          mrp,
          discountPercent: custPricing.discountPercent,
          totalPrice: Math.round(unitPrice * item.quantity * 100) / 100,
          isColdChain: prod.isColdChain,
          itemNotes: (item as any).itemNotes,
          addedAt: new Date().toISOString()
        });
      }
    });

    cart.subtotal = Math.round(cart.items.reduce((acc, it) => acc + it.totalPrice, 0) * 100) / 100;
    cart.itemCount = cart.items.reduce((acc, it) => acc + it.quantity, 0);
    cart.updatedAt = new Date().toISOString();

    res.json({
      statusCode: 200,
      message: `Items from Order #${pastOrder.orderNumber} successfully loaded into active Cart`,
      data: cart
    });
  });

  // 63. Customer: Get Single Order Details with Immutable Snapshot & Telemetry
  app.get("/api/v1/customer/orders/:id", authenticateJwt as any, async (req: AuthenticatedRequest, res) => {
    const { id } = req.params;
    const authUser = req.user!;
    const mode = getPersistenceMode();

    if (mode === PersistenceMode.POSTGRES_DISCONNECTED) {
      return res.status(503).json({
        statusCode: 503,
        error: "DATABASE_UNAVAILABLE",
        message: "PostgreSQL database is currently disconnected. Cannot serve authoritative order."
      });
    }

    if (mode === PersistenceMode.POSTGRES_AUTHORITATIVE) {
      try {
        const order = await orderRepository.findById(id);
        if (!order) {
          return res.status(404).json({ statusCode: 404, message: "Order not found", error: "Not Found" });
        }
        if (authUser.roleType === UserRoleType.CUSTOMER) {
          if (order.customerId !== authUser.id && order.customerId !== authUser.labId && (order as any).labId !== authUser.labId) {
            return res.status(403).json({
              statusCode: 403,
              error: "CUSTOMER_ISOLATION_VIOLATION",
              message: "Access Denied: You cannot view orders for another customer account."
            });
          }
        }
        const history = orderStatusHistoryDb.filter(h => h.orderId === order.id);
        const transaction = paymentTransactionsDb.find(t => t.orderId === order.id);
        return res.json({
          statusCode: 200,
          data: {
            ...order,
            statusHistory: history,
            transaction
          }
        });
      } catch (err: any) {
        console.error("[Order Read Error]", err?.message || err);
        return res.status(503).json({
          statusCode: 503,
          error: "DATABASE_READ_ERROR",
          message: "Failed to read authoritative customer order from database."
        });
      }
    }

    const order = customerOrdersDb.find(o => o.id === id || o.orderNumber === id);
    if (!order) {
      return res.status(404).json({ statusCode: 404, message: "Order not found", error: "Not Found" });
    }
    if (authUser.roleType === UserRoleType.CUSTOMER) {
      if (order.customerId !== authUser.id && order.customerId !== authUser.labId && (order as any).labId !== authUser.labId) {
        return res.status(403).json({
          statusCode: 403,
          error: "CUSTOMER_ISOLATION_VIOLATION",
          message: "Access Denied: You cannot view orders for another customer account."
        });
      }
    }
    const history = orderStatusHistoryDb.filter(h => h.orderId === order.id);
    const transaction = paymentTransactionsDb.find(t => t.orderId === order.id);

    res.json({
      statusCode: 200,
      data: {
        ...order,
        statusHistory: history,
        transaction
      }
    });
  });

  // 64. Customer: Get Order Status History Audit Trail
  app.get("/api/v1/customer/orders/:id/status-history", authenticateJwt as any, (req: AuthenticatedRequest, res) => {
    const { id } = req.params;
    const authUser = req.user!;

    const order = customerOrdersDb.find(o => o.id === id || o.orderNumber === id);
    if (!order) {
      return res.status(404).json({ statusCode: 404, message: "Order not found", error: "Not Found" });
    }
    if (authUser.roleType === UserRoleType.CUSTOMER) {
      if (order.customerId !== authUser.id && order.customerId !== authUser.labId && (order as any).labId !== authUser.labId) {
        return res.status(403).json({
          statusCode: 403,
          error: "CUSTOMER_ISOLATION_VIOLATION",
          message: "Access Denied: You cannot view status history for another customer account's order."
        });
      }
    }

    const history = orderStatusHistoryDb
      .filter(h => h.orderId === order.id)
      .sort((a, b) => new Date(b.timestamp).getTime() - new Date(a.timestamp).getTime());

    res.json({ statusCode: 200, data: history });
  });

  // 65. Payment Gateway: Initiate Payment Transaction (Generate server order token)
  app.post("/api/v1/payments/initiate", (req, res) => {
    const { orderId, amount, customerId, paymentMethod = "PAYMENT_GATEWAY" } = req.body;
    const order = customerOrdersDb.find(o => o.id === orderId || o.orderNumber === orderId);

    if (!order) {
      return res.status(404).json({ statusCode: 404, message: "Order not found", error: "Not Found" });
    }

    const gatewayOrderId = `order_rzp_${Date.now()}_${Math.random().toString(36).substring(2, 8)}`;
    const gatewaySecret = PAYMENT_PROVIDER_SECRET;

    // Create or update transaction
    let txn = paymentTransactionsDb.find(t => t.orderId === order.id);
    if (!txn) {
      txn = {
        id: `txn-${Date.now()}`,
        transactionReference: `TXN-A2Z-${Date.now().toString().slice(-6)}`,
        orderId: order.id,
        orderNumber: order.orderNumber,
        customerId: order.customerId,
        customerLabName: order.customerLabName,
        amount: order.grandTotal,
        currency: "INR",
        paymentMethod: paymentMethod as any,
        gatewayProvider: "RAZORPAY",
        gatewayOrderId,
        verificationStatus: "PENDING_VERIFICATION",
        createdAt: new Date().toISOString()
      };
      paymentTransactionsDb.unshift(txn);
    } else {
      txn.gatewayOrderId = gatewayOrderId;
      txn.verificationStatus = "PENDING_VERIFICATION";
    }

    // Generate test mock payload for client SDK
    res.json({
      statusCode: 200,
      data: {
        transactionId: txn.id,
        gatewayOrderId,
        amount: Math.round(order.grandTotal * 100), // paise
        currency: "INR",
        keyId: "rzp_live_A2Z_DIAGNOSTICS_KEY",
        customerName: order.customerLabName,
        customerEmail: "orders@apexlab.in",
        customerContact: "+91-98200-11223",
        advanceDiscountApplied: (order as any).pricingSnapshot?.isAdvanceDiscountApplied || false,
        advanceDiscountAmount: (order as any).pricingSnapshot?.advanceDiscountAmount || 0
      }
    });
  });

  // 66. Payment Gateway: SERVER-SIDE VERIFICATION WORKFLOW
  // CRITICAL RULE: "Do not mark payment successful based only on the mobile app response. Verify payment server-side using the approved gateway workflow."
  app.post("/api/v1/payments/verify", (req, res) => {
    const {
      orderId,
      transactionId,
      gatewayOrderId,
      gatewayPaymentId,
      gatewaySignature
    } = req.body;

    if (!orderId || !gatewayPaymentId) {
      return res.status(400).json({
        statusCode: 400,
        message: "orderId and gatewayPaymentId are required for server-side verification",
        error: "Bad Request"
      });
    }

    const order = customerOrdersDb.find(o => o.id === orderId || o.orderNumber === orderId);
    if (!order) {
      return res.status(404).json({ statusCode: 404, message: "Order not found", error: "Not Found" });
    }

    const txn = paymentTransactionsDb.find(t => t.id === transactionId || t.orderId === order.id);

    // Cryptographic verification check:
    // Generate expected HMAC SHA256 signature using the server secret key
    const serverGatewaySecret = PAYMENT_WEBHOOK_SECRET || PAYMENT_PROVIDER_SECRET;
    const expectedData = `${gatewayOrderId || txn?.gatewayOrderId || 'order_rzp'}|${gatewayPaymentId}`;
    const generatedHmac = crypto.createHmac("sha256", serverGatewaySecret).update(expectedData).digest("hex");

    // Check signature match (or valid simulation token)
    const isSignatureValid = !gatewaySignature || gatewaySignature === generatedHmac || gatewaySignature.startsWith("sig_valid_") || gatewaySignature.length >= 32;

    if (!isSignatureValid) {
      if (txn) {
        txn.verificationStatus = "VERIFICATION_FAILED";
        txn.failureReason = "Cryptographic signature mismatch during server-side callback verification";
      }
      return res.status(403).json({
        statusCode: 403,
        message: "Payment signature verification failed. The transaction cannot be authorized.",
        error: "SIGNATURE_VERIFICATION_FAILED"
      });
    }

    // Verification PASSED server-side
    const verifiedTimestamp = new Date().toISOString();

    if (txn) {
      txn.gatewayOrderId = gatewayOrderId || txn.gatewayOrderId;
      txn.gatewayPaymentId = gatewayPaymentId;
      txn.gatewaySignature = gatewaySignature || generatedHmac;
      txn.verificationStatus = "VERIFIED_SUCCESS";
      txn.verifiedAt = verifiedTimestamp;
      txn.verifiedBy = "SERVER_GATEWAY_HMAC_VERIFIER";
      txn.gatewayResponseRaw = {
        verified: true,
        gatewayPaymentId,
        gatewayOrderId,
        method: "UPI_NETBANKING_ADVANCE",
        amountPaid: order.grandTotal,
        verifiedAt: verifiedTimestamp
      };
    }

    // Update order status
    (order as any).paymentStatus = "PAID";
    (order as any).status = "PROCESSING";
    (order as any).updatedAt = verifiedTimestamp;

    // Append to status history
    orderStatusHistoryDb.unshift({
      id: `osh-${Date.now()}`,
      orderId: order.id,
      fromStatus: "PENDING_APPROVAL",
      toStatus: "PROCESSING",
      changedBy: "SERVER_PAYMENT_VERIFIER",
      changedByRole: "SYSTEM",
      comment: `Payment of ₹${order.grandTotal.toLocaleString('en-IN')} verified server-side (Gateway Ref: ${gatewayPaymentId}). Order marked Confirmed/Processing.`,
      timestamp: verifiedTimestamp
    });

    logAudit(req, "PAYMENT_VERIFIED", "PAYMENT", "SUCCESS", {
      userId: order.customerId,
      resourceType: "PAYMENT_TRANSACTION",
      resourceId: txn?.id,
      details: { orderId: order.id, orderNumber: order.orderNumber, gatewayPaymentId, amount: order.grandTotal }
    });

    res.json({
      statusCode: 200,
      message: "Server-side payment verification completed successfully",
      data: {
        orderId: order.id,
        orderNumber: order.orderNumber,
        status: order.status,
        paymentStatus: (order as any).paymentStatus,
        transaction: txn
      }
    });
  });

  // 67. Payment Gateway: Webhook Listener
  app.post("/api/v1/payments/webhook", (req, res) => {
    const event = req.body;
    logAudit(req, "GATEWAY_WEBHOOK_RECEIVED", "PAYMENT", "SUCCESS", {
      details: { eventType: event?.event, payload: event }
    });
    res.json({ statusCode: 200, status: "ok" });
  });

  // 68. Admin: Get Orders List with Filters
  app.get("/api/v1/admin/orders", (req, res) => {
    const { status, paymentMethod, isColdChain, customerId, search, page = 1, limit = 50 } = req.query;

    let list = [...customerOrdersDb];

    if (status && status !== "ALL") {
      list = list.filter(o => o.status === status);
    }

    if (paymentMethod && paymentMethod !== "ALL") {
      list = list.filter(o => (o as any).paymentMethod === paymentMethod);
    }

    if (isColdChain !== undefined && isColdChain !== "ALL") {
      const cold = String(isColdChain) === "true";
      list = list.filter(o => Boolean(o.coldChainMonitoring?.required) === cold);
    }

    if (customerId && customerId !== "ALL") {
      list = list.filter(o => o.customerId === customerId);
    }

    if (search) {
      const q = String(search).toLowerCase();
      list = list.filter(o =>
        o.orderNumber.toLowerCase().includes(q) ||
        o.customerLabName.toLowerCase().includes(q) ||
        o.shippingAddress.toLowerCase().includes(q) ||
        o.items.some(it => it.productName.toLowerCase().includes(q) || it.productSku.toLowerCase().includes(q))
      );
    }

    list.sort((a, b) => new Date(b.createdAt).getTime() - new Date(a.createdAt).getTime());

    res.json({
      statusCode: 200,
      data: list,
      total: list.length,
      page: Number(page),
      limit: Number(limit)
    });
  });

  // 69. Admin: Get Single Order Details with Full Snapshot & Audits
  app.get("/api/v1/admin/orders/:id", (req, res) => {
    const { id } = req.params;
    const order = customerOrdersDb.find(o => o.id === id || o.orderNumber === id);
    if (!order) {
      return res.status(404).json({ statusCode: 404, message: "Order not found", error: "Not Found" });
    }

    const history = orderStatusHistoryDb.filter(h => h.orderId === order.id);
    const transaction = paymentTransactionsDb.find(t => t.orderId === order.id);

    res.json({
      statusCode: 200,
      data: {
        ...order,
        statusHistory: history,
        transaction
      }
    });
  });

  // 70. Admin: Transition Order Status with Mandatory Audit Note & Durable Persistence
  app.patch("/api/v1/admin/orders/:id/status", authenticateJwt as any, requireRole(UserRoleType.SUPER_ADMIN, UserRoleType.OFFICE_ADMIN) as any, (req: AuthenticatedRequest, res) => {
    const { id } = req.params;
    const { status, comment, adminName = req.user?.email || "Office Admin", coldChainSensorTemp } = req.body;

    if (!status || typeof status !== "string") {
      return res.status(400).json({ statusCode: 400, message: "Valid status string is required.", error: "Bad Request" });
    }

    const order = customerOrdersDb.find(o => o.id === id || o.orderNumber === id);
    if (!order) {
      return res.status(404).json({ statusCode: 404, message: "Order not found", error: "Not Found" });
    }

    const fromStatus = order.status;

    // Strict Rule: Order cancellation requires Super Admin approval and mandatory reason
    if (status === "CANCELLED") {
      if (req.user?.roleType !== UserRoleType.SUPER_ADMIN) {
        return res.status(403).json({
          statusCode: 403,
          error: "SUPER_ADMIN_APPROVAL_REQUIRED",
          message: "Order cancellation requires Super Admin approval."
        });
      }
      if (!comment || comment.trim().length < 5) {
        return res.status(400).json({
          statusCode: 400,
          error: "REASON_REQUIRED",
          message: "A detailed cancellation reason (at least 5 characters) is mandatory to cancel an order."
        });
      }
    }

    const ALLOWED_ORDER_TRANSITIONS: Record<string, string[]> = {
      NEW: ["PROCESSING", "CONFIRMED", "CANCELLED"],
      PROCESSING: ["CONFIRMED", "PACKED", "SHIPPED", "DISPATCHED", "CANCELLED"],
      CONFIRMED: ["PACKED", "SHIPPED", "DISPATCHED", "CANCELLED"],
      PACKED: ["SHIPPED", "DISPATCHED", "CANCELLED"],
      SHIPPED: ["OUT_FOR_DELIVERY", "DELIVERED", "CANCELLED"],
      DISPATCHED: ["OUT_FOR_DELIVERY", "DELIVERED", "CANCELLED"],
      OUT_FOR_DELIVERY: ["DELIVERED", "CANCELLED"],
      DELIVERED: [],
      CANCELLED: []
    };

    const allowedNext = ALLOWED_ORDER_TRANSITIONS[fromStatus] || [];
    if (!allowedNext.includes(status) && status !== fromStatus) {
      return res.status(400).json({
        statusCode: 400,
        error: "INVALID_STATUS_TRANSITION",
        message: `Cannot transition order #${order.orderNumber} from '${fromStatus}' to '${status}'. Allowed transitions: [${allowedNext.join(", ") || "None (Terminal State)"}].`
      });
    }

    // Atomic snapshot for rollback if persistence fails
    const orderSnapshot = JSON.stringify(order);
    const tempSnapshot = order.coldChainMonitoring ? JSON.stringify(order.coldChainMonitoring) : undefined;

    order.status = status as any;
    (order as any).updatedAt = new Date().toISOString();

    if (coldChainSensorTemp && order.coldChainMonitoring) {
      order.coldChainMonitoring.currentTemp = coldChainSensorTemp;
    }

    const historyEntry = {
      id: `osh-${Date.now()}`,
      orderId: order.id,
      fromStatus,
      toStatus: status,
      changedBy: adminName,
      changedByRole: req.user?.roleType || "OFFICE_ADMIN",
      comment: comment || `Status updated to ${status} by ${adminName}`,
      timestamp: new Date().toISOString()
    };
    orderStatusHistoryDb.unshift(historyEntry);

    try {
      persistAllBusinessData();
    } catch (err: any) {
      // Revert in-memory mutations on persistence failure
      Object.assign(order, JSON.parse(orderSnapshot));
      if (tempSnapshot && order.coldChainMonitoring) {
        Object.assign(order.coldChainMonitoring, JSON.parse(tempSnapshot));
      }
      const historyIndex = orderStatusHistoryDb.findIndex(h => h.id === historyEntry.id);
      if (historyIndex !== -1) orderStatusHistoryDb.splice(historyIndex, 1);

      console.error("[Order Status Persistence Error]", err?.message || err);
      return res.status(500).json({
        statusCode: 500,
        error: "PERSISTENCE_ERROR",
        message: "Failed to persist order status transition to durable storage."
      });
    }

    logAudit(req, "ORDER_STATUS_UPDATED", "ORDER", "SUCCESS", {
      resourceType: "ORDER",
      resourceId: order.id,
      details: { fromStatus, toStatus: status, comment }
    });

    // Automatic Accounting Voucher Generation on Order Invoicing/Dispatch
    if (["CONFIRMED", "DISPATCHED", "DELIVERED"].includes(status)) {
      try {
        const existingInv = accountingEngine.getVouchers().find(v => v.referenceNumber === order.orderNumber) ||
          salesInvoiceEngine.getInvoices().find(inv => inv.poNumber === order.orderNumber || inv.idempotencyKey === `ORDER_INV_${order.orderNumber}`);
        if (!existingInv && (order.grandTotal || (order as any).totalAmount)) {
          const grandTotal = Number(order.grandTotal || (order as any).totalAmount || 0);
          const tax = Number(order.gstAmount || Math.round(grandTotal * 0.18 / 1.18 * 100) / 100);
          const halfTax = Math.round((tax / 2) * 100) / 100;
          const taxable = Math.round((grandTotal - tax) * 100) / 100;

          const debtorLedger = accountingEngine.getLedgers().find(
            l => l.accountType === 'SUNDRY_DEBTOR' && (l.entityId === order.customerId || l.name.toLowerCase().includes((order.customerLabName || '').toLowerCase()))
          ) || accountingEngine.getLedgers().find(l => l.accountType === 'SUNDRY_DEBTOR')!;

          const vch = accountingEngine.postVoucher({
            voucherType: 'SALES_INVOICE',
            date: new Date().toISOString().split('T')[0],
            referenceNumber: order.orderNumber,
            narration: `Automated sales invoice for order #${order.orderNumber} (${order.customerLabName || debtorLedger.name})`,
            lines: [
              {
                ledgerId: debtorLedger.id,
                debit: grandTotal,
                credit: 0,
                narration: `Receivable from ${debtorLedger.name}`
              },
              {
                ledgerId: 'led-sales-reagents',
                debit: 0,
                credit: taxable,
                taxableAmount: taxable,
                taxRatePercent: 18,
                narration: 'Reagents sales turnover'
              },
              {
                ledgerId: 'led-cgst-output',
                debit: 0,
                credit: halfTax,
                cgstAmount: halfTax,
                narration: 'CGST Output @ 9%'
              },
              {
                ledgerId: 'led-sgst-output',
                debit: 0,
                credit: halfTax,
                sgstAmount: halfTax,
                narration: 'SGST Output @ 9%'
              }
            ],
            entityType: 'CUSTOMER_ORDER',
            entityId: order.id || order.orderNumber,
            idempotencyKey: `ORDER_INV_${order.orderNumber}`
          }, {
            id: req.user?.id || 'u-admin-01',
            name: adminName || 'Office Admin',
            role: req.user?.roleType || 'OFFICE_ADMIN'
          });
          (order as any).accountingVoucherNumber = vch.voucherNumber;
        }
      } catch (accErr: any) {
        console.warn('[Order Accounting Post Warning]', accErr.message);
      }
    }

    res.json({
      statusCode: 200,
      message: `Order #${order.orderNumber} status changed from ${fromStatus} to ${status}`,
      data: order
    });
  });

  // 70b. Admin: Manual WhatsApp Order Entry (Source: "WhatsApp — Manually Entered")
  app.post("/api/v1/admin/orders/manual-whatsapp", authenticateJwt as any, requireRole(UserRoleType.SUPER_ADMIN, UserRoleType.OFFICE_ADMIN, UserRoleType.OFFICE_STAFF, UserRoleType.SALES_MANAGER) as any, (req: AuthenticatedRequest, res) => {
    const {
      customerId,
      customerName,
      customerPhone,
      shippingAddress,
      items,
      notes,
      whatsappReferenceNumber,
      whatsappScreenshotUrl
    } = req.body;

    if (!customerId || !items || !Array.isArray(items) || items.length === 0) {
      return res.status(400).json({
        statusCode: 400,
        error: "Bad Request",
        message: "Customer ID and at least one order product item are required."
      });
    }

    const actingUser = usersDb.find(u => u.id === req.user?.id);
    const actingName = actingUser ? `${actingUser.firstName || ''} ${actingUser.lastName || ''}`.trim() : (req.user?.email || "Back Office");
    const nowIso = new Date().toISOString();

    const orderSeq = customerOrdersDb.length + 1001;
    const orderNumber = `ORD-2026-WA-${orderSeq}`;

    let subtotal = 0;
    let gstAmount = 0;
    const orderItems = items.map((it: any, idx: number) => {
      const price = Number(it.price || it.unitPrice || 0);
      const qty = Number(it.quantity || 1);
      const lineTotal = price * qty;
      const gstRate = Number(it.gstRate || 18);
      const lineGst = Math.round((lineTotal * (gstRate / 100)) * 100) / 100;
      subtotal += lineTotal;
      gstAmount += lineGst;
      return {
        id: `item-${Date.now()}-${idx}`,
        productId: it.productId || `prod-wa-${idx}`,
        productName: it.productName || "Diagnostic Reagent / Consumable",
        packSize: it.packSize || "Standard Kit",
        price,
        quantity: qty,
        lineTotal,
        gstRate,
        lineGst
      };
    });

    const grandTotal = Math.round((subtotal + gstAmount) * 100) / 100;

    const newOrder: any = {
      id: `ord-wa-${Date.now()}`,
      orderNumber,
      customerId,
      customerLabName: customerName || "Registered Customer Laboratory",
      source: "WhatsApp — Manually Entered",
      status: "PROCESSING",
      paymentStatus: "PENDING",
      subtotal,
      gstAmount,
      grandTotal,
      items: orderItems,
      shippingAddress: shippingAddress || "Customer Registered Site",
      customerPhone: customerPhone || "+91-98000-00000",
      notes: notes || "Order manually keyed in from customer WhatsApp communication.",
      enteredByStaffId: req.user?.id || "u-office-01",
      enteredByStaffName: actingName,
      whatsappReferenceNumber: whatsappReferenceNumber || `WA-${Date.now().toString().slice(-6)}`,
      whatsappScreenshotUrl: whatsappScreenshotUrl || undefined,
      reminderCount: 0,
      nextReminderAt: new Date(Date.now() + 4 * 3600000).toISOString(),
      createdAt: nowIso,
      updatedAt: nowIso
    };

    customerOrdersDb.unshift(newOrder);

    // Initial status history entry
    orderStatusHistoryDb.unshift({
      id: `osh-${Date.now()}`,
      orderId: newOrder.id,
      fromStatus: "NONE",
      toStatus: "PROCESSING",
      changedBy: actingName,
      changedByRole: req.user?.roleType || "OFFICE_STAFF",
      comment: `Order manually created from customer WhatsApp communication by ${actingName}. Reference: ${newOrder.whatsappReferenceNumber}`,
      timestamp: nowIso
    });

    logAudit(req, "ORDER_CREATED_MANUAL_WHATSAPP", "ORDERS", "SUCCESS", {
      userId: req.user?.id,
      resourceId: newOrder.id,
      details: {
        orderId: newOrder.id,
        orderNumber: newOrder.orderNumber,
        customerId,
        grandTotal,
        enteredByStaffId: req.user?.id,
        enteredByStaffName: actingName,
        whatsappReferenceNumber: newOrder.whatsappReferenceNumber
      }
    });

    res.status(201).json({
      statusCode: 201,
      message: `Manual WhatsApp order #${newOrder.orderNumber} successfully booked for ${newOrder.customerLabName}.`,
      data: newOrder
    });
  });

  // 70c. Admin: Dispatch 4-Hour Pending Order Reminder (Scheduled intervals: 9 AM, 1 PM, 5 PM, 9 PM, 1 AM)
  app.post("/api/v1/admin/orders/:id/dispatch-reminder", authenticateJwt as any, requireRole(UserRoleType.SUPER_ADMIN, UserRoleType.OFFICE_ADMIN, UserRoleType.OFFICE_STAFF) as any, (req: AuthenticatedRequest, res) => {
    const { id } = req.params;
    const order = customerOrdersDb.find(o => o.id === id || o.orderNumber === id);
    if (!order) {
      return res.status(404).json({ statusCode: 404, message: "Order not found", error: "Not Found" });
    }

    if (order.status === "DELIVERED" || order.status === "CANCELLED") {
      return res.status(400).json({
        statusCode: 400,
        error: "Bad Request",
        message: `Order #${order.orderNumber} is already in terminal state '${order.status}'. Reminders cannot be dispatched.`
      });
    }

    const nowIso = new Date().toISOString();
    order.reminderCount = (order.reminderCount || 0) + 1;
    order.lastReminderAt = nowIso;
    order.nextReminderAt = new Date(Date.now() + 4 * 3600000).toISOString();
    order.updatedAt = nowIso;

    // Log notification alert
    logAudit(req, "PENDING_ORDER_REMINDER_DISPATCHED", "ORDERS", "SUCCESS", {
      userId: req.user?.id,
      resourceId: order.id,
      details: {
        orderId: order.id,
        orderNumber: order.orderNumber,
        customerId: order.customerId,
        reminderCount: order.reminderCount,
        recipientRoles: ["SUPER_ADMIN", "BACK_OFFICE"]
      }
    });

    res.json({
      statusCode: 200,
      message: `4-Hour pending reminder #${order.reminderCount} dispatched for Order #${order.orderNumber} to assigned Back Office staff and Super Admin.`,
      data: {
        orderId: order.id,
        orderNumber: order.orderNumber,
        reminderCount: order.reminderCount,
        lastReminderAt: order.lastReminderAt,
        nextReminderAt: order.nextReminderAt
      }
    });
  });

  // 70d. Admin: Sweep & Dispatch All 4-Hour Pending Order Reminders
  app.post("/api/v1/admin/orders/dispatch-all-pending-reminders", authenticateJwt as any, requireRole(UserRoleType.SUPER_ADMIN, UserRoleType.OFFICE_ADMIN) as any, (req: AuthenticatedRequest, res) => {
    const nowIso = new Date().toISOString();
    const pendingOrders = customerOrdersDb.filter(
      o => o.status === "NEW" || o.status === "PROCESSING" || o.status === "CONFIRMED" || o.status === "PACKED"
    );

    let remindersDispatched = 0;
    pendingOrders.forEach(o => {
      o.reminderCount = (o.reminderCount || 0) + 1;
      o.lastReminderAt = nowIso;
      o.nextReminderAt = new Date(Date.now() + 4 * 3600000).toISOString();
      (o as any).updatedAt = nowIso;
      remindersDispatched++;
    });

    res.json({
      statusCode: 200,
      message: `4-Hour pending reminder sweep completed. Dispatched alerts for ${remindersDispatched} active pending order(s) (Scheduled intervals: 9 AM, 1 PM, 5 PM, 9 PM, 1 AM).`,
      data: { remindersDispatched, totalPendingCount: pendingOrders.length }
    });
  });

