  // Enforce mandatory JWT authentication across all service endpoints
  app.use("/api/v1/service", authenticateJwt as any);

  // Helper: Server-side Ticket-Level Authorization Guard
  function authorizeTicketAccess(
    reqUser: { id: string; roleType: UserRoleType; email: string; labId?: string } | undefined,
    ticket: ServiceTicketEntity
  ): { authorized: boolean; statusCode?: number; error?: string; message?: string } {
    if (!reqUser) {
      return { authorized: false, statusCode: 401, error: "Unauthorized", message: "Authentication required" };
    }

    // Super Admin, Office Admin, Service Manager have full global clearance
    if ([UserRoleType.SUPER_ADMIN, UserRoleType.OFFICE_ADMIN, UserRoleType.SERVICE_MANAGER].includes(reqUser.roleType)) {
      return { authorized: true };
    }

    // Service Engineer MUST ONLY access their assigned tickets
    if (reqUser.roleType === UserRoleType.SERVICE_ENGINEER) {
      if (ticket.assignedEngineerId === reqUser.id) {
        return { authorized: true };
      }
      return {
        authorized: false,
        statusCode: 403,
        error: "ENGINEER_UNAUTHORIZED",
        message: "Access Denied: Service engineers are restricted to viewing and mutating their explicitly assigned service tickets."
      };
    }

    // Customer can only view their own lab's tickets
    if (reqUser.roleType === UserRoleType.CUSTOMER) {
      const userLabId = reqUser.labId || reqUser.id;
      if (ticket.customerId === reqUser.id || ticket.customerId === userLabId || (ticket as any).labId === userLabId) {
        return { authorized: true };
      }
      return {
        authorized: false,
        statusCode: 403,
        error: "CUSTOMER_UNAUTHORIZED",
        message: "Access Denied: Customers may only view service tickets raised for their own registered laboratory."
      };
    }

    // Office Staff / Sales Person: read-only if related
    if ([UserRoleType.OFFICE_STAFF, UserRoleType.SALES_PERSON].includes(reqUser.roleType)) {
      return { authorized: true };
    }

    return {
      authorized: false,
      statusCode: 403,
      error: "FORBIDDEN",
      message: "Insufficient permissions for service ticket access."
    };
  }

  // Helper: SLA Target Hours by Priority based on configured SLA rules
  function getSlaHoursForPriority(priority: string): number {
    switch (priority) {
      case "CRITICAL": return serviceSlaConfigDb.criticalResponseHours;
      case "HIGH": return serviceSlaConfigDb.highResponseHours;
      case "MEDIUM": return serviceSlaConfigDb.mediumResponseHours;
      case "LOW": return serviceSlaConfigDb.lowResponseHours;
      default: return serviceSlaConfigDb.mediumResponseHours;
    }
  }

