  // 74. Service: Get Customer Installed Equipment List
  const getEquipmentHandler = (req: any, res: any) => {
    const authUser = req.user!;
    const { customerId, status, search, warrantyStatus } = req.query;
    let list = [...customerEquipmentDb];

    if (authUser.roleType === UserRoleType.CUSTOMER) {
      const userLabId = authUser.labId || authUser.id;
      if (customerId && customerId !== "ALL" && customerId !== authUser.id && customerId !== userLabId) {
        return res.status(403).json({
          statusCode: 403,
          error: "CUSTOMER_ISOLATION_VIOLATION",
          message: "Access Denied: You cannot view equipment for another customer account."
        });
      }
      list = list.filter(e => e.customerId === authUser.id || e.customerId === userLabId);
    } else if (customerId && customerId !== "ALL") {
      list = list.filter(e => e.customerId === customerId);
    }
    if (status && status !== "ALL") {
      list = list.filter(e => e.status === status);
    }
    if (warrantyStatus && warrantyStatus !== "ALL") {
      list = list.filter(e => e.warrantyStatus === warrantyStatus);
    }
    if (search) {
      const q = String(search).toLowerCase();
      list = list.filter(e =>
        e.equipmentName.toLowerCase().includes(q) ||
        e.serialNumber.toLowerCase().includes(q) ||
        e.modelNumber.toLowerCase().includes(q) ||
        e.customerLabName.toLowerCase().includes(q)
      );
    }

    // Attach open tickets count
    const enriched = list.map(eq => {
      const tickets = serviceTicketsDb.filter(t => t.equipmentId === eq.id);
      const open = tickets.filter(t => !["CLOSED", "CANCELLED"].includes(t.status));
      return {
        ...eq,
        totalServiceTicketsCount: tickets.length,
        openTicketsCount: open.length
      };
    });

    res.json({
      statusCode: 200,
      data: enriched,
      total: enriched.length
    });
  };
  app.get("/api/v1/service/equipment", getEquipmentHandler);
  app.get("/api/v1/service/equipments", getEquipmentHandler);

  // 75. Service: Get Single Equipment Details
