  /**
   * Safe transactional service ticket persistence helper.
   * Ensures that in PostgreSQL mode, writes are transactional and atomic.
   * In case of database failure or disconnect, any in-memory ticket/equipment changes
   * are completely rolled back to pre-mutation snapshots to avoid misleading memory leaks.
   * In LOCAL_JSON mode, persists durable state to JSON store.
   */
  async function persistServiceTicketMutation(options: {
    ticket: ServiceTicketEntity;
    ticketSnapshot?: string;
    equipment?: CustomerEquipmentEntity;
    equipmentSnapshot?: string;
    equipmentUpdateData?: any;
    res: any;
  }): Promise<boolean> {
    const mode = getPersistenceMode();

    if (mode === PersistenceMode.POSTGRES_DISCONNECTED) {
      if (options.ticketSnapshot) {
        const restored = JSON.parse(options.ticketSnapshot);
        Object.assign(options.ticket, restored);
      }
      if (options.equipment && options.equipmentSnapshot) {
        const restoredEq = JSON.parse(options.equipmentSnapshot);
        Object.assign(options.equipment, restoredEq);
      }
      options.res.status(503).json({
        statusCode: 503,
        error: "DATABASE_UNAVAILABLE",
        message: "PostgreSQL database is currently disconnected. Service ticket mutation cannot be completed."
      });
      return false;
    }

    if (mode === PersistenceMode.POSTGRES_AUTHORITATIVE) {
      try {
        if (options.equipment && options.equipmentUpdateData) {
          await serviceTicketRepository.saveTicketWithEquipmentTx(options.ticket, {
            equipmentId: options.equipment.id,
            data: options.equipmentUpdateData
          });
        } else {
          await serviceTicketRepository.upsert(options.ticket);
        }
      } catch (err: any) {
        if (options.ticketSnapshot) {
          const restored = JSON.parse(options.ticketSnapshot);
          Object.assign(options.ticket, restored);
        }
        if (options.equipment && options.equipmentSnapshot) {
          const restoredEq = JSON.parse(options.equipmentSnapshot);
          Object.assign(options.equipment, restoredEq);
        }
        console.error("[Service Ticket Persistence Error]", err?.message || err);
        options.res.status(500).json({
          statusCode: 500,
          error: "DATABASE_WRITE_ERROR",
          message: `Failed to persist service ticket mutation to PostgreSQL: ${err.message}`
        });
        return false;
      }
    } else {
      persistAllBusinessData();
    }

    return true;
  }

  // 77. Service: Create Ticket / Lodge Complaint (Customer or Office Admin)
  app.post("/api/v1/service/tickets", async (req, res) => {
    const {
      customerId,
      category = "EQUIPMENT_BREAKDOWN",
      equipmentId,
      priority = "MEDIUM",
      title,
      description,
      errorCode,
      customerContactPerson,
      customerPhone,
      customerAddress,
      assignedEngineerId
    } = req.body;

    const authUser = (req as any).user || getRequestAuthUser(req);
    if (!authUser) {
      return res.status(401).json({ statusCode: 401, error: "UNAUTHORIZED", message: "Authentication required to lodge service ticket." });
    }

    const effectiveLabId = authUser.labId || authUser.id;
    const targetCustomerId = authUser.roleType === UserRoleType.CUSTOMER ? authUser.id : (customerId || authUser.id);

    if (authUser.roleType === UserRoleType.CUSTOMER) {
      if (customerId && customerId !== authUser.id && customerId !== effectiveLabId) {
        return res.status(403).json({
          statusCode: 403,
          error: "CUSTOMER_ISOLATION_VIOLATION",
          message: "Access Denied: You cannot lodge service tickets on behalf of another customer account."
        });
      }
    }

    if (!targetCustomerId || !title || !description) {
      return res.status(400).json({
        statusCode: 400,
        message: "customerId, title, and description are mandatory to lodge a ticket",
        error: "Bad Request"
      });
    }

    const cust = usersDb.find(u => u.id === targetCustomerId || u.labId === targetCustomerId);
    const eq = equipmentId ? customerEquipmentDb.find(e => e.id === equipmentId) : undefined;
    const slaHours = getSlaHoursForPriority(priority);
    const now = new Date();
    const slaTargetTimestamp = new Date(now.getTime() + slaHours * 3600000).toISOString();
    const ticketSeq = serviceTicketsDb.length + 101;
    const ticketNumber = `TCK-2026-${String(ticketSeq).padStart(4, "0")}`;

    let assignedEng: UserEntity | undefined;
    if (assignedEngineerId) {
      assignedEng = usersDb.find(u => u.id === assignedEngineerId && u.roleType === UserRoleType.SERVICE_ENGINEER);
    }

    const initialStatus = assignedEng ? "ASSIGNED" : "NEW";

    const newTicket: ServiceTicketEntity = {
      id: `tck-${Date.now()}`,
      ticketNumber,
      customerId: targetCustomerId,
      customerLabName: cust?.customerProfile?.labName || eq?.customerLabName || "Diagnostic Laboratory",
      customerContactPerson: customerContactPerson || cust?.firstName + " " + cust?.lastName || "Lab Incharge",
      customerPhone: customerPhone || cust?.phoneNumber || "+91-9876543210",
      customerAddress: customerAddress || "Central Laboratory Diagnostics Wing",
      category,
      equipmentId: eq?.id,
      equipmentName: eq?.equipmentName,
      equipmentModel: eq?.modelNumber,
      equipmentSerial: eq?.serialNumber,
      priority,
      title,
      description,
      errorCode,
      status: initialStatus as any,
      assignedEngineerId: assignedEng?.id,
      assignedEngineerName: assignedEng ? `${assignedEng.firstName} ${assignedEng.lastName}` : undefined,
      assignedEngineerPhone: assignedEng?.phoneNumber,
      assignedEngineerEmail: assignedEng?.email,
      assignedAt: assignedEng ? now.toISOString() : undefined,
      slaTargetHours: slaHours,
      slaTargetTimestamp,
      slaStatus: "ON_TRACK",
      notes: [
        {
          id: `not-${Date.now()}`,
          ticketId: `tck-${Date.now()}`,
          authorId: cust?.id || "SYSTEM",
          authorName: cust ? `${cust.firstName} ${cust.lastName}` : "Customer Lab",
          authorRole: cust?.roleType || "CUSTOMER",
          noteType: "CUSTOMER_VISIBLE",
          content: `Complaint lodged: ${title}. ${description}${errorCode ? ` (Reported Error Code: ${errorCode})` : ""}`,
          createdAt: now.toISOString()
        }
      ],
      attachments: [],
      partsUsed: [],
      customerCommunication: [
        {
          id: `msg-${Date.now()}`,
          ticketId: `tck-${Date.now()}`,
          senderId: cust?.id || "SYSTEM",
          senderName: cust ? `${cust.firstName} ${cust.lastName}` : "Lab Director",
          senderRole: "CUSTOMER",
          message: `Ticket #${ticketNumber} created. Priority: ${priority}. Required SLA: ${slaHours}h.`,
          isCustomerVisible: true,
          timestamp: now.toISOString()
        }
      ],
      disputeHistory: [],
      createdAt: now.toISOString(),
      updatedAt: now.toISOString()
    };

    const prevEqStatus = eq?.status;
    const eqSnapshot = eq ? JSON.stringify(eq) : undefined;
    if (eq && category === "EQUIPMENT_BREAKDOWN") {
      eq.status = priority === "CRITICAL" ? "DOWN" : "DEGRADED";
    }

    const mode = getPersistenceMode();
    if (mode === PersistenceMode.POSTGRES_DISCONNECTED) {
      if (eq && eqSnapshot) {
        Object.assign(eq, JSON.parse(eqSnapshot));
      }
      return res.status(503).json({
        statusCode: 503,
        error: "DATABASE_UNAVAILABLE",
        message: "PostgreSQL database is currently disconnected. Ticket creation cannot be completed."
      });
    }

    if (mode === PersistenceMode.POSTGRES_AUTHORITATIVE) {
      try {
        if (eq && eq.status !== prevEqStatus) {
          await serviceTicketRepository.saveTicketWithEquipmentTx(newTicket, {
            equipmentId: eq.id,
            data: { status: eq.status }
          });
        } else {
          await serviceTicketRepository.upsert(newTicket);
        }
      } catch (err: any) {
        if (eq && eqSnapshot) {
          Object.assign(eq, JSON.parse(eqSnapshot));
        }
        return res.status(500).json({
          statusCode: 500,
          error: "DATABASE_WRITE_ERROR",
          message: `Failed to persist service ticket to PostgreSQL: ${err.message}`
        });
      }
    } else {
      persistAllBusinessData();
    }

    serviceTicketsDb.unshift(newTicket);

    // Push notification to Customer
    customerNotificationsDb.unshift({
      id: `notif-${Date.now()}`,
      title: `Service Ticket Logged #${newTicket.ticketNumber}`,
      message: `Your complaint for ${newTicket.equipmentName || newTicket.title} has been logged. SLA Target: ${slaHours}h.`,
      type: "ORDER_STATUS",
      isRead: false,
      timestamp: now.toISOString()
    });

    logAudit(req, "SERVICE_TICKET_CREATED", "SERVICE", "SUCCESS", {
      userId: customerId,
      resourceType: "SERVICE_TICKET",
      resourceId: newTicket.id,
      details: { ticketNumber: newTicket.ticketNumber, priority, category, equipmentId }
    });

    res.status(201).json({
      statusCode: 201,
      message: `Service Ticket #${newTicket.ticketNumber} created successfully`,
      data: newTicket
    });
  });

  // 78. Service: Get Tickets List (With Strict Ticket-Level Authorization & Filters)
  app.get("/api/v1/service/tickets", async (req: AuthenticatedRequest, res) => {
    const {
      status,
      priority,
      category,
      customerId,
      assignedEngineerId,
      slaStatus,
      search,
      page = 1,
      limit = 50
    } = req.query;

    const mode = getPersistenceMode();
    if (mode === PersistenceMode.POSTGRES_DISCONNECTED) {
      return res.status(503).json({
        statusCode: 503,
        error: "DATABASE_UNAVAILABLE",
        message: "PostgreSQL database is currently disconnected. Cannot serve authoritative service tickets."
      });
    }

    let list: any[];
    if (mode === PersistenceMode.POSTGRES_AUTHORITATIVE) {
      try {
        list = await serviceTicketRepository.findAll();
      } catch (err: any) {
        console.error("[Service Tickets Read Error]", err?.message || err);
        return res.status(503).json({
          statusCode: 503,
          error: "DATABASE_READ_ERROR",
          message: "Failed to read authoritative service tickets from database."
        });
      }
    } else {
      list = [...serviceTicketsDb];
    }

    const authUser = req.user || getRequestAuthUser(req);
    // SERVER-SIDE TICKET-LEVEL AUTHORIZATION FILTER
    // If request has authenticated engineer token, strictly filter only assigned tickets
    if (authUser && authUser.roleType === UserRoleType.SERVICE_ENGINEER) {
      list = list.filter(t => t.assignedEngineerId === authUser.id);
    } else if (authUser && authUser.roleType === UserRoleType.CUSTOMER) {
      const effectiveLabId = (authUser as any).labId || authUser.id;
      if (customerId && customerId !== "ALL" && customerId !== authUser.id && customerId !== effectiveLabId) {
        return res.status(403).json({
          statusCode: 403,
          error: "CUSTOMER_ISOLATION_VIOLATION",
          message: "Access Denied: You cannot view service tickets for another customer account."
        });
      }
      list = list.filter(t => t.customerId === authUser.id || t.customerId === effectiveLabId || (t as any).labId === effectiveLabId);
    }

    // Query Filters
    if (status && status !== "ALL") {
      list = list.filter(t => t.status === status);
    }
    if (priority && priority !== "ALL") {
      list = list.filter(t => t.priority === priority);
    }
    if (category && category !== "ALL") {
      list = list.filter(t => t.category === category);
    }
    if (customerId && customerId !== "ALL") {
      list = list.filter(t => t.customerId === customerId);
    }
    if (assignedEngineerId && assignedEngineerId !== "ALL") {
      list = list.filter(t => t.assignedEngineerId === assignedEngineerId);
    }
    if (slaStatus && slaStatus !== "ALL") {
      list = list.filter(t => t.slaStatus === slaStatus);
    }

    if (search) {
      const q = String(search).toLowerCase();
      list = list.filter(t =>
        (t.ticketNumber && t.ticketNumber.toLowerCase().includes(q)) ||
        (t.title && t.title.toLowerCase().includes(q)) ||
        (t.customerLabName && t.customerLabName.toLowerCase().includes(q)) ||
        (t.equipmentName && t.equipmentName.toLowerCase().includes(q)) ||
        (t.equipmentSerial && t.equipmentSerial.toLowerCase().includes(q)) ||
        (t.assignedEngineerName && t.assignedEngineerName.toLowerCase().includes(q))
      );
    }

    // Check SLA status dynamically (construct copy so we do not mutate in-memory cache directly)
    const now = Date.now();
    const evaluatedList = list.map(orig => {
      const t = { ...orig };
      if (!["CLOSED", "RESOLVED", "CANCELLED"].includes(t.status)) {
        const slaTime = new Date(t.slaTargetTimestamp).getTime();
        const diffHours = (slaTime - now) / 3600000;
        if (diffHours < 0) {
          t.slaStatus = "BREACHED";
        } else if (diffHours <= 2) {
          t.slaStatus = "WARNING";
        } else {
          t.slaStatus = "ON_TRACK";
        }
      } else {
        t.slaStatus = "MET";
      }
      return t;
    });

    evaluatedList.sort((a, b) => new Date(b.createdAt).getTime() - new Date(a.createdAt).getTime());

    res.json({
      statusCode: 200,
      data: evaluatedList,
      total: evaluatedList.length,
      page: Number(page),
      limit: Number(limit)
    });
  });

  // 79. Service: Get Single Ticket by ID (With Server-Side Ticket-Level Auth Guard)
  app.get("/api/v1/service/tickets/:id", async (req: AuthenticatedRequest, res) => {
    const { id } = req.params;
    const mode = getPersistenceMode();

    if (mode === PersistenceMode.POSTGRES_DISCONNECTED) {
      return res.status(503).json({
        statusCode: 503,
        error: "DATABASE_UNAVAILABLE",
        message: "PostgreSQL database is currently disconnected. Cannot serve authoritative service ticket."
      });
    }

    let ticket: any;
    if (mode === PersistenceMode.POSTGRES_AUTHORITATIVE) {
      try {
        ticket = await serviceTicketRepository.findById(id);
        if (!ticket) {
          return res.status(404).json({ statusCode: 404, message: "Ticket not found", error: "Not Found" });
        }
      } catch (err: any) {
        console.error("[Service Ticket Read Error]", err?.message || err);
        return res.status(503).json({
          statusCode: 503,
          error: "DATABASE_READ_ERROR",
          message: "Failed to read authoritative service ticket from database."
        });
      }
    } else {
      ticket = serviceTicketsDb.find(t => t.id === id || t.ticketNumber === id);
      if (!ticket) {
        return res.status(404).json({ statusCode: 404, message: "Ticket not found", error: "Not Found" });
      }
    }

    // Check ticket-level authorization
    if (req.user) {
      const authCheck = authorizeTicketAccess(req.user, ticket);
      if (!authCheck.authorized) {
        return res.status(authCheck.statusCode || 403).json({
          statusCode: authCheck.statusCode || 403,
          error: authCheck.error,
          message: authCheck.message
        });
      }
    }

    res.json({
      statusCode: 200,
      data: ticket
    });
  });

  // 80. Service: Assign / Reassign Ticket (Service Manager / Office Admin)
  const assignHandler = async (req: AuthenticatedRequest, res: any) => {
    const authUser = req.user!;
    if (authUser.roleType === UserRoleType.CUSTOMER || authUser.roleType === UserRoleType.SERVICE_ENGINEER) {
      return res.status(403).json({
        statusCode: 403,
        error: "FORBIDDEN",
        message: "Access Denied: Only Service Managers, Super Admins, and Office Admins can assign service tickets."
      });
    }

    const { id } = req.params;
    const { engineerId, assignedEngineerId, priority, slaTargetHours, comment, assignedBy = "Service Dispatch Lead" } = req.body;

    const ticket = serviceTicketsDb.find(t => t.id === id || t.ticketNumber === id);
    if (!ticket) {
      return res.status(404).json({ statusCode: 404, message: "Ticket not found", error: "Not Found" });
    }

    const targetEngId = engineerId || assignedEngineerId || "u-eng-01";
    let eng = usersDb.find(u => u.id === targetEngId);
    if (!eng || eng.roleType !== UserRoleType.SERVICE_ENGINEER) {
      eng = usersDb.find(u => u.roleType === UserRoleType.SERVICE_ENGINEER);
    }
    if (!eng) {
      return res.status(400).json({
        statusCode: 400,
        message: "Invalid engineerId. Target user must have SERVICE_ENGINEER role",
        error: "Bad Request"
      });
    }

    const ticketSnapshot = JSON.stringify(ticket);
    const previousStatus = ticket.status;
    ticket.assignedEngineerId = eng.id;
    ticket.assignedEngineerName = `${eng.firstName} ${eng.lastName}`;
    ticket.assignedEngineerPhone = eng.phoneNumber;
    ticket.assignedEngineerEmail = eng.email;
    ticket.assignedAt = new Date().toISOString();
    ticket.status = "ASSIGNED";
    ticket.updatedAt = new Date().toISOString();

    if (priority) {
      ticket.priority = priority;
    }
    if (slaTargetHours) {
      ticket.slaTargetHours = Number(slaTargetHours);
      ticket.slaTargetTimestamp = new Date(Date.now() + Number(slaTargetHours) * 3600000).toISOString();
    }

    // Append internal note
    ticket.notes.unshift({
      id: `not-${Date.now()}`,
      ticketId: ticket.id,
      authorId: req.user?.id || "u-smgr-01",
      authorName: assignedBy,
      authorRole: "SERVICE_MANAGER",
      noteType: "INTERNAL",
      content: `Ticket assigned to Biomedical Engineer ${eng.firstName} ${eng.lastName} (${eng.employeeProfile?.employeeCode || 'ENG'}). ${comment || ''}`,
      createdAt: new Date().toISOString()
    });

    // Communication timeline
    ticket.customerCommunication.push({
      id: `msg-${Date.now()}`,
      ticketId: ticket.id,
      senderId: req.user?.id || "u-smgr-01",
      senderName: "Service Desk Dispatch",
      senderRole: "SERVICE_MANAGER",
      message: `Assigned to Lead Biomedical Service Engineer ${eng.firstName} ${eng.lastName} (${eng.phoneNumber}).`,
      isCustomerVisible: true,
      timestamp: new Date().toISOString()
    });

    const persisted = await persistServiceTicketMutation({ ticket, ticketSnapshot, res });
    if (!persisted) return;

    logAudit(req, "TICKET_ASSIGNED", "SERVICE", "SUCCESS", {
      resourceType: "SERVICE_TICKET",
      resourceId: ticket.id,
      details: { ticketNumber: ticket.ticketNumber, engineerId: eng.id, engineerName: ticket.assignedEngineerName }
    });

    res.json({
      statusCode: 200,
      message: `Ticket #${ticket.ticketNumber} assigned to ${eng.firstName} ${eng.lastName}`,
      data: ticket
    });
  };
  app.patch("/api/v1/service/tickets/:id/assign", assignHandler);
  app.post("/api/v1/service/tickets/:id/assign", assignHandler);

