  // 88. Service: Add Parts Used (With Automatic Warranty vs Billable Calculation)
  app.post("/api/v1/service/tickets/:id/parts", async (req: AuthenticatedRequest, res) => {
    const { id } = req.params;
    const { partId, partNumber, partName, quantity = 1, unitCost, isWarrantyCovered, invoiceNumber } = req.body;

    const ticket = serviceTicketsDb.find(t => t.id === id || t.ticketNumber === id);
    if (!ticket) {
      return res.status(404).json({ statusCode: 404, message: "Ticket not found", error: "Not Found" });
    }

    if (req.user) {
      const authCheck = authorizeTicketAccess(req.user, ticket);
      if (!authCheck.authorized) {
        return res.status(authCheck.statusCode || 403).json({ statusCode: authCheck.statusCode || 403, error: authCheck.error, message: authCheck.message });
      }
    }

    // Check catalog or equipment warranty status
    const catalogItem = serviceSparePartsDb.find(p => p.id === partId || p.partNumber === partNumber);
    const eq = ticket.equipmentId ? customerEquipmentDb.find(e => e.id === ticket.equipmentId) : undefined;
    
    // Auto-determine warranty status if not explicitly overridden:
    // If equipment is UNDER_WARRANTY or ACTIVE_CMC, parts are warranty covered ($0 billable)
    let isCovered = isWarrantyCovered !== undefined ? Boolean(isWarrantyCovered) : (eq?.warrantyStatus === "UNDER_WARRANTY" || eq?.warrantyStatus === "ACTIVE_CMC");
    const cost = unitCost || catalogItem?.unitCost || 5000.00;
    const qty = Math.max(1, Number(quantity) || 1);
    const totalCost = cost * qty;
    const isBillable = !isCovered;

    const newPart: ServicePartItem = {
      id: `prt-used-${Date.now()}`,
      ticketId: ticket.id,
      partId: catalogItem?.id || partId,
      partNumber: partNumber || catalogItem?.partNumber || "SP-GEN-01",
      partName: partName || catalogItem?.partName || "Replacement Biomedical Spare Part",
      quantity: qty,
      unitCost: cost,
      totalCost,
      isWarrantyCovered: isCovered,
      isBillable,
      invoiceNumber: isBillable ? (invoiceNumber || `INV-SP-${Date.now().toString().slice(-6)}`) : undefined,
      addedBy: ticket.assignedEngineerName || "Service Engineer",
      addedAt: new Date().toISOString()
    };

    const ticketSnapshot = JSON.stringify(ticket);
    const catalogStockSnapshot = catalogItem?.stockQuantity;

    ticket.partsUsed.push(newPart);
    ticket.updatedAt = new Date().toISOString();

    // Deduct catalog stock if found
    if (catalogItem && catalogItem.stockQuantity >= qty) {
      catalogItem.stockQuantity -= qty;
    }

    ticket.notes.unshift({
      id: `not-${Date.now()}`,
      ticketId: ticket.id,
      authorId: req.user?.id || "u-eng-01",
      authorName: ticket.assignedEngineerName || "Service Engineer",
      authorRole: "SERVICE_ENGINEER",
      noteType: "INTERNAL",
      content: `Installed Part: ${newPart.partName} (${newPart.partNumber}) x ${qty}. Total: ₹${totalCost.toLocaleString('en-IN')}. Status: ${isCovered ? 'Covered Under AMC/Warranty (₹0 to customer)' : 'Billable to Lab'}.`,
      createdAt: new Date().toISOString()
    });

    const persisted = await persistServiceTicketMutation({ ticket, ticketSnapshot, res });
    if (!persisted) {
      if (catalogItem && catalogStockSnapshot !== undefined) {
        catalogItem.stockQuantity = catalogStockSnapshot;
      }
      return;
    }

    logAudit(req, "SPARE_PART_INSTALLED", "SERVICE", "SUCCESS", {
      resourceType: "SERVICE_TICKET",
      resourceId: ticket.id,
      details: { ticketNumber: ticket.ticketNumber, part: newPart }
    });

    res.status(201).json({
      statusCode: 201,
      message: `Part ${newPart.partName} added to ticket`,
      data: ticket
    });
  });

