  app.post("/api/v1/service/tickets/:id/resolve", async (req: AuthenticatedRequest, res) => {
    const { id } = req.params;
    const {
      rootCause = "Halogen lamp filament degradation causing baseline photometric optical drift > 0.08 Abs.",
      actionTaken = "Replaced 12V 20W Quartz lamp assembly, cleaned flowcell optical lenses, and performed 8-filter wavelength calibration verification.",
      testRunResult = "Passed 5x replicate clinical albumin test run. CV: 1.1% (within NABL allowable limit of < 3.0%).",
      reagentLotTested = "Roche Albumin Gen.2 Lot #669101",
      calibrationPassed = true,
      qcValueObserved = "Level 1: 3.82 g/dL (Target: 3.80 +/- 0.15) | Level 2: 2.45 g/dL (Target: 2.40 +/- 0.12)"
    } = req.body;

    const ticket = serviceTicketsDb.find(t => t.id === id || t.ticketNumber === id);
    if (!ticket) {
      return res.status(404).json({ statusCode: 404, message: "Ticket not found", error: "Not Found" });
    }

    if (req.user) {
      const authCheck = authorizeTicketAccess(req.user, ticket);
      if (!authCheck.authorized) {
        return res.status(authCheck.statusCode || 403).json({ statusCode: authCheck.statusCode || 403, error: authCheck.error, message: authCheck.message });
      }
    }

    const ticketSnapshot = JSON.stringify(ticket);
    const eq = ticket.equipmentId ? customerEquipmentDb.find(e => e.id === ticket.equipmentId) : undefined;
    const eqSnapshot = eq ? JSON.stringify(eq) : undefined;

    const now = new Date().toISOString();
    ticket.status = "CUSTOMER_FEEDBACK_PENDING"; // Transitions to feedback pending for customer rating
    ticket.resolution = {
      rootCause,
      actionTaken,
      testRunResult,
      reagentLotTested,
      calibrationPassed: Boolean(calibrationPassed),
      qcValueObserved,
      resolvedAt: now,
      resolvedBy: ticket.assignedEngineerId || "u-eng-01",
      resolvedByName: ticket.assignedEngineerName || "Lead Biomedical Engineer"
    };
    ticket.updatedAt = now;

    // Reset equipment status back to OPERATIONAL
    if (eq) {
      eq.status = "OPERATIONAL";
      eq.lastServiceDate = now.split("T")[0];
    }

    ticket.notes.unshift({
      id: `not-${Date.now()}`,
      ticketId: ticket.id,
      authorId: ticket.assignedEngineerId || "u-eng-01",
      authorName: ticket.assignedEngineerName || "Service Engineer",
      authorRole: "SERVICE_ENGINEER",
      noteType: "CUSTOMER_VISIBLE",
      content: `RESOLUTION SUBMITTED: ${actionTaken}. Clinical test run: ${testRunResult}. Calibration: PASSED.`,
      createdAt: now
    });

    ticket.customerCommunication.push({
      id: `msg-${Date.now()}`,
      ticketId: ticket.id,
      senderId: ticket.assignedEngineerId || "u-eng-01",
      senderName: ticket.assignedEngineerName || "Service Engineer",
      senderRole: "SERVICE_ENGINEER",
      message: `Repair and QC calibration completed successfully. Equipment restored to full operational status. Please submit your digital sign-off and feedback rating.`,
      isCustomerVisible: true,
      timestamp: now
    });

    // Send push notification to Customer for feedback
    customerNotificationsDb.unshift({
      id: `notif-${Date.now()}`,
      title: `Service Resolved - Action Required: Feedback #${ticket.ticketNumber}`,
      message: `Engineer ${ticket.assignedEngineerName} resolved issue for ${ticket.equipmentName || ticket.title}. Please provide satisfaction rating and digital sign-off.`,
      type: "ORDER_STATUS",
      isRead: false,
      timestamp: now
    });

    const persisted = await persistServiceTicketMutation({
      ticket,
      ticketSnapshot,
      equipment: eq,
      equipmentSnapshot: eqSnapshot,
      equipmentUpdateData: eq ? { status: eq.status, lastServiceDate: eq.lastServiceDate } : undefined,
      res
    });
    if (!persisted) return;

    logAudit(req, "TICKET_RESOLVED", "SERVICE", "SUCCESS", {
      resourceType: "SERVICE_TICKET",
      resourceId: ticket.id,
      details: { ticketNumber: ticket.ticketNumber, resolution: ticket.resolution }
    });

    res.json({
      statusCode: 200,
      message: `Service Ticket #${ticket.ticketNumber} marked RESOLVED. Awaiting customer feedback sign-off.`,
      data: ticket
    });
  });

