  // 96. Service: Flexible Status Transition (Waiting for parts, waiting for customer, etc.)
  const statusHandler = async (req: AuthenticatedRequest, res: any) => {
    const { id } = req.params;
    const { status, comment = "" } = req.body;

    if (!req.user) {
      return res.status(401).json({ statusCode: 401, error: "Unauthorized", message: "Authentication required" });
    }

    if (!status || typeof status !== "string") {
      return res.status(400).json({ statusCode: 400, message: "Valid status string is required.", error: "Bad Request" });
    }

    const ticket = serviceTicketsDb.find(t => t.id === id || t.ticketNumber === id);
    if (!ticket) {
      return res.status(404).json({ statusCode: 404, message: "Ticket not found", error: "Not Found" });
    }

    const authCheck =  authorizeTicketAccess(req.user, ticket);
    if (!authCheck.authorized) {
      return res.status(authCheck.statusCode || 403).json({
        statusCode: authCheck.statusCode || 403,
        error: authCheck.error || "Forbidden",
        message: authCheck.message || "Access denied"
      });
    }

    const prev = ticket.status;
    const ALLOWED_TICKET_TRANSITIONS: Record<string, string[]> = {
      NEW: ["ASSIGNED", "SCHEDULED", "IN_PROGRESS", "WAITING_FOR_PARTS", "WAITING_FOR_CUSTOMER", "CANCELLED"],
      ASSIGNED: ["SCHEDULED", "ON_THE_WAY", "CHECKED_IN", "IN_PROGRESS", "WAITING_FOR_PARTS", "WAITING_FOR_CUSTOMER", "CANCELLED"],
      ACKNOWLEDGED: ["SCHEDULED", "ON_THE_WAY", "CHECKED_IN", "IN_PROGRESS", "WAITING_FOR_PARTS", "WAITING_FOR_CUSTOMER", "CANCELLED"],
      SCHEDULED: ["ON_THE_WAY", "CHECKED_IN", "IN_PROGRESS", "WAITING_FOR_PARTS", "WAITING_FOR_CUSTOMER", "CANCELLED"],
      ON_THE_WAY: ["CHECKED_IN", "IN_PROGRESS", "WAITING_FOR_PARTS", "WAITING_FOR_CUSTOMER", "CANCELLED"],
      CHECKED_IN: ["IN_PROGRESS", "WAITING_FOR_PARTS", "WAITING_FOR_CUSTOMER", "RESOLVED", "CANCELLED"],
      IN_PROGRESS: ["WAITING_FOR_PARTS", "WAITING_FOR_CUSTOMER", "CUSTOMER_FEEDBACK_PENDING", "BACK_OFFICE_REVIEW", "RESOLVED", "CANCELLED"],
      WAITING_FOR_PARTS: ["IN_PROGRESS", "SCHEDULED", "WAITING_FOR_CUSTOMER", "RESOLVED", "CANCELLED"],
      WAITING_FOR_CUSTOMER: ["IN_PROGRESS", "SCHEDULED", "WAITING_FOR_PARTS", "RESOLVED", "CANCELLED"],
      CUSTOMER_FEEDBACK_PENDING: ["RESOLVED", "CLOSED", "CUSTOMER_DISPUTED_RESOLUTION", "BACK_OFFICE_REVIEW", "REOPENED"],
      BACK_OFFICE_REVIEW: ["RESOLVED", "CLOSED", "REOPENED", "IN_PROGRESS"],
      CUSTOMER_DISPUTED_RESOLUTION: ["IN_PROGRESS", "ASSIGNED", "REOPENED", "RESOLVED", "BACK_OFFICE_REVIEW"],
      RESOLVED: ["CLOSED", "REOPENED", "CUSTOMER_FEEDBACK_PENDING", "CUSTOMER_DISPUTED_RESOLUTION", "BACK_OFFICE_REVIEW"],
      REOPENED: ["ASSIGNED", "IN_PROGRESS", "SCHEDULED", "WAITING_FOR_PARTS", "WAITING_FOR_CUSTOMER"],
      CLOSED: ["REOPENED"],
      CANCELLED: []
    };

    const allowedNext = ALLOWED_TICKET_TRANSITIONS[prev] || [];
    if (!allowedNext.includes(status) && status !== prev) {
      return res.status(400).json({
        statusCode: 400,
        error: "INVALID_STATUS_TRANSITION",
        message: `Cannot transition service ticket #${ticket.ticketNumber} from '${prev}' to '${status}'. Allowed transitions: [${allowedNext.join(", ") || "None (Terminal State)"}].`
      });
    }

    const ticketSnapshot = JSON.stringify(ticket);
    ticket.status = status as any;
    ticket.updatedAt = new Date().toISOString();

    ticket.notes.unshift({
      id: `not-${Date.now()}`,
      ticketId: ticket.id,
      authorId: req.user.id,
      authorName: req.user.email || ticket.assignedEngineerName || "Service Desk",
      authorRole: req.user.roleType || "SERVICE_ENGINEER",
      noteType: "INTERNAL",
      content: `Status transition: ${prev} -> ${status}. ${comment}`.trim(),
      createdAt: new Date().toISOString()
    });

    const persisted = await persistServiceTicketMutation({ ticket, ticketSnapshot, res });
    if (!persisted) return;

    res.json({
      statusCode: 200,
      message: `Ticket status updated to ${status}`,
      data: ticket
    });
  };
  app.patch("/api/v1/service/tickets/:id/status", authenticateJwt as any, requireRole(UserRoleType.SUPER_ADMIN, UserRoleType.OFFICE_ADMIN, UserRoleType.SERVICE_MANAGER, UserRoleType.SERVICE_ENGINEER) as any, statusHandler);
  app.post("/api/v1/service/tickets/:id/status", authenticateJwt as any, requireRole(UserRoleType.SUPER_ADMIN, UserRoleType.OFFICE_ADMIN, UserRoleType.SERVICE_MANAGER, UserRoleType.SERVICE_ENGINEER) as any, statusHandler);

