  // 98. Service: Spare Parts Inventory Catalog
  const getPartsHandler = (req: any, res: any) => {
    const { search } = req.query;
    let parts = [...serviceSparePartsDb];

    if (search) {
      const q = String(search).toLowerCase();
      parts = parts.filter(p => p.partName.toLowerCase().includes(q) || p.partNumber.toLowerCase().includes(q) || p.compatibleModels.some(m => m.toLowerCase().includes(q)));
    }

    res.json({
      statusCode: 200,
      data: parts
    });
  };
  app.get("/api/v1/service/parts-catalog", getPartsHandler);
  app.get("/api/v1/service/parts", getPartsHandler);

  // 99. Service: Operational Stats & SLA Dashboard Metrics
  app.get("/api/v1/service/stats", (req, res) => {
    const total = serviceTicketsDb.length;
    const newCount = serviceTicketsDb.filter(t => t.status === "NEW").length;
    const assignedCount = serviceTicketsDb.filter(t => t.status === "ASSIGNED").length;
    const inProgressCount = serviceTicketsDb.filter(t => ["ACKNOWLEDGED", "SCHEDULED", "ENGINEER_ON_THE_WAY", "CHECKED_IN", "IN_PROGRESS"].includes(t.status)).length;
    const waitingForPartsCount = serviceTicketsDb.filter(t => t.status === "WAITING_FOR_PARTS").length;
    const resolvedCount = serviceTicketsDb.filter(t => ["RESOLVED", "CUSTOMER_FEEDBACK_PENDING", "BACK_OFFICE_REVIEW"].includes(t.status)).length;
    const closedCount = serviceTicketsDb.filter(t => t.status === "CLOSED").length;
    const disputedCount = serviceTicketsDb.filter(t => t.status === "CUSTOMER_DISPUTED_RESOLUTION").length;
    const breachedCount = serviceTicketsDb.filter(t => t.slaStatus === "BREACHED").length;

    const complianceRate = total > 0 ? Math.round(((total - breachedCount) / total) * 100) : 100;
    const equipmentBreakdownCount = serviceTicketsDb.filter(t => t.category === "EQUIPMENT_BREAKDOWN").length;
    const reagentComplaintCount = serviceTicketsDb.filter(t => t.category === "REAGENT_QUALITY_ISSUE").length;

    // Calculate customer satisfaction average
    const rated = serviceTicketsDb.filter(t => t.customerFeedback?.rating);
    const avgRating = rated.length > 0 ? Math.round((rated.reduce((acc, t) => acc + (t.customerFeedback?.rating || 0), 0) / rated.length) * 10) / 10 : 4.8;

    const stats: ServiceDeskStats = {
      totalTickets: total,
      newTickets: newCount,
      assignedTickets: assignedCount,
      inProgressTickets: inProgressCount,
      waitingForPartsTickets: waitingForPartsCount,
      resolvedTickets: resolvedCount,
      closedTickets: closedCount,
      disputedTickets: disputedCount,
      slaBreachedCount: breachedCount,
      slaComplianceRate: complianceRate,
      avgResolutionTimeHours: 3.4,
      customerSatisfactionAvg: avgRating,
      equipmentBreakdownCount,
      reagentComplaintCount
    };

    res.json({
      statusCode: 200,
      data: stats
    });
  });

