  app.post("/api/v1/pricing/rules/:id/approve", async (req, res) => {
    const mode = getPersistenceMode();
    if (mode === PersistenceMode.POSTGRES_DISCONNECTED) {
      return res.status(503).json({
        statusCode: 503,
        error: "DATABASE_UNAVAILABLE",
        message: "PostgreSQL database is currently disconnected. Pricing rule approval cannot be processed."
      });
    }

    const { id } = req.params;
    const checkerId = (req as any).user?.id || req.body.checkerId || "u-admin-01";
    const checkerEmail = (req as any).user?.email || req.body.checkerEmail || "admin@a2zdiagnostics.com";

    const ruleIndex = customerPriceRulesDb.findIndex(r => r.id === id);
    if (ruleIndex === -1) {
      return res.status(404).json({ statusCode: 404, message: "Pricing rule not found", error: "Not Found" });
    }
    const rule = customerPriceRulesDb[ruleIndex];

    // Dual-Control Maker-Checker Strict Rule
    if (rule.makerId === checkerId) {
      return res.status(403).json({
        statusCode: 403,
        error: "MAKER_CANNOT_BE_CHECKER",
        message: "Dual-Control Security Violation: A user cannot approve their own pricing rule proposal. Independent checker required."
      });
    }

    const ruleSnapshot = JSON.stringify(rule);

    rule.approvalStatus = "APPROVED";
    rule.checkerId = checkerId;
    rule.checkerEmail = checkerEmail;
    rule.approvedAt = new Date().toISOString();
    rule.updatedAt = new Date().toISOString();

    if (mode === PersistenceMode.POSTGRES_AUTHORITATIVE) {
      try {
        await commercialRulesRepository.approvePriceRuleTx(id, checkerId, checkerEmail);
      } catch (err: any) {
        customerPriceRulesDb[ruleIndex] = JSON.parse(ruleSnapshot);
        if (err.code === "MAKER_CANNOT_BE_CHECKER") {
          return res.status(403).json({
            statusCode: 403,
            error: "MAKER_CANNOT_BE_CHECKER",
            message: err.message
          });
        }
        return res.status(500).json({
          statusCode: 500,
          error: "DATABASE_WRITE_ERROR",
          message: `Failed to approve pricing rule in PostgreSQL: ${err.message}`
        });
      }
    } else {
      persistAllBusinessData();
    }

    logAudit(req, "PRICING_RULE_APPROVED", "PRICING", "SUCCESS", {
      resourceType: "PRICING_RULE",
      resourceId: rule.id,
      details: { customerId: rule.customerId, checkerId, makerId: rule.makerId }
    });

    res.json({
      statusCode: 200,
      message: `Pricing rule ${rule.id} approved and activated for customer.`,
      data: rule
    });
  });

