  // 107. Order Amendment (Controlled Financial Corrections with Credit Notes)
  app.post("/api/v1/admin/orders/:id/amend", async (req, res) => {
    const mode = getPersistenceMode();
    if (mode === PersistenceMode.POSTGRES_DISCONNECTED) {
      return res.status(503).json({
        statusCode: 503,
        error: "DATABASE_UNAVAILABLE",
        message: "PostgreSQL database is currently disconnected. Order amendment cannot be processed."
      });
    }

    const { id } = req.params;
    const {
      amendmentType = "PRICE_CORRECTION_CREDIT_NOTE",
      revisedSubtotal,
      creditAmount = 0,
      creditNoteNumber,
      justification,
      makerId = "u-office-01",
      checkerId = "u-admin-01"
    } = req.body;

    const orderIndex = customerOrdersDb.findIndex(o => o.id === id || o.orderNumber === id);
    if (orderIndex === -1) {
      return res.status(404).json({ statusCode: 404, message: "Order not found", error: "Not Found" });
    }
    const order = customerOrdersDb[orderIndex];

    if (!justification) {
      return res.status(400).json({ statusCode: 400, message: "Mandatory justification is required for order amendment", error: "Bad Request" });
    }

    // Dual-Control Maker-Checker Strict Rule
    if (makerId === checkerId) {
      return res.status(403).json({
        statusCode: 403,
        error: "MAKER_CANNOT_BE_CHECKER",
        message: "Dual-Control Security Violation: Maker and Checker cannot be the same user for financial corrections."
      });
    }

    const generatedCreditNoteNumber = creditNoteNumber || `CN-2026-${Math.floor(1000 + Math.random() * 9000)}`;

    // Idempotency: Prevent duplicate credit note number
    const isDuplicateCreditNote = orderAmendmentsDb.some(a => a.creditNoteNumber === generatedCreditNoteNumber) ||
      (Array.isArray(order.statusHistory) && order.statusHistory.some((h: any) => h.creditNoteNumber === generatedCreditNoteNumber));
    if (isDuplicateCreditNote) {
      return res.status(409).json({
        statusCode: 409,
        error: "DUPLICATE_CREDIT_NOTE",
        message: `Credit note ${generatedCreditNoteNumber} has already been applied.`
      });
    }

    const numericCredit = Number(creditAmount) || 0;
    const amendment: OrderAmendmentAuditEntity = {
      id: `amd-${Date.now()}`,
      orderId: order.id,
      orderNumber: order.orderNumber,
      amendedBy: (req as any).user?.id || checkerId,
      amendedByName: (req as any).user?.name || "Chief Financial Officer",
      amendedByRole: (req as any).user?.roleType || "FINANCE_ADMIN",
      amendmentType,
      originalSubtotal: order.subtotal,
      revisedSubtotal: Number(revisedSubtotal) || order.subtotal,
      creditNoteNumber: generatedCreditNoteNumber,
      creditAmount: numericCredit,
      justification,
      makerId,
      checkerId,
      approvedAt: new Date().toISOString(),
      createdAt: new Date().toISOString()
    };

    const ledgerEntry = numericCredit > 0 ? {
      id: `led-cn-${Date.now()}`,
      date: new Date().toISOString().split("T")[0],
      type: "CREDIT_NOTE" as const,
      description: `Credit Note #${amendment.creditNoteNumber}: ${amendment.justification}`,
      referenceNumber: amendment.creditNoteNumber,
      amount: -numericCredit,
      runningBalance: customerWalletsDb[order.customerId] ? Math.max(0, (customerWalletsDb[order.customerId].currentOutstanding || 0) - numericCredit) : 0
    } : undefined;

    const auditLogData: AuditLogEntity = {
      id: `aud-${Date.now()}-${Math.random().toString(36).substring(2, 7)}`,
      userId: (req as any).user?.id || checkerId,
      userEmail: (req as any).user?.email || "cfo@a2zdiagnostics.com",
      userRole: (req as any).user?.roleType || "FINANCE_ADMIN",
      action: "ORDER_AMENDMENT_RECORDED",
      module: "ORDER",
      resourceType: "ORDER",
      resourceId: order.id,
      ipAddress: (req.headers["x-forwarded-for"] as string) || req.socket.remoteAddress || "127.0.0.1",
      userAgent: req.headers["user-agent"] || "Unknown",
      status: "WARNING",
      details: { orderNumber: order.orderNumber, creditNoteNumber: amendment.creditNoteNumber, creditAmount: numericCredit, justification },
      timestamp: new Date().toISOString()
    };

    // In-memory snapshots for atomic rollback
    const orderSnapshot = JSON.stringify(order);
    const walletSnapshot = customerWalletsDb[order.customerId] ? JSON.stringify(customerWalletsDb[order.customerId]) : null;
    const creditSnapshot = customerCreditProfilesDb[order.customerId] ? JSON.stringify(customerCreditProfilesDb[order.customerId]) : null;
    const orderAmendmentsSnapshot = JSON.stringify(orderAmendmentsDb);

    // Apply in-memory mutations
    orderAmendmentsDb.unshift(amendment);
    if (revisedSubtotal !== undefined) {
      order.subtotal = Number(revisedSubtotal);
    }
    if (!order.statusHistory) order.statusHistory = [];
    order.statusHistory.unshift(amendment);
    order.notes = order.notes
      ? `${order.notes} | [AMENDMENT] CN: ${amendment.creditNoteNumber} (${amendment.justification})`
      : `[AMENDMENT] CN: ${amendment.creditNoteNumber} (${amendment.justification})`;

    if (numericCredit > 0 && customerWalletsDb[order.customerId]) {
      const wallet = customerWalletsDb[order.customerId];
      wallet.currentOutstanding = Math.max(0, (wallet.currentOutstanding || 0) - numericCredit);
      wallet.availableCredit = Math.min(wallet.creditLimit, Math.max(0, wallet.creditLimit - wallet.currentOutstanding));
      if (ledgerEntry) {
        wallet.ledgerEntries.unshift(ledgerEntry);
      }
    }
    if (numericCredit > 0 && customerCreditProfilesDb[order.customerId]) {
      const profile = customerCreditProfilesDb[order.customerId];
      profile.currentOutstanding = Math.max(0, (profile.currentOutstanding || 0) - numericCredit);
      profile.availableCredit = Math.min(profile.creditLimit, Math.max(0, profile.creditLimit - profile.currentOutstanding));
    }

    if (mode === PersistenceMode.POSTGRES_AUTHORITATIVE) {
      try {
        await financialRepository.amendOrderWithCreditNoteTx({
          orderIdOrNumber: order.id,
          amendment,
          creditDeduction: numericCredit > 0 ? {
            customerId: order.customerId,
            creditAmount: numericCredit,
            ledgerEntry
          } : undefined,
          auditLog: auditLogData
        });
      } catch (err: any) {
        // Atomic rollback of in-memory state
        customerOrdersDb[orderIndex] = JSON.parse(orderSnapshot);
        if (walletSnapshot) customerWalletsDb[order.customerId] = JSON.parse(walletSnapshot);
        if (creditSnapshot) customerCreditProfilesDb[order.customerId] = JSON.parse(creditSnapshot);
        orderAmendmentsDb.length = 0;
        orderAmendmentsDb.push(...JSON.parse(orderAmendmentsSnapshot));

        if (err.code === "DUPLICATE_CREDIT_NOTE") {
          return res.status(409).json({
            statusCode: 409,
            error: "DUPLICATE_CREDIT_NOTE",
            message: err.message
          });
        }
        if (err.code === "MAKER_CANNOT_BE_CHECKER") {
          return res.status(403).json({
            statusCode: 403,
            error: "MAKER_CANNOT_BE_CHECKER",
            message: err.message
          });
        }
        return res.status(500).json({
          statusCode: 500,
          error: "DATABASE_WRITE_ERROR",
          message: `Failed to persist order amendment in PostgreSQL: ${err.message}`
        });
      }
    } else {
      persistAllBusinessData();
    }

    auditLogsDb.unshift(auditLogData);
    if (auditLogsDb.length > 500) auditLogsDb.pop();

    res.status(201).json({
      statusCode: 201,
      message: `Order #${order.orderNumber} amendment registered with Credit Note #${amendment.creditNoteNumber}. Historical snapshot preserved.`,
      data: amendment,
      order
    });
  });

  // 108. Order Amendments List
  app.get("/api/v1/admin/orders/:id/amendments", async (req, res) => {
    const mode = getPersistenceMode();
    if (mode === PersistenceMode.POSTGRES_DISCONNECTED) {
      return res.status(503).json({
        statusCode: 503,
        error: "DATABASE_UNAVAILABLE",
        message: "PostgreSQL database is currently disconnected. Order amendments cannot be queried."
      });
    }

    const { id } = req.params;

    if (mode === PersistenceMode.POSTGRES_AUTHORITATIVE) {
      try {
        const list = await financialRepository.findAmendmentsByOrderId(id);
        return res.json({ statusCode: 200, data: list });
      } catch (err: any) {
        return res.status(503).json({
          statusCode: 503,
          error: "DATABASE_READ_ERROR",
          message: `Failed to query order amendments from PostgreSQL: ${err.message}`
        });
      }
    }

    const list = orderAmendmentsDb.filter(a => a.orderId === id || a.orderNumber === id);
    res.json({ statusCode: 200, data: list });
  });

