  // 1. PM Equipment List with Server-Authoritative Coverage & Health Scores
  app.get("/api/v1/pm/equipment", (req: AuthenticatedRequest, res) => {
    const { customerId, status, healthLevel, coverageState, search } = req.query;

    let list = customerEquipmentDb.map(eq => {
      const cov = calculateEquipmentCoverage(eq.id);
      const health = calculateEquipmentHealthScore(eq.id);
      const activeWorkOrder = pmWorkOrdersDb.find(
        p => p.equipmentId === eq.id && !["COMPLETED", "CLOSED", "CANCELLED"].includes(p.status)
      );

      return {
        ...eq,
        coverageState: cov.coverageState,
        activeCoverage: cov.activeCoverage,
        healthScore: health.score,
        healthLevel: health.level,
        healthColorClass: health.colorClass,
        openTicketCount: health.openTicketCount,
        activePmWorkOrder: activeWorkOrder ? {
          id: activeWorkOrder.id,
          pmWorkOrderNumber: activeWorkOrder.pmWorkOrderNumber,
          scheduledDueDate: activeWorkOrder.scheduledDueDate,
          status: activeWorkOrder.status,
          assignedEngineerName: activeWorkOrder.assignedEngineerName
        } : null
      };
    });

    if (customerId) {
      list = list.filter(e => e.customerId === customerId);
    }
    if (status) {
      list = list.filter(e => e.status === status);
    }
    if (healthLevel) {
      list = list.filter(e => e.healthLevel === healthLevel);
    }
    if (coverageState) {
      list = list.filter(e => e.coverageState === coverageState);
    }
    if (search) {
      const q = String(search).toLowerCase();
      list = list.filter(e =>
        e.equipmentName?.toLowerCase().includes(q) ||
        e.modelNumber?.toLowerCase().includes(q) ||
        e.serialNumber?.toLowerCase().includes(q) ||
        e.customerLabName?.toLowerCase().includes(q)
      );
    }

    res.json({
      statusCode: 200,
      data: list,
      total: list.length
    });
  });

