  // 8. Generate Scheduled PM Work Orders (Schedule Engine Runner)
  app.post("/api/v1/pm/work-orders/generate", (req: AuthenticatedRequest, res) => {
    const { forceAll = false } = req.body;
    const generated: any[] = [];
    const skipped: any[] = [];

    const now = new Date();
    const currentYear = now.getFullYear();
    const currentQuarter = Math.floor(now.getMonth() / 3) + 1;
    const currentPeriodKey = `${currentYear}-Q${currentQuarter}`;

    customerEquipmentDb.forEach(eq => {
      // Check if active or scheduled PM already exists for current period to prevent duplicates
      const existing = pmWorkOrdersDb.find(
        p => p.equipmentId === eq.id && (p.periodKey === currentPeriodKey || ["SCHEDULED", "DUE_SOON", "ASSIGNED", "ACCEPTED", "IN_PROGRESS"].includes(p.status))
      );

      if (existing && !forceAll) {
        skipped.push({ equipmentId: eq.id, reason: `Work Order #${existing.pmWorkOrderNumber} already exists for this cycle.` });
        return;
      }

      // Determine appropriate checklist template
      const template = pmChecklistTemplatesDb.find(t => 
        t.modelNumber?.toLowerCase().includes(eq.modelNumber?.toLowerCase()) ||
        eq.modelNumber?.toLowerCase().includes(t.modelNumber?.toLowerCase())
      ) || pmChecklistTemplatesDb[0];

      // Auto-assign qualified engineer
      const assignedEng = autoAssignBestEngineerForPm(eq, eq.locationDepartment);
      const coverage = calculateEquipmentCoverage(eq.id);

      const pmNumber = `PM-${currentYear}-${Math.floor(1000 + Math.random() * 9000)}`;
      const dueDate = eq.nextPmDueDate || new Date(Date.now() + 14 * 24 * 60 * 60 * 1000).toISOString().split("T")[0];
      const reminderStart = new Date(new Date(dueDate).getTime() - 30 * 24 * 60 * 60 * 1000).toISOString().split("T")[0];

      const newWo = {
        id: `pm-wo-${Date.now()}-${Math.floor(Math.random() * 1000)}`,
        pmWorkOrderNumber: pmNumber,
        equipmentId: eq.id,
        equipmentName: eq.equipmentName,
        modelNumber: eq.modelNumber,
        serialNumber: eq.serialNumber,
        companyName: "Diagnostic OEM",
        customerId: eq.customerId,
        customerLabName: eq.customerLabName,
        customerAddress: eq.locationDepartment,
        contactPerson: eq.contactPerson,
        contactPhone: eq.contactPhone,
        coverageType: coverage.activeCoverage?.coverageType || "AMC",
        coverageStatus: coverage.coverageState,
        maintenancePlan: "Quarterly Comprehensive PM",
        pmFrequency: "QUARTERLY",
        scheduledDueDate: dueDate,
        reminderWindowStartDate: reminderStart,
        periodKey: currentPeriodKey,
        status: assignedEng ? "ASSIGNED" : "DUE_SOON",
        assignedEngineerId: assignedEng?.engineerId,
        assignedEngineerName: assignedEng?.engineerName,
        assignedEngineerPhone: assignedEng?.phone,
        assignedAt: assignedEng ? new Date().toISOString() : undefined,
        checklistTemplateId: template?.id,
        checklistItems: template?.items?.map((item: any) => ({
          itemId: item.id,
          category: item.category,
          title: item.title,
          isMandatory: item.isMandatory,
          result: "NOT_APPLICABLE",
          expectedRange: item.expectedRange,
          readingUnit: item.readingUnit
        })) || [],
        auditHistory: [
          {
            timestamp: new Date().toISOString(),
            fromStatus: "NONE",
            toStatus: assignedEng ? "ASSIGNED" : "DUE_SOON",
            userId: req.user?.id || "system",
            userName: req.user?.email || "PM Schedule Engine",
            userRole: req.user?.roleType || "SYSTEM",
            reason: "Auto-generated by Maintenance Schedule Engine"
          }
        ],
        createdAt: new Date().toISOString(),
        updatedAt: new Date().toISOString()
      };

      if (assignedEng) {
        assignedEng.activeWorkloadCount += 1;
      }

      pmWorkOrdersDb.unshift(newWo);
      generated.push(newWo);
    });

    logAudit(req, "PM_BATCH_SCHEDULE_GENERATED", "SERVICE", "SUCCESS", {
      details: { generatedCount: generated.length, skippedCount: skipped.length }
    });

    res.status(201).json({
      statusCode: 201,
      message: `Schedule Engine executed. Generated ${generated.length} PM Work Orders, skipped ${skipped.length} duplicates.`,
      data: { generated, skipped }
    });
  });

