  // 13. PM Work Order: Complete & Server Validate (Generates Next PM Date + Recalculates Health)
  app.post("/api/v1/pm/work-orders/:id/complete", (req: AuthenticatedRequest, res) => {
    const { id } = req.params;
    const {
      checklistItems,
      engineerNotes = "All PM protocol checks completed per standard biomedical operating procedures.",
      partsReplaced = [],
      customerSignatoryName = "Dr. Rajesh Kulkarni",
      customerSignatureUrl = "data:image/png;base64,iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAYAAAAfFcSJAAAADUlEQVR42mNk+M9QDwADhgGAWjR9awAAAABJRU5ErkJggg==",
      autoCreateTicketForFailures = true
    } = req.body;

    const wo = pmWorkOrdersDb.find(p => p.id === id || p.pmWorkOrderNumber === id);
    if (!wo) {
      return res.status(404).json({ statusCode: 404, message: "PM Work Order not found" });
    }

    if (checklistItems && Array.isArray(checklistItems)) {
      wo.checklistItems = checklistItems;
    }

    // SERVER VALIDATION: Check mandatory items
    const uncompletedMandatory = wo.checklistItems.filter(
      (i: any) => i.isMandatory && (!i.result || i.result === "NOT_APPLICABLE")
    );

    if (uncompletedMandatory.length > 0) {
      return res.status(422).json({
        statusCode: 422,
        error: "INCOMPLETE_MANDATORY_CHECKLIST",
        message: `Validation Error: ${uncompletedMandatory.length} mandatory checklist item(s) are incomplete. PM cannot be closed without completing all required items.`,
        uncompletedItems: uncompletedMandatory.map((i: any) => i.title)
      });
    }

    // FAULT DISCOVERY: Check if any item failed
    const failedItems = wo.checklistItems.filter((i: any) => i.result === "FAIL");
    let linkedBreakdownTicketId: string | undefined = undefined;

    if (failedItems.length > 0 && autoCreateTicketForFailures) {
      // Auto-generate linked breakdown service ticket
      const newTicketNumber = `TCK-${new Date().getFullYear()}-${Math.floor(1000 + Math.random() * 9000)}`;
      const breakdownTicket: any = {
        id: `tck-${Date.now()}`,
        ticketNumber: newTicketNumber,
        customerId: wo.customerId,
        customerLabName: wo.customerLabName,
        customerContactPerson: wo.contactPerson,
        customerPhone: wo.contactPhone,
        customerAddress: wo.customerAddress,
        category: "EQUIPMENT_BREAKDOWN",
        equipmentId: wo.equipmentId,
        equipmentName: wo.equipmentName,
        equipmentModel: wo.modelNumber,
        equipmentSerial: wo.serialNumber,
        priority: "HIGH",
        title: `Defect identified during PM: ${failedItems[0].title}`,
        description: `Discovered failed PM checklist item(s): ${failedItems.map((f: any) => f.title).join(", ")}. Engineer Notes: ${engineerNotes}`,
        status: "IN_PROGRESS",
        assignedEngineerId: wo.assignedEngineerId,
        assignedEngineerName: wo.assignedEngineerName,
        slaTargetHours: 8,
        slaTargetTimestamp: new Date(Date.now() + 8 * 3600000).toISOString(),
        slaStatus: "ON_TRACK",
        notes: [],
        attachments: [],
        partsUsed: [],
        customerCommunication: [],
        disputeHistory: [],
        createdAt: new Date().toISOString(),
        updatedAt: new Date().toISOString()
      };
      serviceTicketsDb.unshift(breakdownTicket);
      linkedBreakdownTicketId = breakdownTicket.id;
    }

    const now = new Date().toISOString();
    const prevStatus = wo.status;

    // Calculate next PM schedule
    const nextSchedule = calculateNextPmDueDate(now.split("T")[0], wo.pmFrequency || "QUARTERLY");
    wo.nextGeneratedPmDate = nextSchedule.nextDueDate;

    wo.status = "COMPLETED";
    wo.completedAt = now;
    wo.engineerNotes = engineerNotes;
    wo.partsReplaced = partsReplaced;
    wo.customerSignatoryName = customerSignatoryName;
    wo.customerSignatureUrl = customerSignatureUrl;
    wo.updatedAt = now;

    wo.auditHistory.push({
      timestamp: now,
      fromStatus: prevStatus,
      toStatus: "COMPLETED",
      userId: req.user?.id || wo.assignedEngineerId || "u-eng-01",
      userName: wo.assignedEngineerName || "Service Engineer",
      userRole: "SERVICE_ENGINEER",
      reason: `PM Protocol completed. Next scheduled due date: ${nextSchedule.nextDueDate}. ${failedItems.length > 0 ? `${failedItems.length} failure(s) escalated to Breakdown Ticket #${linkedBreakdownTicketId}` : "All checks PASSED."}`
    });

    // Update equipment records
    const eq = customerEquipmentDb.find(e => e.id === wo.equipmentId);
    if (eq) {
      eq.lastServiceDate = now.split("T")[0];
      eq.nextPmDueDate = nextSchedule.nextDueDate;
      if (failedItems.length === 0) {
        eq.status = "OPERATIONAL";
      }
    }

    // Add Timeline Event
    equipmentTimelineDb.unshift({
      id: `tml-${Date.now()}`,
      equipmentId: wo.equipmentId,
      eventType: "PREVENTIVE_MAINTENANCE",
      title: `PM Milestone Completed (#${wo.pmWorkOrderNumber})`,
      description: `Comprehensive PM checks completed by ${wo.assignedEngineerName}. Next PM due on ${nextSchedule.nextDueDate}.`,
      status: "COMPLETED",
      date: now,
      referenceId: wo.pmWorkOrderNumber,
      performerName: wo.assignedEngineerName,
      severity: failedItems.length > 0 ? "WARNING" : "SUCCESS"
    });

    // Auto-schedule next cycle PM in database
    const nextWoNumber = `PM-${new Date().getFullYear()}-${Math.floor(1000 + Math.random() * 9000)}`;
    const nextWo = {
      id: `pm-wo-${Date.now() + 1}`,
      pmWorkOrderNumber: nextWoNumber,
      equipmentId: wo.equipmentId,
      equipmentName: wo.equipmentName,
      modelNumber: wo.modelNumber,
      serialNumber: wo.serialNumber,
      companyName: wo.companyName,
      customerId: wo.customerId,
      customerLabName: wo.customerLabName,
      customerAddress: wo.customerAddress,
      contactPerson: wo.contactPerson,
      contactPhone: wo.contactPhone,
      coverageType: wo.coverageType,
      coverageStatus: wo.coverageStatus,
      maintenancePlan: wo.maintenancePlan,
      pmFrequency: wo.pmFrequency,
      scheduledDueDate: nextSchedule.nextDueDate,
      reminderWindowStartDate: nextSchedule.reminderWindowStartDate,
      periodKey: nextSchedule.periodKey,
      status: "SCHEDULED",
      assignedEngineerId: wo.assignedEngineerId,
      assignedEngineerName: wo.assignedEngineerName,
      assignedEngineerPhone: wo.assignedEngineerPhone,
      checklistTemplateId: wo.checklistTemplateId,
      checklistItems: [],
      auditHistory: [
        {
          timestamp: now,
          fromStatus: "NONE",
          toStatus: "SCHEDULED",
          userId: "system",
          userName: "PM Schedule Engine",
          userRole: "SYSTEM",
          reason: `Auto-generated upon completion of PM #${wo.pmWorkOrderNumber}`
        }
      ],
      createdAt: now,
      updatedAt: now
    };
    pmWorkOrdersDb.unshift(nextWo);

    logAudit(req, "PM_WORK_ORDER_COMPLETED", "SERVICE", "SUCCESS", {
      resourceType: "PM_WORK_ORDER",
      resourceId: wo.id,
      details: {
        pmWorkOrderNumber: wo.pmWorkOrderNumber,
        nextDueDate: nextSchedule.nextDueDate,
        failedChecklistCount: failedItems.length
      }
    });

    res.json({
      statusCode: 200,
      message: `PM Work Order #${wo.pmWorkOrderNumber} completed successfully. Next PM scheduled for ${nextSchedule.nextDueDate}.`,
      data: {
        workOrder: wo,
        nextWorkOrder: nextWo,
        linkedBreakdownTicketId
      }
    });
  });

  // 14. PM Work Order: Customer Digital Sign-off
  app.post("/api/v1/pm/work-orders/:id/customer-signoff", (req: AuthenticatedRequest, res) => {
    const { id } = req.params;
    const {
      signatoryName = "Dr. Rajesh Kulkarni",
      signatureUrl = "data:image/png;base64,iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAYAAAAfFcSJAAAADUlEQVR42mNk+M9QDwADhgGAWjR9awAAAABJRU5ErkJggg==",
      rating = 5,
      feedbackNotes = "PM executed thoroughly. Optical calibrations verified."
    } = req.body;

    const wo = pmWorkOrdersDb.find(p => p.id === id || p.pmWorkOrderNumber === id);
    if (!wo) {
      return res.status(404).json({ statusCode: 404, message: "PM Work Order not found" });
    }

    wo.customerSignatoryName = signatoryName;
    wo.customerSignatureUrl = signatureUrl;
    wo.customerRating = rating;
    wo.customerFeedback = feedbackNotes;
    wo.updatedAt = new Date().toISOString();

    res.json({
      statusCode: 200,
      message: "Customer signature and feedback recorded.",
      data: wo
    });
  });

  // 15. PM Work Order: Back-Office Close
  app.post("/api/v1/pm/work-orders/:id/close", (req: AuthenticatedRequest, res) => {
    const { id } = req.params;
    const { reviewNotes = "PM service report and NABL calibration certificates audited and archived." } = req.body;

    const wo = pmWorkOrdersDb.find(p => p.id === id || p.pmWorkOrderNumber === id);
    if (!wo) {
      return res.status(404).json({ statusCode: 404, message: "PM Work Order not found" });
    }

    const prevStatus = wo.status;
    wo.status = "CLOSED";
    wo.closedAt = new Date().toISOString();
    wo.updatedAt = new Date().toISOString();

    wo.auditHistory.push({
      timestamp: new Date().toISOString(),
      fromStatus: prevStatus,
      toStatus: "CLOSED",
      userId: req.user?.id || "u-smgr-01",
      userName: req.user?.email || "Service Manager",
      userRole: "SERVICE_MANAGER",
      reason: `Back-Office Audit Completed: ${reviewNotes}`
    });

    res.json({
      statusCode: 200,
      message: `PM Work Order #${wo.pmWorkOrderNumber} CLOSED.`,
      data: wo
    });
  });

  // 16. Offline Draft Sync Handler
  app.post("/api/v1/pm/work-orders/sync-offline-draft", (req: AuthenticatedRequest, res) => {
    const { offlineDrafts } = req.body;
    if (!offlineDrafts || !Array.isArray(offlineDrafts)) {
      return res.status(400).json({ statusCode: 400, message: "offlineDrafts array is required" });
    }

    const results: any[] = [];

    offlineDrafts.forEach(draft => {
      const wo = pmWorkOrdersDb.find(p => p.id === draft.id || p.pmWorkOrderNumber === draft.pmWorkOrderNumber);
      if (!wo) {
        results.push({ draftId: draft.id, syncStatus: "FAILED", error: "Work Order not found on server" });
        return;
      }

      // Check conflict
      if (wo.status === "COMPLETED" || wo.status === "CLOSED") {
        results.push({ draftId: draft.id, syncStatus: "CONFLICT", message: "Already completed on server", serverData: wo });
        return;
      }

      if (draft.checklistItems) wo.checklistItems = draft.checklistItems;
      if (draft.engineerNotes) wo.engineerNotes = draft.engineerNotes;
      if (draft.partsReplaced) wo.partsReplaced = draft.partsReplaced;
      wo.updatedAt = new Date().toISOString();

      results.push({ draftId: draft.id, syncStatus: "SYNCED", serverData: wo });
    });

    res.json({
      statusCode: 200,
      message: `Processed ${offlineDrafts.length} offline PM drafts.`,
      data: results
    });
  });

  // 17. Preventive Maintenance Admin Metrics & KPIs
  app.get("/api/v1/pm/metrics/admin", (req: AuthenticatedRequest, res) => {
    const totalEquipment = customerEquipmentDb.length;
    const allCoverages = customerEquipmentDb.map(e => calculateEquipmentCoverage(e.id));
    const allHealth = customerEquipmentDb.map(e => calculateEquipmentHealthScore(e.id));

    const totalWorkOrders = pmWorkOrdersDb.length;
    const completedWorkOrders = pmWorkOrdersDb.filter(p => p.status === "COMPLETED" || p.status === "CLOSED").length;
    const complianceRate = totalWorkOrders > 0 ? Math.round((completedWorkOrders / totalWorkOrders) * 100) : 100;

    const overdueCount = pmWorkOrdersDb.filter(p => p.status === "OVERDUE" || (p.status !== "COMPLETED" && p.status !== "CLOSED" && new Date(p.scheduledDueDate).getTime() < Date.now())).length;
    const dueSoonCount = pmWorkOrdersDb.filter(p => p.status === "DUE_SOON" || p.status === "SCHEDULED").length;
    const inProgressCount = pmWorkOrdersDb.filter(p => p.status === "IN_PROGRESS" || p.status === "ACCEPTED" || p.status === "ASSIGNED").length;

    const expiringCoverageCount = allCoverages.filter(c => c.coverageState.includes("EXPIRING_SOON")).length;
    const expiredCoverageCount = allCoverages.filter(c => c.coverageState.includes("EXPIRED") || c.coverageState === "NO_ACTIVE_COVERAGE").length;
    const criticalHealthCount = allHealth.filter(h => h.level === "CRITICAL" || h.level === "AT_RISK").length;

    res.json({
      statusCode: 200,
      data: {
        totalEquipment,
        complianceRate,
        overdueCount,
        dueSoonCount,
        inProgressCount,
        completedWorkOrders,
        expiringCoverageCount,
        expiredCoverageCount,
        criticalHealthCount,
        engineerWorkloads: engineerQualificationsDb.map(e => ({
          engineerId: e.engineerId,
          engineerName: e.engineerName,
          activeWorkloadCount: e.activeWorkloadCount,
          maxCapacity: e.maxConcurrentJobs,
          utilizationPercent: Math.round((e.activeWorkloadCount / e.maxConcurrentJobs) * 100)
        }))
      }
    });
  });

  // 18. PM Qualified Biomedical Engineers List
  app.get("/api/v1/pm/engineers", (req, res) => {
    res.json({
      statusCode: 200,
      data: engineerQualificationsDb
    });
  });

