  // Helper to execute a single sync item with idempotency and business logic
  function processSyncItemInternal(item: any, user: any): {
    id: string;
    idempotencyKey: string;
    actionType: string;
    status: 'SYNCED' | 'FAILED' | 'CONFLICT';
    isIdempotencyReplay: boolean;
    serverConfirmedAt: string;
    serverEntityId?: string;
    message: string;
    errorMessage?: string;
    conflictDetails?: any;
  } {
    const now = new Date().toISOString();
    const idempotencyKey = item.idempotencyKey || `IDEM-${item.actionType}-${item.id}`;

    // 1. Check Idempotency Key Replay
    if (syncIdempotencyDb.has(idempotencyKey)) {
      const existing = syncIdempotencyDb.get(idempotencyKey)!;
      return {
        id: item.id,
        idempotencyKey,
        actionType: item.actionType,
        status: 'SYNCED',
        isIdempotencyReplay: true,
        serverConfirmedAt: existing.processedAt,
        serverEntityId: existing.serverEntityId,
        message: `Idempotency replay recognized: action already securely committed at ${existing.processedAt} without duplicate side-effects.`
      };
    }

    try {
      let serverEntityId = `ent-${Date.now()}-${Math.floor(Math.random() * 1000)}`;
      let successMessage = "Offline action processed and committed to server repository.";

      // 2. Policy & Action Execution
      switch (item.actionType) {
        case "ATTENDANCE_CHECKIN":
        case "ATTENDANCE_CHECKOUT": {
          const payload = item.businessData || {};
          const isPunchIn = item.actionType === "ATTENDANCE_CHECKIN" || payload.punchType === "PUNCH_IN";
          serverEntityId = `att-${Date.now()}`;
          
          engineerAttendanceDb.unshift({
            id: serverEntityId,
            idempotencyKey,
            engineerId: payload.engineerId || user?.id || "u-eng-01",
            engineerName: payload.engineerName || (user ? `${user.firstName || ''} ${user.lastName || ''}`.trim() : "Service Engineer"),
            punchType: isPunchIn ? "PUNCH_IN" : "PUNCH_OUT",
            shift: payload.shift || "GENERAL_MORNING",
            deviceTimestamp: item.createdAt || now,
            syncedAt: now,
            location: item.location || {
              latitude: 19.0760,
              longitude: 72.8777,
              accuracyMeters: 10,
              status: "LOCATION_CAPTURED_OFFLINE"
            },
            odometerReadingKm: payload.odometerReadingKm,
            batteryLevelPercent: payload.batteryLevelPercent,
            notes: payload.notes,
            status: "VERIFIED"
          });

          successMessage = `Attendance ${isPunchIn ? "Punch-In" : "Punch-Out"} registered successfully. Timestamp verified.`;
          break;
        }

        case "SERVICE_WORK_UPDATE": {
          const payload = item.businessData || {};
          const ticket = serviceTicketsDb.find(t => t.id === payload.ticketId || t.ticketNumber === payload.ticketNumber);
          
          if (!ticket) {
            return {
              id: item.id,
              idempotencyKey,
              actionType: item.actionType,
              status: "FAILED",
              isIdempotencyReplay: false,
              serverConfirmedAt: now,
              message: "Target service ticket was not found on server.",
              errorMessage: `Service ticket '${payload.ticketId || payload.ticketNumber}' does not exist.`
            };
          }

          // Check if ticket is already closed by supervisor/another user (Conflict condition)
          if (ticket.status === "CLOSED" || ticket.status === "CUSTOMER_FEEDBACK_PENDING") {
            const conflictObj = {
              itemId: item.id,
              actionType: item.actionType,
              conflictType: "TICKET_ALREADY_CLOSED",
              message: `Service ticket #${ticket.ticketNumber} is already in state '${ticket.status}'. Offline draft cannot blindly overwrite closed record.`,
              serverData: {
                ticketNumber: ticket.ticketNumber,
                status: ticket.status,
                updatedAt: ticket.updatedAt,
                resolution: ticket.resolution
              },
              clientData: payload,
              detectedAt: now,
              resolutionOptions: ["SERVER_WINS", "MERGE_FIELDS"]
            };

            return {
              id: item.id,
              idempotencyKey,
              actionType: item.actionType,
              status: "CONFLICT",
              isIdempotencyReplay: false,
              serverConfirmedAt: now,
              message: `Conflict detected on ticket #${ticket.ticketNumber}`,
              conflictDetails: conflictObj
            };
          }

          serverEntityId = ticket.id;
          
          // Apply draft work update to ticket notes and resolution draft
          if (payload.preliminaryObservations || payload.draftActionTaken) {
            ticket.notes.unshift({
              id: `not-sync-${Date.now()}`,
              ticketId: ticket.id,
              authorId: user?.id || "u-eng-01",
              authorName: user?.email || "Offline Field Engineer",
              authorRole: "SERVICE_ENGINEER",
              noteType: "INTERNAL",
              content: `[OFFLINE DRAFT SYNCED]: Observations: ${payload.preliminaryObservations || "None"}. Actions: ${payload.draftActionTaken || "None"}`,
              createdAt: item.createdAt || now
            });
          }

          if (payload.sparePartsDraft && Array.isArray(payload.sparePartsDraft) && payload.sparePartsDraft.length > 0) {
            ticket.partsUsed = ticket.partsUsed || [];
            payload.sparePartsDraft.forEach((p: any) => {
              const qty = p.quantity || 1;
              const cost = p.unitPrice || 1850;
              ticket.partsUsed.push({
                id: `prt-draft-${Date.now()}-${Math.floor(Math.random() * 1000)}`,
                ticketId: ticket.id,
                partId: p.partId || `part-${Date.now()}`,
                partName: p.partName || "Replacement Part",
                partNumber: p.partNumber || "SP-GEN-01",
                quantity: qty,
                unitCost: cost,
                totalCost: qty * cost,
                isWarrantyCovered: true,
                isBillable: false,
                addedBy: user?.firstName ? `${user.firstName} ${user.lastName || ''}`.trim() : "Service Engineer",
                addedAt: now
              });
            });
          }

          ticket.updatedAt = now;
          successMessage = `Field service draft for ticket #${ticket.ticketNumber} synced and appended to service timeline.`;
          break;
        }

        case "VISIT_REPORT": {
          const payload = item.businessData || {};
          serverEntityId = `vis-${Date.now()}`;
          
          fieldVisitReportsDb.unshift({
            id: serverEntityId,
            idempotencyKey,
            engineerOrSalesId: user?.id || "u-eng-01",
            authorName: user ? `${user.firstName || ''} ${user.lastName || ''}`.trim() || user.email : "Field Executive",
            labName: payload.labName || "Diagnostic Center",
            labAddress: payload.labAddress,
            doctorOrDirectorName: payload.doctorOrDirectorName || "Lab Incharge",
            contactNumber: payload.contactNumber,
            discussionSummary: payload.discussionSummary || "Standard periodic field visit discussion",
            followUpRequired: Boolean(payload.followUpRequired),
            followUpDate: payload.followUpDate,
            sampleCollectionRequired: Boolean(payload.sampleCollectionRequired),
            competitorReagentsNoticed: payload.competitorReagentsNoticed,
            estimatedMonthlyPotentialInr: Number(payload.estimatedMonthlyPotentialInr) || 0,
            deviceCreatedAt: item.createdAt || now,
            syncedAt: now
          });

          successMessage = `Field visit report for ${payload.labName || 'Client'} logged successfully.`;
          break;
        }

        case "EXPENSE_SUBMISSION": {
          const payload = item.businessData || {};
          serverEntityId = `exp-${Date.now()}`;
          
          engineerExpensesDb.unshift({
            id: serverEntityId,
            idempotencyKey,
            engineerId: user?.id || "u-eng-01",
            engineerName: user ? `${user.firstName || ''} ${user.lastName || ''}`.trim() || user.email : "Service Engineer",
            expenseCategory: payload.expenseCategory || "TRAVEL_FUEL",
            amount: Number(payload.amount) || 0,
            currency: payload.currency || "INR",
            billNumber: payload.billNumber,
            billDate: payload.billDate || now.split("T")[0],
            merchantName: payload.merchantName,
            description: payload.description || "Field expense claim",
            receiptAttachmentUrl: payload.receiptAttachmentUrl || item.attachmentDataUrl,
            status: "SUBMITTED",
            deviceCreatedAt: item.createdAt || now,
            syncedAt: now
          });

          successMessage = `Expense claim of ₹${payload.amount || 0} (${payload.expenseCategory || 'General'}) registered for audit approval.`;
          break;
        }

        case "SERVICE_FEEDBACK_SUBMISSION": {
          const payload = item.businessData || {};
          const ticket = serviceTicketsDb.find(t => t.id === payload.ticketId || t.ticketNumber === payload.ticketNumber);
          
          if (ticket) {
            ticket.customerFeedback = {
              rating: Number(payload.overallRating) || 5,
              feedbackNotes: payload.feedbackComments || "Excellent response time and repair quality.",
              customerSignatoryName: payload.customerAcknowledgedBy || "Lab Director",
              customerDesignation: payload.customerDesignation || "Chief Pathologist",
              submittedAt: now
            };
            ticket.status = "CLOSED";
            ticket.updatedAt = now;
            serverEntityId = ticket.id;
            successMessage = `Service ticket #${ticket.ticketNumber} feedback recorded and ticket closed.`;
          } else {
            serverEntityId = `fb-${Date.now()}`;
            successMessage = `Feedback recorded for ticket ${payload.ticketId || payload.ticketNumber}.`;
          }
          break;
        }

        case "ORDER_DRAFT_SYNC": {
          const payload = item.businessData || {};
          serverEntityId = `draft-${Date.now()}`;
          successMessage = `Customer cart / order draft containing ${payload.items?.length || 0} items safely synced to cloud backup.`;
          break;
        }

        default: {
          serverEntityId = `gen-${Date.now()}`;
          successMessage = `Action ${item.actionType} successfully committed.`;
          break;
        }
      }

      // Record in Idempotency Store
      syncIdempotencyDb.set(idempotencyKey, {
        idempotencyKey,
        actionType: item.actionType,
        userId: user?.id || "anonymous",
        deviceId: item.deviceId,
        statusCode: 200,
        responseBody: { success: true, serverEntityId, message: successMessage },
        processedAt: now,
        serverEntityId
      });

      // Record in Activity Log
      syncActivityLogsDb.unshift({
        id: `slog-${Date.now()}-${Math.floor(Math.random() * 100)}`,
        actionType: item.actionType,
        idempotencyKey,
        userId: user?.id || "anonymous",
        status: "SUCCESS",
        message: successMessage,
        deviceTimestamp: item.createdAt || now,
        serverProcessedAt: now,
        details: { serverEntityId, businessData: item.businessData }
      });

      return {
        id: item.id,
        idempotencyKey,
        actionType: item.actionType,
        status: "SYNCED",
        isIdempotencyReplay: false,
        serverConfirmedAt: now,
        serverEntityId,
        message: successMessage
      };
    } catch (err: any) {
      return {
        id: item.id,
        idempotencyKey,
        actionType: item.actionType,
        status: "FAILED",
        isIdempotencyReplay: false,
        serverConfirmedAt: now,
        message: "Server exception occurred during sync processing.",
        errorMessage: err.message || "Unknown server execution error."
      };
    }
  }

  // 1. Process Single Sync Item
  app.post("/api/v1/sync/process-item", (req: AuthenticatedRequest, res) => {
    const item = req.body;
    if (!item || !item.actionType) {
      return res.status(400).json({
        statusCode: 400,
        error: "Bad Request",
        message: "Invalid sync item: actionType is required."
      });
    }

    const result = processSyncItemInternal(item, req.user);
    if (result.isIdempotencyReplay) {
      res.setHeader("X-Idempotency-Replayed", "1");
    }

    res.json({
      statusCode: result.status === "CONFLICT" ? 409 : (result.status === "FAILED" ? 422 : 200),
      data: result
    });
  });

  // 2. Batch Sync Process Endpoint
  app.post("/api/v1/sync/batch", (req: AuthenticatedRequest, res) => {
    const { items = [], deviceId = "DEV-BROWSER-CLIENT", clientTimestamp = new Date().toISOString() } = req.body;

    if (!Array.isArray(items) || items.length === 0) {
      return res.json({
        statusCode: 200,
        batchId: `batch-empty-${Date.now()}`,
        processedCount: 0,
        successCount: 0,
        replayCount: 0,
        failureCount: 0,
        conflictCount: 0,
        results: [],
        timestamp: new Date().toISOString()
      });
    }

    const batchId = `batch-${Date.now()}-${Math.floor(Math.random() * 1000)}`;
    const results: any[] = [];
    let successCount = 0;
    let replayCount = 0;
    let failureCount = 0;
    let conflictCount = 0;

    // Process items in chronological sequence
    const sortedItems = [...items].sort((a, b) => new Date(a.createdAt || 0).getTime() - new Date(b.createdAt || 0).getTime());

    for (const item of sortedItems) {
      const resItem = processSyncItemInternal(item, req.user);
      results.push(resItem);

      if (resItem.status === "SYNCED") {
        if (resItem.isIdempotencyReplay) replayCount++;
        else successCount++;
      } else if (resItem.status === "CONFLICT") {
        conflictCount++;
      } else {
        failureCount++;
      }
    }

    res.json({
      statusCode: 200,
      batchId,
      processedCount: items.length,
      successCount,
      replayCount,
      failureCount,
      conflictCount,
      results,
      timestamp: new Date().toISOString()
    });
  });

  // 3. Sync Activity & Audit Logs
  app.get("/api/v1/sync/activity", (req: AuthenticatedRequest, res) => {
    const { actionType, status, limit = 50 } = req.query;

    let filtered = [...syncActivityLogsDb];
    if (actionType) {
      filtered = filtered.filter(l => l.actionType === actionType);
    }
    if (status) {
      filtered = filtered.filter(l => l.status === status);
    }

    res.json({
      statusCode: 200,
      data: {
        totalRecords: filtered.length,
        logs: filtered.slice(0, Number(limit)),
        idempotencyStoreSize: syncIdempotencyDb.size
      }
    });
  });

  // 4. Interactive Conflict Resolution
  app.post("/api/v1/sync/resolve-conflict", (req: AuthenticatedRequest, res) => {
    const { itemId, resolution, customMergedData, ticketId } = req.body;

    if (!itemId || !resolution) {
      return res.status(400).json({ statusCode: 400, error: "Bad Request", message: "itemId and resolution type ('SERVER_WINS' | 'CLIENT_CHANGE_ACCEPTED' | 'MERGE_FIELDS') are required." });
    }

    const now = new Date().toISOString();
    let appliedMessage = `Conflict for item ${itemId} resolved via ${resolution}.`;

    if (ticketId && (resolution === "CLIENT_CHANGE_ACCEPTED" || resolution === "MERGE_FIELDS")) {
      const ticket = serviceTicketsDb.find(t => t.id === ticketId || t.ticketNumber === ticketId);
      if (ticket) {
        ticket.notes.unshift({
          id: `not-res-${Date.now()}`,
          ticketId: ticket.id,
          authorId: req.user?.id || "u-smgr-01",
          authorName: req.user?.email || "Service Operations Manager",
          authorRole: "SERVICE_MANAGER",
          noteType: "INTERNAL",
          content: `[CONFLICT RESOLVED]: Manually applied resolution strategy '${resolution}'. ${customMergedData?.notes || ''}`,
          createdAt: now
        });
        ticket.updatedAt = now;
      }
    }

    syncActivityLogsDb.unshift({
      id: `slog-res-${Date.now()}`,
      actionType: "CONFLICT_RESOLUTION",
      idempotencyKey: `RESOLVE-${itemId}-${Date.now()}`,
      userId: req.user?.id || "u-smgr-01",
      status: "SUCCESS",
      message: appliedMessage,
      deviceTimestamp: now,
      serverProcessedAt: now,
      details: { itemId, resolution, customMergedData }
    });

    res.json({
      statusCode: 200,
      message: appliedMessage,
      data: { itemId, resolution, resolvedAt: now }
    });
  });

