  app.post("/api/v1/background-jobs/create", (req: AuthenticatedRequest, res) => {
    const { jobType, title, payloadSummary } = req.body;

    const newJob: any = {
      id: `job-${Date.now()}-${Math.floor(Math.random() * 1000)}`,
      jobType: jobType || "DATABASE_INTEGRITY_CHECK",
      title: title || "Automated Operational Task",
      status: "PROCESSING",
      progressPercent: 15,
      idempotencyKey: `idemp-${Date.now()}-${Math.random().toString(36).substring(7)}`,
      startedAt: new Date().toISOString(),
      retryCount: 0,
      maxRetries: 3,
      payloadSummary: payloadSummary || "Executing in safe background queue.",
      triggeredByUserName: req.user?.email || "System Operator",
      triggeredByUserRole: (req.user as any)?.role || (req.user as any)?.roleType || "OFFICE_ADMIN",
      createdAt: new Date().toISOString()
    };

    backgroundJobsDb.unshift(newJob);

    // Simulate async completion
    setTimeout(() => {
      newJob.status = "COMPLETED";
      newJob.progressPercent = 100;
      newJob.completedAt = new Date().toISOString();
      newJob.durationMs = 4500;
    }, 4000);

    logAudit(req, "BACKGROUND_JOB_DISPATCHED", "SYSTEM_HEALTH", "SUCCESS", {
      details: { jobId: newJob.id, jobType: newJob.jobType, title: newJob.title }
    });

    res.status(201).json({
      statusCode: 201,
      message: "Background job queued and running.",
      data: newJob
    });
  });

  app.post("/api/v1/background-jobs/:id/retry", (req: AuthenticatedRequest, res) => {
    const { id } = req.params;
    const job = backgroundJobsDb.find(j => j.id === id);

    if (!job) {
      return res.status(404).json({ statusCode: 404, message: "Job not found." });
    }

    job.status = "RETRYING";
    job.retryCount += 1;
    job.progressPercent = 35;
    job.startedAt = new Date().toISOString();

    setTimeout(() => {
      job.status = "COMPLETED";
      job.progressPercent = 100;
      job.completedAt = new Date().toISOString();
      job.durationMs = 6200;
    }, 3000);

    logAudit(req, "BACKGROUND_JOB_RETRIED", "SYSTEM_HEALTH", "SUCCESS", {
      details: { jobId: job.id, retryCount: job.retryCount }
    });

    res.json({
      statusCode: 200,
      message: "Background job retrying.",
      data: job
    });
  });

  // ----------------------------------------------------------------------------
  // 5. GLOBAL SEARCH API (PHASE BO-6)
  // ----------------------------------------------------------------------------
  app.get("/api/v1/global-search", (req: AuthenticatedRequest, res) => {
    const query = req.query.q ? String(req.query.q).toLowerCase().trim() : "";
    if (!query || query.length < 2) {
      return res.json({ statusCode: 200, results: [] });
    }

    const results: any[] = [];

    // Search Customers
    usersDb.forEach(u => {
      if (u.roleType === UserRoleType.CUSTOMER) {
        const labName = u.customerProfile?.labName || "";
        const code = u.customerProfile?.customerCode || "";
        const phone = u.phoneNumber || "";
        const name = `${u.firstName} ${u.lastName}`;

        if (labName.toLowerCase().includes(query) || code.toLowerCase().includes(query) || phone.includes(query) || name.toLowerCase().includes(query)) {
          results.push({
            id: u.id,
            category: "CUSTOMER",
            title: labName || name,
            subtitle: `Code: ${code || 'N/A'} • Contact: ${name} (${phone})`,
            badge: "Diagnostic Lab",
            tab: "users",
            metadata: { creditLimit: u.customerProfile?.creditLimit, gst: u.customerProfile?.gstNumber }
          });
        }
      }
    });

    // Search Orders
    if (customerOrdersDb) {
      customerOrdersDb.forEach((o: any) => {
        const num = o.orderNumber || o.id || "";
        const lab = o.customerLabName || "";
        if (num.toLowerCase().includes(query) || lab.toLowerCase().includes(query)) {
          results.push({
            id: o.id,
            category: "ORDER",
            title: `Order #${num}`,
            subtitle: `${lab} • ₹${Number(o.totalAmount || 0).toLocaleString('en-IN')} • ${o.status}`,
            badge: o.status,
            tab: "admin_orders",
            metadata: { total: o.totalAmount, date: o.createdAt }
          });
        }
      });
    }

    // Search Products
    productsDb.forEach((p: any) => {
      const name = p.name || "";
      const sku = p.sku || "";
      const code = p.productCode || p.sku || "";
      if (name.toLowerCase().includes(query) || sku.toLowerCase().includes(query) || code.toLowerCase().includes(query)) {
        results.push({
          id: p.id,
          category: "PRODUCT",
          title: name,
          subtitle: `SKU: ${sku} • Type: ${p.productType} • MRP: ₹${p.mrp}`,
          badge: p.productType,
          tab: "products",
          metadata: { mrp: p.mrp, brand: p.companyName || p.companyId }
        });
      }
    });

    // Search Service Tickets & Complaints
    if (serviceTicketsDb) {
      serviceTicketsDb.forEach(t => {
        const num = t.ticketNumber || "";
        const lab = t.customerLabName || "";
        const title = t.title || "";
        const serial = t.equipmentSerial || "";
        if (num.toLowerCase().includes(query) || lab.toLowerCase().includes(query) || title.toLowerCase().includes(query) || serial.toLowerCase().includes(query)) {
          results.push({
            id: t.id,
            category: "SERVICE_TICKET",
            title: `Ticket #${num} - ${title}`,
            subtitle: `${lab} • Serial: ${serial || 'N/A'} • Priority: ${t.priority}`,
            badge: t.status,
            tab: "service_engineer",
            metadata: { priority: t.priority, status: t.status }
          });
        }
      });
    }

    // Search Equipment
    if (customerEquipmentDb) {
      customerEquipmentDb.forEach((e: any) => {
        const name = e.equipmentName || "";
        const serial = e.serialNumber || "";
        const lab = e.customerLabName || "";
        if (name.toLowerCase().includes(query) || serial.toLowerCase().includes(query) || lab.toLowerCase().includes(query)) {
          results.push({
            id: e.id,
            category: "EQUIPMENT",
            title: `${name}`,
            subtitle: `Serial: ${serial} • Installed at: ${lab} • Health: ${e.healthScore}%`,
            badge: e.status,
            tab: "preventive_maintenance",
            metadata: { serial, healthScore: e.healthScore }
          });
        }
      });
    }

    // Search Security & Session keywords
    if ("security sessions active logins devices remote terminate kill logout".includes(query) || query.includes("session") || query.includes("device") || query.includes("login")) {
      results.push({
        id: "nav-sec-sessions",
        category: "SECURITY",
        title: "Security Sessions & Remote Kill Dashboard",
        subtitle: "View active device logins (Desktop, iOS, Android, iPad) and remotely terminate sessions",
        badge: "Security",
        tab: "security_sessions",
        metadata: { activeSessions: userSessionsDb.filter(s => !s.isRevoked).length }
      });
    }

    res.json({
      statusCode: 200,
      totalResults: results.length,
      results: results.slice(0, 15)
    });
  });

  // ----------------------------------------------------------------------------
  // 6. CUSTOMER 360 COMPREHENSIVE PROFILE API (PHASE BO-4)
  // ----------------------------------------------------------------------------
  app.get("/api/v1/customers/:id/360", authenticateJwt as any, (req: AuthenticatedRequest, res) => {
    const { id } = req.params;
    const user = usersDb.find(u => u.id === id);

    if (!user) {
      return res.status(404).json({ statusCode: 404, message: "Customer not found." });
    }

    // Role-based customer ownership check
    if (req.user?.roleType === UserRoleType.CUSTOMER) {
      const isOwner = req.user.id === id || 
        (Boolean(req.user.labId) && req.user.labId === id) || 
        user.id === req.user.id || 
        (Boolean(req.user.labId) && Boolean(user.labId) && user.labId === req.user.labId);
      if (!isOwner) {
        return res.status(403).json({
          statusCode: 403,
          error: "Forbidden",
          message: "Access Denied: You cannot view customer profile records for another customer."
        });
      }
    } else {
      const authorizedBackofficeRoles: UserRoleType[] = [
        UserRoleType.SUPER_ADMIN,
        UserRoleType.OFFICE_ADMIN,
        UserRoleType.OFFICE_STAFF,
        UserRoleType.SALES_MANAGER,
        UserRoleType.SALES_PERSON,
        UserRoleType.ACCOUNTS_STAFF,
        UserRoleType.SERVICE_MANAGER
      ];
      if (!req.user || !authorizedBackofficeRoles.includes(req.user.roleType)) {
        return res.status(403).json({
          statusCode: 403,
          error: "Forbidden",
          message: "Access restricted to authorized personnel."
        });
      }
    }

    const orders = customerOrdersDb ? customerOrdersDb.filter((o: any) => o.customerId === id) : [];
    const equipment = customerEquipmentDb ? customerEquipmentDb.filter((e: any) => e.customerId === id) : [];
    const serviceTickets = serviceTicketsDb ? serviceTicketsDb.filter((t: any) => t.customerId === id) : [];
    const priceRules = customerPriceRulesDb ? customerPriceRulesDb.filter((r: any) => r.customerId === id) : [];

    const customer360 = {
      overview: {
        userId: user.id,
        email: user.email,
        phoneNumber: user.phoneNumber,
        contactPerson: `${user.firstName} ${user.lastName}`,
        labName: user.customerProfile?.labName || `${user.firstName}'s Diagnostic Lab`,
        customerCode: user.customerProfile?.customerCode || "CUST-MH-001",
        customerType: user.customerProfile?.customerType || "HOSPITAL_LAB",
        gstNumber: user.customerProfile?.gstNumber || "27AABCM8921N1ZM",
        drugLicenseNumber: user.customerProfile?.drugLicenseNumber || "MH-TZ2-449102",
        creditLimit: user.customerProfile?.creditLimit || 250000,
        creditPeriodDays: user.customerProfile?.creditPeriodDays || 45,
        currentOutstanding: user.customerProfile?.currentOutstanding || 42150,
        availableCredit: (user.customerProfile?.creditLimit || 250000) - (user.customerProfile?.currentOutstanding || 42150),
        status: user.status,
        isApproved: user.customerProfile?.isApproved ?? true,
        createdAt: user.createdAt
      },
      ordersSummary: {
        totalOrders: orders.length,
        lifetimeValue: orders.reduce((acc: number, o: any) => acc + (Number(o.totalAmount) || 0), 0),
        ordersList: orders.slice(0, 10)
      },
      installedEquipment: equipment,
      serviceTickets: serviceTickets,
      customPricing: priceRules,
      recentActivity: [
        { title: "Placed Consumable Order #ORD-2026-0891", timestamp: new Date(Date.now() - 86400000).toISOString() },
        { title: "Service Ticket #TCK-2026-0014 Lamp Absorbance Check In-Progress", timestamp: new Date(Date.now() - 172800000).toISOString() },
        { title: "NEFT Payment Verified (₹45,000)", timestamp: new Date(Date.now() - 432000000).toISOString() }
      ]
    };

    res.json({
      statusCode: 200,
      data: customer360
    });
  });

