  // Helper: Haversine distance in meters
  function calculateHaversineDistanceMeters(lat1: number, lon1: number, lat2: number, lon2: number): number {
    const R = 6371e3;
    const φ1 = (lat1 * Math.PI) / 180;
    const φ2 = (lat2 * Math.PI) / 180;
    const Δφ = ((lat2 - lat1) * Math.PI) / 180;
    const Δλ = ((lon2 - lon1) * Math.PI) / 180;

    const a =
      Math.sin(Δφ / 2) * Math.sin(Δφ / 2) +
      Math.cos(φ1) * Math.cos(φ2) * Math.sin(Δλ / 2) * Math.sin(Δλ / 2);
    const c = 2 * Math.atan2(Math.sqrt(a), Math.sqrt(1 - a));

    return Math.round(R * c);
  }

  // Helper: Evaluate geofence compliance
  function evaluateAttendanceGeofence(
    policy: string,
    coords?: { latitude: number; longitude: number; accuracyMeters?: number }
  ): {
    isValid: boolean;
    withinGeofence: boolean;
    distanceMeters: number;
    officeName?: string;
    locationType: 'OFFICE' | 'FIELD' | 'CUSTOMER_SITE' | 'NO_LOCATION';
    reason?: string;
  } {
    if (policy === "NO_LOCATION") {
      return {
        isValid: true,
        withinGeofence: true,
        distanceMeters: 0,
        locationType: "NO_LOCATION",
        officeName: "Exempt / Remote Policy"
      };
    }

    if (!coords || typeof coords.latitude !== "number" || typeof coords.longitude !== "number") {
      return {
        isValid: false,
        withinGeofence: false,
        distanceMeters: 0,
        locationType: "NO_LOCATION",
        reason: "Valid GPS Coordinates are required by organization policy for this role."
      };
    }

    if (policy === "FIELD_ANYWHERE") {
      return {
        isValid: true,
        withinGeofence: true,
        distanceMeters: 0,
        locationType: "FIELD",
        officeName: "Authorized Field Territory"
      };
    }

    if (policy === "OFFICE_GEOFENCE") {
      let closestOffice: OfficeGeofence | null = null;
      let minDistance = Infinity;

      for (const off of officeLocationsDb) {
        const dist = calculateHaversineDistanceMeters(coords.latitude, coords.longitude, off.latitude, off.longitude);
        if (dist < minDistance) {
          minDistance = dist;
          closestOffice = off;
        }
      }

      if (closestOffice && minDistance <= closestOffice.radiusMeters) {
        return {
          isValid: true,
          withinGeofence: true,
          distanceMeters: minDistance,
          officeName: closestOffice.name,
          locationType: "OFFICE"
        };
      } else {
        return {
          isValid: false,
          withinGeofence: false,
          distanceMeters: minDistance,
          officeName: closestOffice ? closestOffice.name : "Registered Office",
          locationType: "OFFICE",
          reason: `Current coordinates are ${minDistance}m from ${closestOffice ? closestOffice.name : 'office'} (Allowed geofence radius: ${closestOffice?.radiusMeters || 200}m).`
        };
      }
    }

    return {
      isValid: true,
      withinGeofence: true,
      distanceMeters: 0,
      locationType: "FIELD"
    };
  }

  // Format minutes into "8h 15m"
  function formatMinutesToDuration(totalMinutes: number): string {
    if (!totalMinutes || totalMinutes <= 0) return "0h 00m";
    const hours = Math.floor(totalMinutes / 60);
    const mins = Math.floor(totalMinutes % 60);
    return `${hours}h ${mins.toString().padStart(2, "0")}m`;
  }

